window.GITA_CHAPTERS = {"1": {"name": "Arjun-Vishad", "title": "The Book of the Distress of Arjuna"}, "2": {"name": "Sankhya-Yog", "title": "The Book of Doctrines"}, "3": {"name": "Karma-Yog", "title": "The Book of Virtue in Work"}, "4": {"name": "Jnana Yog", "title": "The Book of the Religion of Knowledge"}, "5": {"name": "Karmasanyasayog", "title": "The Book of Religion by Renouncing Fruit of Works"}, "6": {"name": "Atmasanyamayog", "title": "The Book of Religion by Self-Restraint"}, "7": {"name": "Vijnanayog", "title": "The Book of Religion by Discernment"}, "8": {"name": "Aksharaparabrahmayog", "title": "The Book of Religion by Devotion to the One Supreme God"}, "9": {"name": "Rajavidyarajaguhyayog", "title": "The Book of Religion by the Kingly Knowledge and the Kingly Mystery"}, "10": {"name": "Vibhuti Yog", "title": "The Book of Religion by the Heavenly Perfections"}, "11": {"name": "Viswarupadarsanam", "title": "The Book of the Manifesting of the One and Manifold"}, "12": {"name": "Bhaktiyog", "title": "The Book of the Religion of Faith"}, "13": {"name": "Kshetrakshetrajnavibhagayog", "title": "The Book of Religion by Separation of Matter and Spirit"}, "14": {"name": "Gunatrayavibhagayog", "title": "The Book of Religion by Separation from the Qualities"}, "15": {"name": "Purushottamapraptiyog", "title": "The Book of Religion by Attaining the Supreme"}, "16": {"name": "Daivasarasaupadwibhagayog", "title": "The Book of the Separateness of the Divine and Undivine"}, "17": {"name": "Sraddhatrayavibhagayog", "title": "The Book of Religion by the Threefold Kinds of Faith"}, "18": {"name": "Mokshasanyasayog", "title": "The Book of Religion by Deliverance and Renunciation"}};
window.GITA_VERSES = [
{"c":1,"v":1,"d":"धृतराष्ट्र उवाच\nधर्मक्षेत्रे कुरुक्षेत्रे समवेता युयुत्सवः।\nमामकाः पाण्डवाश्चैव किमकुर्वत सञ्जय॥","t":"dhṛtarāṣṭra uvāca\ndharmakṣetre kurukṣetre samavetā yuyutsavaḥ|\nmāmakāḥ pāṇḍavāścaiva kimakurvata sañjaya||","e":"Dhritirashtra:\nRanged thus for battle on the sacred plain--\nOn Kurukshetra--say, Sanjaya! say\nWhat wrought my people, and the Pandavas?"},
{"c":1,"v":2,"d":"सञ्जय उवाच\nदृष्ट्वा तु पाण्डवानीकं व्यूढं दुर्योधनस्तदा।\nआचार्यमुपसङ्गम्य राजा वचनमब्रवीत्॥","t":"sañjaya uvāca\ndṛṣṭvā tu pāṇḍavānīkaṃ vyūḍhaṃ duryodhanastadā|\nācāryamupasaṅgamya rājā vacanamabravīt||","e":"Sanjaya:\nWhen he beheld the host of Pandavas,\nRaja Duryodhana to Drona drew,\nAnd spake these words:"},
{"c":1,"v":3,"d":"पश्यैतां पाण्डुपुत्राणामाचार्य महतीं चमूम्।\nव्यूढां द्रुपदपुत्रेण तव शिष्येण धीमता॥","t":"paśyaitāṃ pāṇḍuputrāṇāmācārya mahatīṃ camūm|\nvyūḍhāṃ drupadaputreṇa tava śiṣyeṇa dhīmatā||","e":"\"Ah, Guru! see this line,\nHow vast it is of Pandu fighting-men,\nEmbattled by the son of Drupada,\nThy scholar in the war!"},
{"c":1,"v":4,"d":"अत्र शूरा महेष्वासा भीमार्जुनसमा युधि।\nयुयुधानो विराटश्च द्रुपदश्च महारथः॥","t":"atra śūrā maheṣvāsā bhīmārjunasamā yudhi|\nyuyudhāno virāṭaśca drupadaśca mahārathaḥ||","e":"Therein stand ranked\nChiefs like Arjuna, like to Bhima chiefs,\nBenders of bows; Virata, Yuyudhan,\nDrupada, eminent upon his car,"},
{"c":1,"v":5,"d":"धृष्टकेतुश्चेकितानः काशिराजश्च वीर्यवान्।\nपुरुजित्कुन्तिभोजश्च शैब्यश्च नरपुङ्गवः॥","t":"dhṛṣṭaketuścekitānaḥ kāśirājaśca vīryavān|\npurujitkuntibhojaśca śaibyaśca narapuṅgavaḥ||","e":"Dhrishtaket, Chekitan, Kasi's stout lord,\nPurujit, Kuntibhoj, and Saivya,"},
{"c":1,"v":6,"d":"युधामन्युश्च विक्रान्त उत्तमौजाश्च वीर्यवान्।\nसौभद्रो द्रौपदेयाश्च सर्व एव महारथाः॥","t":"yudhāmanyuśca vikrānta uttamaujāśca vīryavān|\nsaubhadro draupadeyāśca sarva eva mahārathāḥ||","e":"With Yudhamanyu, and Uttamauj\nSubhadra's child; and Drupadi's;-all famed!\nAll mounted on their shining chariots!"},
{"c":1,"v":7,"d":"अस्माकं तु विशिष्टा ये तान्निबोध द्विजोत्तम।\nनायका मम सैन्यस्य संज्ञार्थं तान्ब्रवीमि ते॥","t":"asmākaṃ tu viśiṣṭā ye tānnibodha dvijottama|\nnāyakā mama sainyasya saṃjñārthaṃ tānbravīmi te||","e":"On our side, too,--thou best of Brahmans! see\nExcellent chiefs, commanders of my line,\nWhose names I joy to count:"},
{"c":1,"v":8,"d":"भवान्भीष्मश्च कर्णश्च कृपश्च समितिञ्जयः।\nअश्वत्थामा विकर्णश्च सौमदत्तिस्तथैव च॥","t":"bhavānbhīṣmaśca karṇaśca kṛpaśca samitiñjayaḥ|\naśvatthāmā vikarṇaśca saumadattistathaiva ca||","e":"thyself the first,\nThen Bhishma, Karna, Kripa fierce in fight,\nVikarna, Aswatthaman; next to these\nStrong Saumadatti,"},
{"c":1,"v":9,"d":"अन्ये च बहवः शूरा मदर्थे त्यक्तजीविताः।\nनानाशस्त्रप्रहरणाः सर्वे युद्धविशारदाः॥","t":"anye ca bahavaḥ śūrā madarthe tyaktajīvitāḥ|\nnānāśastrapraharaṇāḥ sarve yuddhaviśāradāḥ||","e":"with full many more\nValiant and tried, ready this day to die\nFor me their king, each with his weapon grasped,\nEach skilful in the field."},
{"c":1,"v":10,"d":"अपर्याप्तं तदस्माकं बलं भीष्माभिरक्षितम्।\nपर्याप्तं त्विदमेतेषां बलं भीमाभिरक्षितम्॥","t":"aparyāptaṃ tadasmākaṃ balaṃ bhīṣmābhirakṣitam|\nparyāptaṃ tvidameteṣāṃ balaṃ bhīmābhirakṣitam||","e":"Weakest-meseems-\nOur battle shows where Bhishma holds command,\nAnd Bhima, fronting him, something too strong!"},
{"c":1,"v":11,"d":"अयनेषु च सर्वेषु यथाभागमवस्थिताः।\nभीष्ममेवाभिरक्षन्तु भवन्तः सर्व एव हि॥","t":"ayaneṣu ca sarveṣu yathābhāgamavasthitāḥ|\nbhīṣmamevābhirakṣantu bhavantaḥ sarva eva hi||","e":"Have care our captains nigh to Bhishma's ranks\nPrepare what help they may! Now, blow my shell!\""},
{"c":1,"v":12,"d":"तस्य संजनयन्हर्षं कुरुवृद्धः पितामहः।\nसिंहनादं विनद्योच्चैः शङ्खं दध्मौ प्रतापवान्॥","t":"tasya saṃjanayanharṣaṃ kuruvṛddhaḥ pitāmahaḥ|\nsiṃhanādaṃ vinadyoccaiḥ śaṅkhaṃ dadhmau pratāpavān||","e":"Then, at the signal of the aged king,\nWith blare to wake the blood, rolling around\nLike to a lion's roar, the trumpeter\nBlew the great Conch;"},
{"c":1,"v":13,"d":"ततः शङ्खाश्च भेर्यश्च पणवानकगोमुखाः।\nसहसैवाभ्यहन्यन्त स शब्दस्तुमुलोऽभवत्॥","t":"tataḥ śaṅkhāśca bheryaśca paṇavānakagomukhāḥ|\nsahasaivābhyahanyanta sa śabdastumulo'bhavat||","e":"and, at the noise of it,\nTrumpets and drums, cymbals and gongs and horns\nBurst into sudden clamour; as the blasts\nOf loosened tempest, such the tumult seemed!"},
{"c":1,"v":14,"d":"ततः श्वेतैर्हयैर्युक्ते महति स्यन्दने स्थितौ।\nमाधवः पाण्डवश्चैव दिव्यौ शङ्खौ प्रदध्मतुः॥","t":"tataḥ śvetairhayairyukte mahati syandane sthitau|\nmādhavaḥ pāṇḍavaścaiva divyau śaṅkhau pradadhmatuḥ||","e":"Then might be seen, upon their car of gold\nYoked with white steeds, blowing their battle-shells,\nKrishna the God, Arjuna at his side:"},
{"c":1,"v":15,"d":"पाञ्चजन्यं हृषीकेशो देवदत्तं धनंजयः।\nपौण्ड्रं दध्मौ महाशङ्खं भीमकर्मा वृकोदरः॥","t":"pāñcajanyaṃ hṛṣīkeśo devadattaṃ dhanaṃjayaḥ|\npauṇḍraṃ dadhmau mahāśaṅkhaṃ bhīmakarmā vṛkodaraḥ||","e":"Krishna, with knotted locks, blew his great conch\nCarved of the \"Giant's bone;\" Arjuna blew\nIndra's loud gift; Bhima the terrible--\nWolf-bellied Bhima-blew a long reed-conch;"},
{"c":1,"v":16,"d":"अनन्तविजयं राजा कुन्तीपुत्रो युधिष्ठिरः।\nनकुलः सहदेवश्च सुघोषमणिपुष्पकौ॥","t":"anantavijayaṃ rājā kuntīputro yudhiṣṭhiraḥ|\nnakulaḥ sahadevaśca sughoṣamaṇipuṣpakau||","e":"And Yudhisthira, Kunti's blameless son,\nWinded a mighty shell, \"Victory's Voice;\"\nAnd Nakula blew shrill upon his conch\nNamed the \"Sweet-sounding,\" Sahadev on his\nCalled\"Gem-bedecked,\""},
{"c":1,"v":17,"d":"काश्यश्च परमेष्वासः शिखण्डी च महारथः।\nधृष्टद्युम्नो विराटश्च सात्यकिश्चापराजितः॥","t":"kāśyaśca parameṣvāsaḥ śikhaṇḍī ca mahārathaḥ|\ndhṛṣṭadyumno virāṭaśca sātyakiścāparājitaḥ||","e":"and Kasi's Prince on his.\nSikhandi on his car, Dhrishtadyumn,\nVirata, Satyaki the Unsubdued,"},
{"c":1,"v":18,"d":"द्रुपदो द्रौपदेयाश्च सर्वशः पृथिवीपते।\nसौभद्रश्च महाबाहुः शङ्खान्दध्मुः पृथक्पृथक्॥","t":"drupado draupadeyāśca sarvaśaḥ pṛthivīpate|\nsaubhadraśca mahābāhuḥ śaṅkhāndadhmuḥ pṛthakpṛthak||","e":"Drupada, with his sons, (O Lord of Earth!)\nLong-armed Subhadra's children, all blew loud,"},
{"c":1,"v":19,"d":"स घोषो धार्तराष्ट्राणां हृदयानि व्यदारयत्।\nनभश्च पृथिवीं चैव तुमुलो व्यनुनादयन्॥","t":"sa ghoṣo dhārtarāṣṭrāṇāṃ hṛdayāni vyadārayat|\nnabhaśca pṛthivīṃ caiva tumulo vyanunādayan||","e":"So that the clangour shook their foemen's hearts,\nWith quaking earth and thundering heav'n."},
{"c":1,"v":20,"d":"अथ व्यवस्थितान् दृष्ट्वा धार्तराष्ट्रान्कपिध्वजः।\nप्रवृत्ते शस्त्रसंपाते धनुरुद्यम्य पाण्डवः॥","t":"atha vyavasthitān dṛṣṭvā dhārtarāṣṭrānkapidhvajaḥ|\npravṛtte śastrasaṃpāte dhanurudyamya pāṇḍavaḥ||","e":"Then 'twas-\nBeholding Dhritirashtra's battle set,\nWeapons unsheathing, bows drawn forth, the war\nInstant to break-Arjun, whose ensign-badge\nWas Hanuman the monkey, spake this thing\nTo Krishna the Divine, his charioteer:"},
{"c":1,"v":21,"d":"अर्जुन उवाच\nहृषीकेशं तदा वाक्यमिदमाह महीपते।\nसेनयोरुभयोर्मध्ये रथं स्थापय मेऽच्युत॥","t":"arjuna uvāca\nhṛṣīkeśaṃ tadā vākyamidamāha mahīpate|\nsenayorubhayormadhye rathaṃ sthāpaya me'cyuta||","e":"\"Drive, Dauntless One! to yonder open ground\nBetwixt the armies;"},
{"c":1,"v":22,"d":"यावदेतान्निरीक्षेऽहं योद्धुकामानवस्थितान्।\nकैर्मया सह योद्धव्यमस्मिन्रणसमुद्यमे॥","t":"yāvadetānnirīkṣe'haṃ yoddhukāmānavasthitān|\nkairmayā saha yoddhavyamasminraṇasamudyame||","e":"I would see more nigh\nThese who will fight with us, those we must slay\nTo-day, in war's arbitrament;"},
{"c":1,"v":23,"d":"योत्स्यमानानवेक्षेऽहं य एतेऽत्र समागताः।\nधार्तराष्ट्रस्य दुर्बुद्धेर्युद्धे प्रियचिकीर्षवः॥","t":"yotsyamānānavekṣe'haṃ ya ete'tra samāgatāḥ|\ndhārtarāṣṭrasya durbuddheryuddhe priyacikīrṣavaḥ||","e":"for, sure,\nOn bloodshed all are bent who throng this plain,\nObeying Dhritirashtra's sinful son.\""},
{"c":1,"v":24,"d":"संजय उवाच\nएवमुक्तो हृषीकेशो गुडाकेशेन भारत।\nसेनयोरुभयोर्मध्ये स्थापयित्वा रथोत्तमम्॥","t":"saṃjaya uvāca\nevamukto hṛṣīkeśo guḍākeśena bhārata|\nsenayorubhayormadhye sthāpayitvā rathottamam||","e":"Thus, by Arjuna prayed, (O Bharata!)\nBetween the hosts that heavenly Charioteer\nDrove the bright car, reining its milk-white steeds"},
{"c":1,"v":25,"d":"भीष्मद्रोणप्रमुखतः सर्वेषां च महीक्षिताम्।\nउवाच पार्थ पश्यैतान्समवेतान्कुरूनिति॥","t":"bhīṣmadroṇapramukhataḥ sarveṣāṃ ca mahīkṣitām|\nuvāca pārtha paśyaitānsamavetānkurūniti||","e":"Where Bhishma led,and Drona,and their Lords.\n\"See!\" spake he to Arjuna, \"where they stand,\nThy kindred of the Kurus:\""},
{"c":1,"v":26,"d":"तत्रापश्यत्स्थितान्पार्थः पितृ़नथ पितामहान्।\nआचार्यान्मातुलान्भ्रातृ़न्पुत्रान्पौत्रान्सखींस्तथा॥","t":"tatrāpaśyatsthitānpārthaḥ pitṛnatha pitāmahān|\nācāryānmātulānbhrātṛnputrānpautrānsakhīṃstathā||","e":"and the Prince\nMarked on each hand the kinsmen of his house,\nGrandsires and sires, uncles and brothers and sons,\nCousins and sons-in-law and nephews, mixed\nWith friends and honoured elders; some this side,\nSome that side ranged: and, seeing those opposed,\nSuch kith grown enemies-Arjuna's heart\nMelted with pity, while he uttered this:","g":[26,27]},
{"c":1,"v":27,"d":"श्वशुरान्सुहृदश्चैव सेनयोरुभयोरपि।\nतान्समीक्ष्य स कौन्तेयः सर्वान्बन्धूनवस्थितान्॥","t":"śvaśurānsuhṛdaścaiva senayorubhayorapi|\ntānsamīkṣya sa kaunteyaḥ sarvānbandhūnavasthitān||","e":"and the Prince\nMarked on each hand the kinsmen of his house,\nGrandsires and sires, uncles and brothers and sons,\nCousins and sons-in-law and nephews, mixed\nWith friends and honoured elders; some this side,\nSome that side ranged: and, seeing those opposed,\nSuch kith grown enemies-Arjuna's heart\nMelted with pity, while he uttered this:","g":[26,27]},
{"c":1,"v":28,"d":"अर्जुन उवाच\nकृपया परयाऽऽविष्टो विषीदन्निदमब्रवीत्।\nदृष्ट्वेमं स्वजनं कृष्ण युयुत्सुं समुपस्थितम्॥","t":"arjuna uvāca\nkṛpayā parayā''viṣṭo viṣīdannidamabravīt|\ndṛṣṭvemaṃ svajanaṃ kṛṣṇa yuyutsuṃ samupasthitam||","e":"Arjuna.\nKrishna! as I behold, come here to shed\nTheir common blood, yon concourse of our kin,"},
{"c":1,"v":29,"d":"सीदन्ति मम गात्राणि मुखं च परिशुष्यति।\nवेपथुश्च शरीरे मे रोमहर्षश्च जायते॥","t":"sīdanti mama gātrāṇi mukhaṃ ca pariśuṣyati|\nvepathuśca śarīre me romaharṣaśca jāyate||","e":"My members fail, my tongue dries in my mouth,\nA shudder thrills my body, and my hair\nBristles with horror;"},
{"c":1,"v":30,"d":"गाण्डीवं स्रंसते हस्तात्त्वक्चैव परिदह्यते।\nन च शक्नोम्यवस्थातुं भ्रमतीव च मे मनः॥","t":"gāṇḍīvaṃ sraṃsate hastāttvakcaiva paridahyate|\nna ca śaknomyavasthātuṃ bhramatīva ca me manaḥ||","e":"from my weak hand slips\nGandiv, the goodly bow; a fever burns\nMy skin to parching; hardly may I stand;\nThe life within me seems to swim and faint;"},
{"c":1,"v":31,"d":"निमित्तानि च पश्यामि विपरीतानि केशव।\nन च श्रेयोऽनुपश्यामि हत्वा स्वजनमाहवे॥","t":"nimittāni ca paśyāmi viparītāni keśava|\nna ca śreyo'nupaśyāmi hatvā svajanamāhave||","e":"Nothing do I foresee save woe and wail!\nIt is not good, O Keshav! nought of good\nCan spring from mutual slaughter!"},
{"c":1,"v":32,"d":"न काङ्क्षे विजयं कृष्ण न च राज्यं सुखानि च।\nकिं नो राज्येन गोविन्द किं भोगैर्जीवितेन वा॥","t":"na kāṅkṣe vijayaṃ kṛṣṇa na ca rājyaṃ sukhāni ca|\nkiṃ no rājyena govinda kiṃ bhogairjīvitena vā||","e":"Lo, I hate\nTriumph and domination, wealth and ease,\nThus sadly won! Aho! what victory\nCan bring delight, Govinda! what rich spoils\nCould profit; what rule recompense; what span\nOf life itself seem sweet, bought with such blood?"},
{"c":1,"v":33,"d":"येषामर्थे काङ्क्षितं नो राज्यं भोगाः सुखानि च।\nत इमेऽवस्थिता युद्धे प्राणांस्त्यक्त्वा धनानि च॥","t":"yeṣāmarthe kāṅkṣitaṃ no rājyaṃ bhogāḥ sukhāni ca|\nta ime'vasthitā yuddhe prāṇāṃstyaktvā dhanāni ca||","e":"Seeing that these stand here, ready to die,\nFor whose sake life was fair, and pleasure pleased,\nAnd power grew precious:-"},
{"c":1,"v":34,"d":"आचार्याः पितरः पुत्रास्तथैव च पितामहाः।\nमातुलाः श्चशुराः पौत्राः श्यालाः सम्बन्धिनस्तथा॥","t":"ācāryāḥ pitaraḥ putrāstathaiva ca pitāmahāḥ|\nmātulāḥ ścaśurāḥ pautrāḥ śyālāḥ sambandhinastathā||","e":"grandsires, sires, and sons,\nBrothers, and fathers-in-law, and sons-in-law,\nElders and friends!"},
{"c":1,"v":35,"d":"एतान्न हन्तुमिच्छामि घ्नतोऽपि मधुसूदन।\nअपि त्रैलोक्यराज्यस्य हेतोः किं नु महीकृते॥","t":"etānna hantumicchāmi ghnato'pi madhusūdana|\napi trailokyarājyasya hetoḥ kiṃ nu mahīkṛte||","e":"Shall I deal death on these\nEven though they seek to slay us? Not one blow,\nO Madhusudan! will I strike to gain\nThe rule of all Three Worlds; then, how much less\nTo seize an earthly kingdom!"},
{"c":1,"v":36,"d":"निहत्य धार्तराष्ट्रान्नः का प्रीतिः स्याज्जनार्दन।\nपापमेवाश्रयेदस्मान्हत्वैतानाततायिनः॥","t":"nihatya dhārtarāṣṭrānnaḥ kā prītiḥ syājjanārdana|\npāpamevāśrayedasmānhatvaitānātatāyinaḥ||","e":"Killing these\nMust breed but anguish, Krishna! If they be\nGuilty, we shall grow guilty by their deaths;"},
{"c":1,"v":37,"d":"तस्मान्नार्हा वयं हन्तुं धार्तराष्ट्रान्स्वबान्धवान्।\nस्वजनं हि कथं हत्वा सुखिनः स्याम माधव॥","t":"tasmānnārhā vayaṃ hantuṃ dhārtarāṣṭrānsvabāndhavān|\nsvajanaṃ hi kathaṃ hatvā sukhinaḥ syāma mādhava||","e":"Their sins will light on us, if we shall slay\nThose sons of Dhritirashtra, and our kin;\nWhat peace could come of that, O Madhava?"},
{"c":1,"v":38,"d":"यद्यप्येते न पश्यन्ति लोभोपहतचेतसः।\nकुलक्षयकृतं दोषं मित्रद्रोहे च पातकम्॥","t":"yadyapyete na paśyanti lobhopahatacetasaḥ|\nkulakṣayakṛtaṃ doṣaṃ mitradrohe ca pātakam||","e":"For if indeed, blinded by lust and wrath,\nThese cannot see, or will not see, the sin\nOf kingly lines o'erthrown and kinsmen slain,"},
{"c":1,"v":39,"d":"कथं न ज्ञेयमस्माभिः पापादस्मान्निवर्तितुम्।\nकुलक्षयकृतं दोषं प्रपश्यद्भिर्जनार्दन॥","t":"kathaṃ na jñeyamasmābhiḥ pāpādasmānnivartitum|\nkulakṣayakṛtaṃ doṣaṃ prapaśyadbhirjanārdana||","e":"How should not we, who see, shun such a crime--\nWe who perceive the guilt and feel the shame--\nO thou Delight of Men, Janardana?"},
{"c":1,"v":40,"d":"कुलक्षये प्रणश्यन्ति कुलधर्माः सनातनाः।\nधर्मे नष्टे कुलं कृत्स्नमधर्मोऽभिभवत्युत॥","t":"kulakṣaye praṇaśyanti kuladharmāḥ sanātanāḥ|\ndharme naṣṭe kulaṃ kṛtsnamadharmo'bhibhavatyuta||","e":"By overthrow of houses perisheth\nTheir sweet continuous household piety,\nAnd-rites neglected, piety extinct--\nEnters impiety upon that home;"},
{"c":1,"v":41,"d":"अधर्माभिभवात्कृष्ण प्रदुष्यन्ति कुलस्त्रियः।\nस्त्रीषु दुष्टासु वार्ष्णेय जायते वर्णसङ्करः॥","t":"adharmābhibhavātkṛṣṇa praduṣyanti kulastriyaḥ|\nstrīṣu duṣṭāsu vārṣṇeya jāyate varṇasaṅkaraḥ||","e":"Its women grow unwomaned, whence there spring\nMad passions, and the mingling-up of castes,"},
{"c":1,"v":42,"d":"सङ्करो नरकायैव कुलघ्नानां कुलस्य च।\nपतन्ति पितरो ह्येषां लुप्तपिण्डोदकक्रियाः॥","t":"saṅkaro narakāyaiva kulaghnānāṃ kulasya ca|\npatanti pitaro hyeṣāṃ luptapiṇḍodakakriyāḥ||","e":"Sending a Hell-ward road that family,\nAnd whoso wrought its doom by wicked wrath.\nNay, and the souls of honoured ancestors\nFall from their place of peace, being bereft\nOf funeral-cakes and the wan death-water."},
{"c":1,"v":43,"d":"दोषैरेतैः कुलघ्नानां वर्णसङ्करकारकैः।\nउत्साद्यन्ते जातिधर्माः कुलधर्माश्च शाश्वताः॥","t":"doṣairetaiḥ kulaghnānāṃ varṇasaṅkarakārakaiḥ|\nutsādyante jātidharmāḥ kuladharmāśca śāśvatāḥ||","e":""},
{"c":1,"v":44,"d":"उत्सन्नकुलधर्माणां मनुष्याणां जनार्दन।\nनरकेऽनियतं वासो भवतीत्यनुशुश्रुम॥","t":"utsannakuladharmāṇāṃ manuṣyāṇāṃ janārdana|\nnarake'niyataṃ vāso bhavatītyanuśuśruma||","e":"So teach our holy hymns."},
{"c":1,"v":45,"d":"अहो बत महत्पापं कर्तुं व्यवसिता वयम्।\nयद्राज्यसुखलोभेन हन्तुं स्वजनमुद्यताः॥","t":"aho bata mahatpāpaṃ kartuṃ vyavasitā vayam|\nyadrājyasukhalobhena hantuṃ svajanamudyatāḥ||","e":"Thus, if we slay\nKinsfolk and friends for love of earthly power,\nAhovat! what an evil fault it were!"},
{"c":1,"v":46,"d":"यदि मामप्रतीकारमशस्त्रं शस्त्रपाणयः।\nधार्तराष्ट्रा रणे हन्युस्तन्मे क्षेमतरं भवेत्॥","t":"yadi māmapratīkāramaśastraṃ śastrapāṇayaḥ|\ndhārtarāṣṭrā raṇe hanyustanme kṣemataraṃ bhavet||","e":"Better I deem it, if my kinsmen strike,\nTo face them weaponless, and bare my breast\nTo shaft and spear, than answer blow with blow."},
{"c":1,"v":47,"d":"सञ्जय उवाच\nएवमुक्त्वाऽर्जुनः संख्ये रथोपस्थ उपाविशत्।\nविसृज्य सशरं चापं शोकसंविग्नमानसः॥","t":"sañjaya uvāca\nevamuktvā'rjunaḥ saṃkhye rathopastha upāviśat|\nvisṛjya saśaraṃ cāpaṃ śokasaṃvignamānasaḥ||","e":"So speaking, in the face of those two hosts,\nArjuna sank upon his chariot-seat,\nAnd let fall bow and arrows, sick at heart."},
{"c":2,"v":1,"d":"सञ्जय उवाच\nतं तथा कृपयाऽविष्टमश्रुपूर्णाकुलेक्षणम्।\nविषीदन्तमिदं वाक्यमुवाच मधुसूदनः॥","t":"sañjaya uvāca\ntaṃ tathā kṛpayā'viṣṭamaśrupūrṇākulekṣaṇam|\nviṣīdantamidaṃ vākyamuvāca madhusūdanaḥ||","e":"Sanjaya.\nHim, filled with such compassion and such grief,\nWith eyes tear-dimmed, despondent, in stern words\nThe Driver, Madhusudan, thus addressed:"},
{"c":2,"v":2,"d":"श्री भगवानुवाच\nकुतस्त्वा कश्मलमिदं विषमे समुपस्थितम्।\nअनार्यजुष्टमस्वर्ग्यमकीर्तिकरमर्जुन॥","t":"śrī bhagavānuvāca\nkutastvā kaśmalamidaṃ viṣame samupasthitam|\nanāryajuṣṭamasvargyamakīrtikaramarjuna||","e":"Krishna.\nHow hath this weakness taken thee? Whence springs\nThe inglorious trouble, shameful to the brave,\nBarring the path of virtue?"},
{"c":2,"v":3,"d":"क्लैब्यं मा स्म गमः पार्थ नैतत्त्वय्युपपद्यते।\nक्षुद्रं हृदयदौर्बल्यं त्यक्त्वोत्तिष्ठ परन्तप॥","t":"klaibyaṃ mā sma gamaḥ pārtha naitattvayyupapadyate|\nkṣudraṃ hṛdayadaurbalyaṃ tyaktvottiṣṭha parantapa||","e":"Nay, Arjun!\nForbid thyself to feebleness! it mars\nThy warrior-name! cast off the coward-fit!\nWake! Be thyself! Arise, Scourge of thy Foes!"},
{"c":2,"v":4,"d":"अर्जुन उवाच\nकथं भीष्ममहं संख्ये द्रोणं च मधुसूदन।\nइषुभिः प्रतियोत्स्यामि पूजार्हावरिसूदन॥","t":"arjuna uvāca\nkathaṃ bhīṣmamahaṃ saṃkhye droṇaṃ ca madhusūdana|\niṣubhiḥ pratiyotsyāmi pūjārhāvarisūdana||","e":"Arjuna.\nHow can I, in the battle, shoot with shafts\nOn Bhishma, or on Drona-O thou Chief!--\nBoth worshipful, both honourable men?"},
{"c":2,"v":5,"d":"गुरूनहत्वा हि महानुभावान्\nश्रेयो भोक्तुं भैक्ष्यमपीह लोके।\nहत्वार्थकामांस्तु गुरूनिहैव\nभुञ्जीय भोगान् रुधिरप्रदिग्धान्॥","t":"gurūnahatvā hi mahānubhāvān\nśreyo bhoktuṃ bhaikṣyamapīha loke|\nhatvārthakāmāṃstu gurūnihaiva\nbhuñjīya bhogān rudhirapradigdhān||","e":"Better to live on beggar's bread\nWith those we love alive,\nThan taste their blood in rich feasts spread,\nAnd guiltily survive!"},
{"c":2,"v":6,"d":"न चैतद्विद्मः कतरन्नो गरीयो\nयद्वा जयेम यदि वा नो जयेयुः।\nयानेव हत्वा न जिजीविषाम\nस्तेऽवस्थिताः प्रमुखे धार्तराष्ट्राः॥","t":"na caitadvidmaḥ kataranno garīyo\nyadvā jayema yadi vā no jayeyuḥ|\nyāneva hatvā na jijīviṣāma\nste'vasthitāḥ pramukhe dhārtarāṣṭrāḥ||","e":"Ah! were it worse-who knows?--to be\nVictor or vanquished here,\nWhen those confront us angrily\nWhose death leaves living drear?"},
{"c":2,"v":7,"d":"कार्पण्यदोषोपहतस्वभावः\nपृच्छामि त्वां धर्मसंमूढचेताः।\nयच्छ्रेयः स्यान्निश्िचतं ब्रूहि तन्मे\nशिष्यस्तेऽहं शाधि मां त्वां प्रपन्नम्॥","t":"kārpaṇyadoṣopahatasvabhāvaḥ\npṛcchāmi tvāṃ dharmasaṃmūḍhacetāḥ|\nyacchreyaḥ syānniścataṃ brūhi tanme\nśiṣyaste'haṃ śādhi māṃ tvāṃ prapannam||","e":"In pity lost, by doubtings tossed,\nMy thoughts-distracted-turn\nTo Thee, the Guide I reverence most,\nThat I may counsel learn:"},
{"c":2,"v":8,"d":"न हि प्रपश्यामि ममापनुद्या\nद्यच्छोकमुच्छोषणमिन्द्रियाणाम्।\nअवाप्य भूमावसपत्नमृद्धम्\nराज्यं सुराणामपि चाधिपत्यम्॥","t":"na hi prapaśyāmi mamāpanudyā\ndyacchokamucchoṣaṇamindriyāṇām|\navāpya bhūmāvasapatnamṛddham\nrājyaṃ surāṇāmapi cādhipatyam||","e":"I know not what would heal the grief\nBurned into soul and sense,\nIf I were earth's unchallenged chief--\nA god--and these gone thence!"},
{"c":2,"v":9,"d":"सञ्जय उवाच\nएवमुक्त्वा हृषीकेशं गुडाकेशः परन्तप।\nन योत्स्य इति गोविन्दमुक्त्वा तूष्णीं बभूव ह॥","t":"sañjaya uvāca\nevamuktvā hṛṣīkeśaṃ guḍākeśaḥ parantapa|\nna yotsya iti govindamuktvā tūṣṇīṃ babhūva ha||","e":"Sanjaya.\nSo spake Arjuna to the Lord of Hearts,\nAnd sighing,\"I will not fight!\" held silence then."},
{"c":2,"v":10,"d":"तमुवाच हृषीकेशः प्रहसन्निव भारत।\nसेनयोरुभयोर्मध्ये विषीदन्तमिदं वचः॥","t":"tamuvāca hṛṣīkeśaḥ prahasanniva bhārata|\nsenayorubhayormadhye viṣīdantamidaṃ vacaḥ||","e":"To whom, with tender smile, (O Bharata! )\nWhile the Prince wept despairing 'twixt those hosts,\nKrishna made answer in divinest verse:"},
{"c":2,"v":11,"d":"श्री भगवानुवाच\nअशोच्यानन्वशोचस्त्वं प्रज्ञावादांश्च भाषसे।\nगतासूनगतासूंश्च नानुशोचन्ति पण्डिताः॥","t":"śrī bhagavānuvāca\naśocyānanvaśocastvaṃ prajñāvādāṃśca bhāṣase|\ngatāsūnagatāsūṃśca nānuśocanti paṇḍitāḥ||","e":"Krishna.\nThou grievest where no grief should be! thou speak'st\nWords lacking wisdom! for the wise in heart\nMourn not for those that live, nor those that die."},
{"c":2,"v":12,"d":"न त्वेवाहं जातु नासं न त्वं नेमे जनाधिपाः।\nन चैव न भविष्यामः सर्वे वयमतः परम्॥","t":"na tvevāhaṃ jātu nāsaṃ na tvaṃ neme janādhipāḥ|\nna caiva na bhaviṣyāmaḥ sarve vayamataḥ param||","e":"Nor I, nor thou, nor any one of these,\nEver was not, nor ever will not be,\nFor ever and for ever afterwards.\nAll, that doth live, lives always!"},
{"c":2,"v":13,"d":"देहिनोऽस्मिन्यथा देहे कौमारं यौवनं जरा।\nतथा देहान्तरप्राप्तिर्धीरस्तत्र न मुह्यति॥","t":"dehino'sminyathā dehe kaumāraṃ yauvanaṃ jarā|\ntathā dehāntaraprāptirdhīrastatra na muhyati||","e":"To man's frame\nAs there come infancy and youth and age,\nSo come there raisings-up and layings-down\nOf other and of other life-abodes,\nWhich the wise know, and fear not."},
{"c":2,"v":14,"d":"मात्रास्पर्शास्तु कौन्तेय शीतोष्णसुखदुःखदाः।\nआगमापायिनोऽनित्यास्तांस्तितिक्षस्व भारत॥","t":"mātrāsparśāstu kaunteya śītoṣṇasukhaduḥkhadāḥ|\nāgamāpāyino'nityāstāṃstitikṣasva bhārata||","e":"This that irks--\nThy sense-life, thrilling to the elements--\nBringing thee heat and cold, sorrows and joys,\n'Tis brief and mutable! Bear with it, Prince!\nAs the wise bear."},
{"c":2,"v":15,"d":"यं हि न व्यथयन्त्येते पुरुषं पुरुषर्षभ।\nसमदुःखसुखं धीरं सोऽमृतत्वाय कल्पते॥","t":"yaṃ hi na vyathayantyete puruṣaṃ puruṣarṣabha|\nsamaduḥkhasukhaṃ dhīraṃ so'mṛtatvāya kalpate||","e":"The soul which is not moved,\nThe soul that with a strong and constant calm\nTakes sorrow and takes joy indifferently,\nLives in the life undying!"},
{"c":2,"v":16,"d":"नासतो विद्यते भावो नाभावो विद्यते सतः।\nउभयोरपि दृष्टोऽन्तस्त्वनयोस्तत्त्वदर्शिभिः॥","t":"nāsato vidyate bhāvo nābhāvo vidyate sataḥ|\nubhayorapi dṛṣṭo'ntastvanayostattvadarśibhiḥ||","e":"That which is\nCan never cease to be; that which is not\nWill not exist. To see this truth of both\nIs theirs who part essence from accident,\nSubstance from shadow."},
{"c":2,"v":17,"d":"अविनाशि तु तद्विद्धि येन सर्वमिदं ततम्।\nविनाशमव्ययस्यास्य न कश्चित् कर्तुमर्हति॥","t":"avināśi tu tadviddhi yena sarvamidaṃ tatam|\nvināśamavyayasyāsya na kaścit kartumarhati||","e":"Indestructible,\nLearn thou! the Life is, spreading life through all;\nIt cannot anywhere, by any means,\nBe anywise diminished, stayed, or changed."},
{"c":2,"v":18,"d":"अन्तवन्त इमे देहा नित्यस्योक्ताः शरीरिणः।\nअनाशिनोऽप्रमेयस्य तस्माद्युध्यस्व भारत॥","t":"antavanta ime dehā nityasyoktāḥ śarīriṇaḥ|\nanāśino'prameyasya tasmādyudhyasva bhārata||","e":"But for these fleeting frames which it informs\nWith spirit deathless, endless, infinite,\nThey perish. Let them perish, Prince! and fight!"},
{"c":2,"v":19,"d":"य एनं वेत्ति हन्तारं यश्चैनं मन्यते हतम्।\nउभौ तौ न विजानीतो नायं हन्ति न हन्यते॥","t":"ya enaṃ vetti hantāraṃ yaścainaṃ manyate hatam|\nubhau tau na vijānīto nāyaṃ hanti na hanyate||","e":"He who shall say, \"Lo! I have slain a man!\"\nHe who shall think, \"Lo! I am slain!\" those both\nKnow naught! Life cannot slay. Life is not slain!"},
{"c":2,"v":20,"d":"न जायते म्रियते वा कदाचि\nन्नायं भूत्वा भविता वा न भूयः।\nअजो नित्यः शाश्वतोऽयं पुराणो\nन हन्यते हन्यमाने शरीरे॥","t":"na jāyate mriyate vā kadāci\nnnāyaṃ bhūtvā bhavitā vā na bhūyaḥ|\najo nityaḥ śāśvato'yaṃ purāṇo\nna hanyate hanyamāne śarīre||","e":"Never the spirit was born; the spirit shall cease to be never;\nNever was time it was not; End and Beginning are dreams!\nBirthless and deathless and changeless remaineth the spirit for ever;\nDeath hath not touched it at all, dead though the house of it seems!"},
{"c":2,"v":21,"d":"वेदाविनाशिनं नित्यं य एनमजमव्ययम्।\nकथं स पुरुषः पार्थ कं घातयति हन्ति कम्॥","t":"vedāvināśinaṃ nityaṃ ya enamajamavyayam|\nkathaṃ sa puruṣaḥ pārtha kaṃ ghātayati hanti kam||","e":"Who knoweth it exhaustless, self-sustained,\nImmortal, indestructible,--shall such\nSay, \"I have killed a man, or caused to kill?\""},
{"c":2,"v":22,"d":"वासांसि जीर्णानि यथा विहाय\nनवानि गृह्णाति नरोऽपराणि।\nतथा शरीराणि विहाय जीर्णा\nन्यन्यानि संयाति नवानि देही॥","t":"vāsāṃsi jīrṇāni yathā vihāya\nnavāni gṛhṇāti naro'parāṇi|\ntathā śarīrāṇi vihāya jīrṇā\nnyanyāni saṃyāti navāni dehī||","e":"Nay, but as when one layeth\nHis worn-out robes away,\nAnd taking new ones, sayeth,\n\"These will I wear to-day!\"\nSo putteth by the spirit\nLightly its garb of flesh,\nAnd passeth to inherit\nA residence afresh."},
{"c":2,"v":23,"d":"नैनं छिन्दन्ति शस्त्राणि नैनं दहति पावकः।\nन चैनं क्लेदयन्त्यापो न शोषयति मारुतः॥","t":"nainaṃ chindanti śastrāṇi nainaṃ dahati pāvakaḥ|\nna cainaṃ kledayantyāpo na śoṣayati mārutaḥ||","e":"I say to thee weapons reach not the Life;\nFlame burns it not, waters cannot o'erwhelm,\nNor dry winds wither it."},
{"c":2,"v":24,"d":"अच्छेद्योऽयमदाह्योऽयमक्लेद्योऽशोष्य एव च।\nनित्यः सर्वगतः स्थाणुरचलोऽयं सनातनः॥","t":"acchedyo'yamadāhyo'yamakledyo'śoṣya eva ca|\nnityaḥ sarvagataḥ sthāṇuracalo'yaṃ sanātanaḥ||","e":"Impenetrable,\nUnentered, unassailed, unharmed, untouched,\nImmortal, all-arriving, stable, sure,"},
{"c":2,"v":25,"d":"अव्यक्तोऽयमचिन्त्योऽयमविकार्योऽयमुच्यते।\nतस्मादेवं विदित्वैनं नानुशोचितुमर्हसि॥","t":"avyakto'yamacintyo'yamavikāryo'yamucyate|\ntasmādevaṃ viditvainaṃ nānuśocitumarhasi||","e":"Invisible, ineffable, by word\nAnd thought uncompassed, ever all itself,\nThus is the Soul declared! How wilt thou, then,--\nKnowing it so,--grieve when thou shouldst not grieve?"},
{"c":2,"v":26,"d":"अथ चैनं नित्यजातं नित्यं वा मन्यसे मृतम्।\nतथापि त्वं महाबाहो नैवं शोचितुमर्हसि॥","t":"atha cainaṃ nityajātaṃ nityaṃ vā manyase mṛtam|\ntathāpi tvaṃ mahābāho naivaṃ śocitumarhasi||","e":"How, if thou hearest that the man new-dead\nIs, like the man new-born, still living man--\nOne same, existent Spirit--wilt thou weep?"},
{"c":2,"v":27,"d":"जातस्य हि ध्रुवो मृत्युर्ध्रुवं जन्म मृतस्य च।\nतस्मादपरिहार्येऽर्थे न त्वं शोचितुमर्हसि॥","t":"jātasya hi dhruvo mṛtyurdhruvaṃ janma mṛtasya ca|\ntasmādaparihārye'rthe na tvaṃ śocitumarhasi||","e":"The end of birth is death; the end of death\nIs birth: this is ordained! and mournest thou,\nChief of the stalwart arm! for what befalls\nWhich could not otherwise befall?"},
{"c":2,"v":28,"d":"अव्यक्तादीनि भूतानि व्यक्तमध्यानि भारत।\nअव्यक्तनिधनान्येव तत्र का परिदेवना॥","t":"avyaktādīni bhūtāni vyaktamadhyāni bhārata|\navyaktanidhanānyeva tatra kā paridevanā||","e":"The birth\nOf living things comes unperceived; the death\nComes unperceived; between them, beings perceive:\nWhat is there sorrowful herein, dear Prince?"},
{"c":2,"v":29,"d":"आश्चर्यवत्पश्यति कश्चिदेन\nमाश्चर्यवद्वदति तथैव चान्यः।\nआश्चर्यवच्चैनमन्यः श्रृणोति\nश्रुत्वाप्येनं वेद न चैव कश्चित्॥","t":"āścaryavatpaśyati kaścidena\nmāścaryavadvadati tathaiva cānyaḥ|\nāścaryavaccainamanyaḥ śrṛṇoti\nśrutvāpyenaṃ veda na caiva kaścit||","e":"Wonderful, wistful, to contemplate!\nDifficult, doubtful, to speak upon!\nStrange and great for tongue to relate,\nMystical hearing for every one!\nNor wotteth man this, what a marvel it is,\nWhen seeing, and saying, and hearing are done!"},
{"c":2,"v":30,"d":"देही नित्यमवध्योऽयं देहे सर्वस्य भारत।\nतस्मात्सर्वाणि भूतानि न त्वं शोचितुमर्हसि॥","t":"dehī nityamavadhyo'yaṃ dehe sarvasya bhārata|\ntasmātsarvāṇi bhūtāni na tvaṃ śocitumarhasi||","e":"This Life within all living things, my Prince!\nHides beyond harm; scorn thou to suffer, then,\nFor that which cannot suffer."},
{"c":2,"v":31,"d":"स्वधर्ममपि चावेक्ष्य न विकम्पितुमर्हसि।\nधर्म्याद्धि युद्धाछ्रेयोऽन्यत्क्षत्रियस्य न विद्यते॥","t":"svadharmamapi cāvekṣya na vikampitumarhasi|\ndharmyāddhi yuddhāchreyo'nyatkṣatriyasya na vidyate||","e":"Do thy part!\nBe mindful of thy name, and tremble not!\nNought better can betide a martial soul\nThan lawful war;"},
{"c":2,"v":32,"d":"यदृच्छया चोपपन्नं स्वर्गद्वारमपावृतम्।\nसुखिनः क्षत्रियाः पार्थ लभन्ते युद्धमीदृशम्॥","t":"yadṛcchayā copapannaṃ svargadvāramapāvṛtam|\nsukhinaḥ kṣatriyāḥ pārtha labhante yuddhamīdṛśam||","e":"happy the warrior\nTo whom comes joy of battle--comes, as now,\nGlorious and fair, unsought; opening for him\nA gateway unto Heav'n."},
{"c":2,"v":33,"d":"अथ चैत्त्वमिमं धर्म्यं संग्रामं न करिष्यसि।\nततः स्वधर्मं कीर्तिं च हित्वा पापमवाप्स्यसि॥","t":"atha caittvamimaṃ dharmyaṃ saṃgrāmaṃ na kariṣyasi|\ntataḥ svadharmaṃ kīrtiṃ ca hitvā pāpamavāpsyasi||","e":"But, if thou shunn'st\nThis honourable field--a Kshattriya--\nIf, knowing thy duty and thy task, thou bidd'st\nDuty and task go by--that shall be sin!"},
{"c":2,"v":34,"d":"अकीर्तिं चापि भूतानि कथयिष्यन्ति तेऽव्ययाम्।\nसंभावितस्य चाकीर्तिर्मरणादतिरिच्यते॥","t":"akīrtiṃ cāpi bhūtāni kathayiṣyanti te'vyayām|\nsaṃbhāvitasya cākīrtirmaraṇādatiricyate||","e":"And those to come shall speak thee infamy\nFrom age to age; but infamy is worse\nFor men of noble blood to bear than death!"},
{"c":2,"v":35,"d":"भयाद्रणादुपरतं मंस्यन्ते त्वां महारथाः।\nयेषां च त्वं बहुमतो भूत्वा यास्यसि लाघवम्॥","t":"bhayādraṇāduparataṃ maṃsyante tvāṃ mahārathāḥ|\nyeṣāṃ ca tvaṃ bahumato bhūtvā yāsyasi lāghavam||","e":"The chiefs upon their battle-chariots\nWill deem 'twas fear that drove thee from the fray.\nOf those who held thee mighty-souled the scorn\nThou must abide,"},
{"c":2,"v":36,"d":"अवाच्यवादांश्च बहून् वदिष्यन्ति तवाहिताः।\nनिन्दन्तस्तव सामर्थ्यं ततो दुःखतरं नु किम्॥","t":"avācyavādāṃśca bahūn vadiṣyanti tavāhitāḥ|\nnindantastava sāmarthyaṃ tato duḥkhataraṃ nu kim||","e":"while all thine enemies\nWill scatter bitter speech of thee, to mock\nThe valour which thou hadst; what fate could fall\nMore grievously than this?"},
{"c":2,"v":37,"d":"हतो वा प्राप्स्यसि स्वर्गं जित्वा वा भोक्ष्यसे महीम्।\nतस्मादुत्तिष्ठ कौन्तेय युद्धाय कृतनिश्चयः॥","t":"hato vā prāpsyasi svargaṃ jitvā vā bhokṣyase mahīm|\ntasmāduttiṣṭha kaunteya yuddhāya kṛtaniścayaḥ||","e":"Either--being killed--\nThou wilt win Swarga's safety, or--alive\nAnd victor--thou wilt reign an earthly king.\nTherefore, arise, thou Son of Kunti! brace\nThine arm for conflict,"},
{"c":2,"v":38,"d":"सुखदुःखे समे कृत्वा लाभालाभौ जयाजयौ।\nततो युद्धाय युज्यस्व नैवं पापमवाप्स्यसि॥","t":"sukhaduḥkhe same kṛtvā lābhālābhau jayājayau|\ntato yuddhāya yujyasva naivaṃ pāpamavāpsyasi||","e":"nerve thy heart to meet--\nAs things alike to thee--pleasure or pain,\nProfit or ruin, victory or defeat:\nSo minded, gird thee to the fight, for so\nThou shalt not sin!"},
{"c":2,"v":39,"d":"एषा तेऽभिहिता सांख्ये बुद्धिर्योगे त्विमां श्रृणु।\nबुद्ध्यायुक्तो यया पार्थ कर्मबन्धं प्रहास्यसि॥","t":"eṣā te'bhihitā sāṃkhye buddhiryoge tvimāṃ śrṛṇu|\nbuddhyāyukto yayā pārtha karmabandhaṃ prahāsyasi||","e":"Thus far I speak to thee\nAs from the \"Sankhya\"--unspiritually--\nHear now the deeper teaching of the Yog,\nWhich holding, understanding, thou shalt burst\nThy Karmabandh, the bondage of wrought deeds."},
{"c":2,"v":40,"d":"नेहाभिक्रमनाशोऽस्ति प्रत्यवायो न विद्यते।\nस्वल्पमप्यस्य धर्मस्य त्रायते महतो भयात्॥","t":"nehābhikramanāśo'sti pratyavāyo na vidyate|\nsvalpamapyasya dharmasya trāyate mahato bhayāt||","e":"Here shall no end be hindered, no hope marred,\nNo loss be feared: faith--yea, a little faith--\nShall save thee from the anguish of thy dread."},
{"c":2,"v":41,"d":"व्यवसायात्मिका बुद्धिरेकेह कुरुनन्दन।\nबहुशाखा ह्यनन्ताश्च बुद्धयोऽव्यवसायिनाम्॥","t":"vyavasāyātmikā buddhirekeha kurunandana|\nbahuśākhā hyanantāśca buddhayo'vyavasāyinām||","e":"Here, Glory of the Kurus! shines one rule--\nOne steadfast rule--while shifting souls have laws\nMany and hard."},
{"c":2,"v":42,"d":"यामिमां पुष्पितां वाचं प्रवदन्त्यविपश्चितः।\nवेदवादरताः पार्थ नान्यदस्तीति वादिनः॥","t":"yāmimāṃ puṣpitāṃ vācaṃ pravadantyavipaścitaḥ|\nvedavādaratāḥ pārtha nānyadastīti vādinaḥ||","e":"Specious, but wrongful deem\nThe speech of those ill-taught ones who extol\nThe letter of their Vedas, saying, \"This\nIs all we have, or need;\""},
{"c":2,"v":43,"d":"कामात्मानः स्वर्गपरा जन्मकर्मफलप्रदाम्।\nक्रियाविशेषबहुलां भोगैश्वर्यगतिं प्रति॥","t":"kāmātmānaḥ svargaparā janmakarmaphalapradām|\nkriyāviśeṣabahulāṃ bhogaiśvaryagatiṃ prati||","e":"being weak at heart\nWith wants, seekers of Heaven: which comes--they say--\nAs \"fruit of good deeds done;\" promising men\nMuch profit in new births for works of faith;\nIn various rites abounding; following whereon\nLarge merit shall accrue towards wealth and power;"},
{"c":2,"v":44,"d":"भोगैश्वर्यप्रसक्तानां तयापहृतचेतसाम्।\nव्यवसायात्मिका बुद्धिः समाधौ न विधीयते॥","t":"bhogaiśvaryaprasaktānāṃ tayāpahṛtacetasām|\nvyavasāyātmikā buddhiḥ samādhau na vidhīyate||","e":"Albeit, who wealth and power do most desire\nLeast fixity of soul have such, least hold\nOn heavenly meditation."},
{"c":2,"v":45,"d":"त्रैगुण्यविषया वेदा निस्त्रैगुण्यो भवार्जुन।\nनिर्द्वन्द्वो नित्यसत्त्वस्थो निर्योगक्षेम आत्मवान्॥","t":"traiguṇyaviṣayā vedā nistraiguṇyo bhavārjuna|\nnirdvandvo nityasattvastho niryogakṣema ātmavān||","e":"Much these teach,\nFrom Veds, concerning the \"three qualities;\"\nBut thou, be free of the \"three qualities,\"\nFree of the \"pairs of opposites,\" and free\nFrom that sad righteousness which calculates;\nSelf-ruled, Arjuna! simple, satisfied!"},
{"c":2,"v":46,"d":"यावानर्थ उदपाने सर्वतः संप्लुतोदके।\nतावान्सर्वेषु वेदेषु ब्राह्मणस्य विजानतः॥","t":"yāvānartha udapāne sarvataḥ saṃplutodake|\ntāvānsarveṣu vedeṣu brāhmaṇasya vijānataḥ||","e":"Look! like as when a tank pours water forth\nTo suit all needs, so do these Brahmans draw\nText for all wants from tank of Holy Writ."},
{"c":2,"v":47,"d":"कर्मण्येवाधिकारस्ते मा फलेषु कदाचन।\nमा कर्मफलहेतुर्भूर्मा ते सङ्गोऽस्त्वकर्मणि॥","t":"karmaṇyevādhikāraste mā phaleṣu kadācana|\nmā karmaphalaheturbhūrmā te saṅgo'stvakarmaṇi||","e":"But thou, want not! ask not! Find full reward\nOf doing right in right! Let right deeds be\nThy motive, not the fruit which comes from them.\nAnd live in action! Labour!"},
{"c":2,"v":48,"d":"योगस्थः कुरु कर्माणि सङ्गं त्यक्त्वा धनञ्जय।\nसिद्ध्यसिद्ध्योः समो भूत्वा समत्वं योग उच्यते॥","t":"yogasthaḥ kuru karmāṇi saṅgaṃ tyaktvā dhanañjaya|\nsiddhyasiddhyoḥ samo bhūtvā samatvaṃ yoga ucyate||","e":"Make thine acts\nThy piety, casting all self aside,\nContemning gain and merit; equable\nIn good or evil: equability\nIs Yog, is piety!"},
{"c":2,"v":49,"d":"दूरेण ह्यवरं कर्म बुद्धियोगाद्धनञ्जय।\nबुद्धौ शरणमन्विच्छ कृपणाः फलहेतवः॥","t":"dūreṇa hyavaraṃ karma buddhiyogāddhanañjaya|\nbuddhau śaraṇamanviccha kṛpaṇāḥ phalahetavaḥ||","e":"Yet, the right act\nIs less, far less, than the right-thinking mind.\nSeek refuge in thy soul; have there thy heaven!\nScorn them that follow virtue for her gifts!"},
{"c":2,"v":50,"d":"बुद्धियुक्तो जहातीह उभे सुकृतदुष्कृते।\nतस्माद्योगाय युज्यस्व योगः कर्मसु कौशलम्॥","t":"buddhiyukto jahātīha ubhe sukṛtaduṣkṛte|\ntasmādyogāya yujyasva yogaḥ karmasu kauśalam||","e":"The mind of pure devotion--even here--\nCasts equally aside good deeds and bad,\nPassing above them. Unto pure devotion\nDevote thyself: with perfect meditation\nComes perfect act,"},
{"c":2,"v":51,"d":"कर्मजं बुद्धियुक्ता हि फलं त्यक्त्वा मनीषिणः।\nजन्मबन्धविनिर्मुक्ताः पदं गच्छन्त्यनामयम्॥","t":"karmajaṃ buddhiyuktā hi phalaṃ tyaktvā manīṣiṇaḥ|\njanmabandhavinirmuktāḥ padaṃ gacchantyanāmayam||","e":"and the right-hearted rise--\nMore certainly because they seek no gain--\nForth from the bands of body, step by step,\nTo highest seats of bliss."},
{"c":2,"v":52,"d":"यदा ते मोहकलिलं बुद्धिर्व्यतितरिष्यति।\nतदा गन्तासि निर्वेदं श्रोतव्यस्य श्रुतस्य च॥","t":"yadā te mohakalilaṃ buddhirvyatitariṣyati|\ntadā gantāsi nirvedaṃ śrotavyasya śrutasya ca||","e":"When thy firm soul\nHath shaken off those tangled oracles\nWhich ignorantly guide, then shall it soar\nTo high neglect of what's denied or said,\nThis way or that way, in doctrinal writ."},
{"c":2,"v":53,"d":"श्रुतिविप्रतिपन्ना ते यदा स्थास्यति निश्चला।\nसमाधावचला बुद्धिस्तदा योगमवाप्स्यसि॥","t":"śrutivipratipannā te yadā sthāsyati niścalā|\nsamādhāvacalā buddhistadā yogamavāpsyasi||","e":"Troubled no longer by the priestly lore,\nSafe shall it live, and sure; steadfastly bent\nOn meditation. This is Yog--and Peace!"},
{"c":2,"v":54,"d":"अर्जुन उवाच\nस्थितप्रज्ञस्य का भाषा समाधिस्थस्य केशव।\nस्थितधीः किं प्रभाषेत किमासीत व्रजेत किम्॥","t":"arjuna uvāca\nsthitaprajñasya kā bhāṣā samādhisthasya keśava|\nsthitadhīḥ kiṃ prabhāṣeta kimāsīta vrajeta kim||","e":"Arjuna.\nWhat is his mark who hath that steadfast heart,\nConfirmed in holy meditation? How\nKnow we his speech, Kesava? Sits he, moves he\nLike other men?"},
{"c":2,"v":55,"d":"श्री भगवानुवाच\nप्रजहाति यदा कामान् सर्वान् पार्थ मनोगतान्।\nआत्मन्येवात्मना तुष्टः स्थितप्रज्ञस्तदोच्यते॥","t":"śrī bhagavānuvāca\nprajahāti yadā kāmān sarvān pārtha manogatān|\nātmanyevātmanā tuṣṭaḥ sthitaprajñastadocyate||","e":"Krishna.\nWhen one, O Pritha's Son!\nAbandoning desires which shake the mind--\nFinds in his soul full comfort for his soul,\nHe hath attained the Yog--that man is such!"},
{"c":2,"v":56,"d":"दुःखेष्वनुद्विग्नमनाः सुखेषु विगतस्पृहः।\nवीतरागभयक्रोधः स्थितधीर्मुनिरुच्यते॥","t":"duḥkheṣvanudvignamanāḥ sukheṣu vigataspṛhaḥ|\nvītarāgabhayakrodhaḥ sthitadhīrmunirucyate||","e":"In sorrows not dejected, and in joys\nNot overjoyed; dwelling outside the stress\nOf passion, fear, and anger; fixed in calms\nOf lofty contemplation;--such an one\nIs Muni, is the Sage, the true Recluse!"},
{"c":2,"v":57,"d":"यः सर्वत्रानभिस्नेहस्तत्तत्प्राप्य शुभाशुभम्।\nनाभिनन्दति न द्वेष्टि तस्य प्रज्ञा प्रतिष्ठिता॥","t":"yaḥ sarvatrānabhisnehastattatprāpya śubhāśubham|\nnābhinandati na dveṣṭi tasya prajñā pratiṣṭhitā||","e":"He who to none and nowhere overbound\nBy ties of flesh, takes evil things and good\nNeither desponding nor exulting, such\nBears wisdom's plainest mark!"},
{"c":2,"v":58,"d":"यदा संहरते चायं कूर्मोऽङ्गानीव सर्वशः।\nइन्द्रियाणीन्द्रियार्थेभ्यस्तस्य प्रज्ञा प्रतिष्ठिता॥","t":"yadā saṃharate cāyaṃ kūrmo'ṅgānīva sarvaśaḥ|\nindriyāṇīndriyārthebhyastasya prajñā pratiṣṭhitā||","e":"He who shall draw\nAs the wise tortoise draws its four feet safe\nUnder its shield, his five frail senses back\nUnder the spirit's buckler from the world\nWhich else assails them, such an one, my Prince!\nHath wisdom's mark!"},
{"c":2,"v":59,"d":"विषया विनिवर्तन्ते निराहारस्य देहिनः।\nरसवर्जं रसोऽप्यस्य परं दृष्ट्वा निवर्तते॥","t":"viṣayā vinivartante nirāhārasya dehinaḥ|\nrasavarjaṃ raso'pyasya paraṃ dṛṣṭvā nivartate||","e":"Things that solicit sense\nHold off from the self-governed; nay, it comes,\nThe appetites of him who lives beyond\nDepart,--aroused no more."},
{"c":2,"v":60,"d":"यततो ह्यपि कौन्तेय पुरुषस्य विपश्चितः।\nइन्द्रियाणि प्रमाथीनि हरन्ति प्रसभं मनः॥","t":"yatato hyapi kaunteya puruṣasya vipaścitaḥ|\nindriyāṇi pramāthīni haranti prasabhaṃ manaḥ||","e":"Yet may it chance,\nO Son of Kunti! that a governed mind\nShall some time feel the sense-storms sweep, and wrest\nStrong self-control by the roots."},
{"c":2,"v":61,"d":"तानि सर्वाणि संयम्य युक्त आसीत मत्परः।\nवशे हि यस्येन्द्रियाणि तस्य प्रज्ञा प्रतिष्ठिता॥","t":"tāni sarvāṇi saṃyamya yukta āsīta matparaḥ|\nvaśe hi yasyendriyāṇi tasya prajñā pratiṣṭhitā||","e":"Let him regain\nHis kingdom! let him conquer this, and sit\nOn Me intent. That man alone is wise\nWho keeps the mastery of himself!"},
{"c":2,"v":62,"d":"ध्यायतो विषयान्पुंसः सङ्गस्तेषूपजायते।\nसङ्गात् संजायते कामः कामात्क्रोधोऽभिजायते॥","t":"dhyāyato viṣayānpuṃsaḥ saṅgasteṣūpajāyate|\nsaṅgāt saṃjāyate kāmaḥ kāmātkrodho'bhijāyate||","e":"If one\nPonders on objects of the sense, there springs\nAttraction; from attraction grows desire,\nDesire flames to fierce passion,"},
{"c":2,"v":63,"d":"क्रोधाद्भवति संमोहः संमोहात्स्मृतिविभ्रमः।\nस्मृतिभ्रंशाद् बुद्धिनाशो बुद्धिनाशात्प्रणश्यति॥","t":"krodhādbhavati saṃmohaḥ saṃmohātsmṛtivibhramaḥ|\nsmṛtibhraṃśād buddhināśo buddhināśātpraṇaśyati||","e":"passion breeds\nRecklessness; then the memory--all betrayed--\nLets noble purpose go, and saps the mind,\nTill purpose, mind, and man are all undone."},
{"c":2,"v":64,"d":"रागद्वेषवियुक्तैस्तु विषयानिन्द्रियैश्चरन्।\nआत्मवश्यैर्विधेयात्मा प्रसादमधिगच्छति॥","t":"rāgadveṣaviyuktaistu viṣayānindriyaiścaran|\nātmavaśyairvidheyātmā prasādamadhigacchati||","e":"But, if one deals with objects of the sense\nNot loving and not hating, making them\nServe his free soul, which rests serenely lord,\nLo! such a man comes to tranquillity;"},
{"c":2,"v":65,"d":"प्रसादे सर्वदुःखानां हानिरस्योपजायते।\nप्रसन्नचेतसो ह्याशु बुद्धिः पर्यवतिष्ठते॥","t":"prasāde sarvaduḥkhānāṃ hānirasyopajāyate|\nprasannacetaso hyāśu buddhiḥ paryavatiṣṭhate||","e":"And out of that tranquillity shall rise\nThe end and healing of his earthly pains,\nSince the will governed sets the soul at peace."},
{"c":2,"v":66,"d":"नास्ति बुद्धिरयुक्तस्य न चायुक्तस्य भावना।\nन चाभावयतः शान्तिरशान्तस्य कुतः सुखम्॥","t":"nāsti buddhirayuktasya na cāyuktasya bhāvanā|\nna cābhāvayataḥ śāntiraśāntasya kutaḥ sukham||","e":"The soul of the ungoverned is not his,\nNor hath he knowledge of himself; which lacked,\nHow grows serenity? and, wanting that,\nWhence shall he hope for happiness?"},
{"c":2,"v":67,"d":"इन्द्रियाणां हि चरतां यन्मनोऽनुविधीयते।\nतदस्य हरति प्रज्ञां वायुर्नावमिवाम्भसि॥","t":"indriyāṇāṃ hi caratāṃ yanmano'nuvidhīyate|\ntadasya harati prajñāṃ vāyurnāvamivāmbhasi||","e":"The mind\nThat gives itself to follow shows of sense\nSeeth its helm of wisdom rent away,\nAnd, like a ship in waves of whirlwind, drives\nTo wreck and death."},
{"c":2,"v":68,"d":"तस्माद्यस्य महाबाहो निगृहीतानि सर्वशः।\nइन्द्रियाणीन्द्रियार्थेभ्यस्तस्य प्रज्ञा प्रतिष्ठिता॥","t":"tasmādyasya mahābāho nigṛhītāni sarvaśaḥ|\nindriyāṇīndriyārthebhyastasya prajñā pratiṣṭhitā||","e":"Only with him, great Prince!\nWhose senses are not swayed by things of sense--\nOnly with him who holds his mastery,\nShows wisdom perfect."},
{"c":2,"v":69,"d":"या निशा सर्वभूतानां तस्यां जागर्ति संयमी।\nयस्यां जाग्रति भूतानि सा निशा पश्यतो मुनेः॥","t":"yā niśā sarvabhūtānāṃ tasyāṃ jāgarti saṃyamī|\nyasyāṃ jāgrati bhūtāni sā niśā paśyato muneḥ||","e":"What is midnight-gloom\nTo unenlightened souls shines wakeful day\nTo his clear gaze; what seems as wakeful day\nIs known for night, thick night of ignorance,\nTo his true-seeing eyes. Such is the Saint!"},
{"c":2,"v":70,"d":"आपूर्यमाणमचलप्रतिष्ठं\nसमुद्रमापः प्रविशन्ति यद्वत्।\nतद्वत्कामा यं प्रविशन्ति सर्वे\nस शान्तिमाप्नोति न कामकामी॥","t":"āpūryamāṇamacalapratiṣṭhaṃ\nsamudramāpaḥ praviśanti yadvat|\ntadvatkāmā yaṃ praviśanti sarve\nsa śāntimāpnoti na kāmakāmī||","e":"And like the ocean, day by day receiving\nFloods from all lands, which never overflows\nIts boundary-line not leaping, and not leaving,\nFed by the rivers, but unswelled by those;--\nSo is the perfect one! to his soul's ocean\nThe world of sense pours streams of witchery;\nThey leave him as they find, without commotion,\nTaking their tribute, but remaining sea."},
{"c":2,"v":71,"d":"विहाय कामान्यः सर्वान्पुमांश्चरति निःस्पृहः।\nनिर्ममो निरहंकारः स शांतिमधिगच्छति॥","t":"vihāya kāmānyaḥ sarvānpumāṃścarati niḥspṛhaḥ|\nnirmamo nirahaṃkāraḥ sa śāṃtimadhigacchati||","e":"Yea! whoso, shaking off the yoke of flesh\nLives lord, not servant, of his lusts; set free\nFrom pride, from passion, from the sin of \"Self,\"\nToucheth tranquillity!"},
{"c":2,"v":72,"d":"एषा ब्राह्मी स्थितिः पार्थ नैनां प्राप्य विमुह्यति।\nस्थित्वाऽस्यामन्तकालेऽपि ब्रह्मनिर्वाणमृच्छति॥","t":"eṣā brāhmī sthitiḥ pārtha naināṃ prāpya vimuhyati|\nsthitvā'syāmantakāle'pi brahmanirvāṇamṛcchati||","e":"O Pritha's Son!\nThat is the state of Brahm! There rests no dread\nWhen that last step is reached! Live where he will,\nDie when he may, such passeth from all 'plaining,\nTo blest Nirvana, with the Gods, attaining."},
{"c":3,"v":1,"d":"अर्जुन उवाच\nज्यायसी चेत्कर्मणस्ते मता बुद्धिर्जनार्दन।\nतत्किं कर्मणि घोरे मां नियोजयसि केशव॥","t":"arjuna uvāca\njyāyasī cetkarmaṇaste matā buddhirjanārdana|\ntatkiṃ karmaṇi ghore māṃ niyojayasi keśava||","e":"Arjuna.\nThou whom all mortals praise, Janardana!\nIf meditation be a nobler thing\nThan action, wherefore, then, great Kesava!\nDost thou impel me to this dreadful fight?"},
{"c":3,"v":2,"d":"व्यामिश्रेणेव वाक्येन बुद्धिं मोहयसीव मे।\nतदेकं वद निश्िचत्य येन श्रेयोऽहमाप्नुयाम्॥","t":"vyāmiśreṇeva vākyena buddhiṃ mohayasīva me|\ntadekaṃ vada niścatya yena śreyo'hamāpnuyām||","e":"Now am I by thy doubtful speech disturbed!\nTell me one thing, and tell me certainly;\nBy what road shall I find the better end?"},
{"c":3,"v":3,"d":"श्री भगवानुवाच\nलोकेऽस्मिन्द्विविधा निष्ठा पुरा प्रोक्ता मयानघ।\nज्ञानयोगेन सांख्यानां कर्मयोगेन योगिनाम्॥","t":"śrī bhagavānuvāca\nloke'smindvividhā niṣṭhā purā proktā mayānagha|\njñānayogena sāṃkhyānāṃ karmayogena yoginām||","e":"Krishna.\nI told thee, blameless Lord! there be two paths\nShown to this world; two schools of wisdom.\nFirst\nThe Sankhya's, which doth save in way of works\nPrescribed by reason; next, the Yog, which bids\nAttain by meditation, spiritually:\nYet these are one!"},
{"c":3,"v":4,"d":"न कर्मणामनारम्भान्नैष्कर्म्यं पुरुषोऽश्नुते।\nन च संन्यसनादेव सिद्धिं समधिगच्छति॥","t":"na karmaṇāmanārambhānnaiṣkarmyaṃ puruṣo'śnute|\nna ca saṃnyasanādeva siddhiṃ samadhigacchati||","e":"No man shall 'scape from act\nBy shunning action; nay, and none shall come\nBy mere renouncements unto perfectness."},
{"c":3,"v":5,"d":"न हि कश्िचत्क्षणमपि जातु तिष्ठत्यकर्मकृत्।\nकार्यते ह्यवशः कर्म सर्वः प्रकृतिजैर्गुणैः॥","t":"na hi kaścatkṣaṇamapi jātu tiṣṭhatyakarmakṛt|\nkāryate hyavaśaḥ karma sarvaḥ prakṛtijairguṇaiḥ||","e":"Nay, and no jot of time, at any time,\nRests any actionless; his nature's law\nCompels him, even unwilling, into act;\n[For thought is act in fancy]."},
{"c":3,"v":6,"d":"कर्मेन्द्रियाणि संयम्य य आस्ते मनसा स्मरन्।\nइन्द्रियार्थान्विमूढात्मा मिथ्याचारः स उच्यते॥","t":"karmendriyāṇi saṃyamya ya āste manasā smaran|\nindriyārthānvimūḍhātmā mithyācāraḥ sa ucyate||","e":"He who sits\nSuppressing all the instruments of flesh,\nYet in his idle heart thinking on them,\nPlays the inept and guilty hypocrite:"},
{"c":3,"v":7,"d":"यस्त्विन्द्रियाणि मनसा नियम्यारभतेऽर्जुन।\nकर्मेन्द्रियैः कर्मयोगमसक्तः स विशिष्यते॥","t":"yastvindriyāṇi manasā niyamyārabhate'rjuna|\nkarmendriyaiḥ karmayogamasaktaḥ sa viśiṣyate||","e":"But he who, with strong body serving mind,\nGives up his mortal powers to worthy work,\nNot seeking gain, Arjuna! such an one\nIs honourable."},
{"c":3,"v":8,"d":"नियतं कुरु कर्म त्वं कर्म ज्यायो ह्यकर्मणः।\nशरीरयात्रापि च ते न प्रसिद्ध्येदकर्मणः॥","t":"niyataṃ kuru karma tvaṃ karma jyāyo hyakarmaṇaḥ|\nśarīrayātrāpi ca te na prasiddhyedakarmaṇaḥ||","e":"Do thine allotted task!\nWork is more excellent than idleness;\nThe body's life proceeds not, lacking work."},
{"c":3,"v":9,"d":"यज्ञार्थात्कर्मणोऽन्यत्र लोकोऽयं कर्मबन्धनः।\nतदर्थं कर्म कौन्तेय मुक्तसंगः समाचर॥","t":"yajñārthātkarmaṇo'nyatra loko'yaṃ karmabandhanaḥ|\ntadarthaṃ karma kaunteya muktasaṃgaḥ samācara||","e":"There is a task of holiness to do,\nUnlike world-binding toil, which bindeth not\nThe faithful soul; such earthly duty do\nFree from desire, and thou shalt well perform\nThy heavenly purpose."},
{"c":3,"v":10,"d":"सहयज्ञाः प्रजाः सृष्ट्वा पुरोवाच प्रजापतिः।\nअनेन प्रसविष्यध्वमेष वोऽस्त्विष्टकामधुक्॥","t":"sahayajñāḥ prajāḥ sṛṣṭvā purovāca prajāpatiḥ|\nanena prasaviṣyadhvameṣa vo'stviṣṭakāmadhuk||","e":"Spake Prajapati--\nIn the beginning, when all men were made,\nAnd, with mankind, the sacrifice-- \"Do this!\nWork! sacrifice! Increase and multiply\nWith sacrifice! This shall be Kamaduk,\nYour 'Cow of Plenty,' giving back her milk\nOf all abundance."},
{"c":3,"v":11,"d":"देवान्भावयतानेन ते देवा भावयन्तु वः।\nपरस्परं भावयन्तः श्रेयः परमवाप्स्यथ॥","t":"devānbhāvayatānena te devā bhāvayantu vaḥ|\nparasparaṃ bhāvayantaḥ śreyaḥ paramavāpsyatha||","e":"Worship the gods thereby;\nThe gods shall yield thee grace."},
{"c":3,"v":12,"d":"इष्टान्भोगान्हि वो देवा दास्यन्ते यज्ञभाविताः।\nतैर्दत्तानप्रदायैभ्यो यो भुङ्क्ते स्तेन एव सः॥","t":"iṣṭānbhogānhi vo devā dāsyante yajñabhāvitāḥ|\ntairdattānapradāyaibhyo yo bhuṅkte stena eva saḥ||","e":"Those meats ye crave\nThe gods will grant to Labour, when it pays\nTithes in the altar-flame. But if one eats\nFruits of the earth, rendering to kindly Heaven\nNo gift of toil, that thief steals from his world.\""},
{"c":3,"v":13,"d":"यज्ञशिष्टाशिनः सन्तो मुच्यन्ते सर्वकिल्बिषैः।\nभुञ्जते ते त्वघं पापा ये पचन्त्यात्मकारणात्॥","t":"yajñaśiṣṭāśinaḥ santo mucyante sarvakilbiṣaiḥ|\nbhuñjate te tvaghaṃ pāpā ye pacantyātmakāraṇāt||","e":"Who eat of food after their sacrifice\nAre quit of fault, but they that spread a feast\nAll for themselves, eat sin and drink of sin."},
{"c":3,"v":14,"d":"अन्नाद्भवन्ति भूतानि पर्जन्यादन्नसम्भवः।\nयज्ञाद्भवति पर्जन्यो यज्ञः कर्मसमुद्भवः॥","t":"annādbhavanti bhūtāni parjanyādannasambhavaḥ|\nyajñādbhavati parjanyo yajñaḥ karmasamudbhavaḥ||","e":"By food the living live; food comes of rain,\nAnd rain comes by the pious sacrifice,\nAnd sacrifice is paid with tithes of toil;"},
{"c":3,"v":15,"d":"कर्म ब्रह्मोद्भवं विद्धि ब्रह्माक्षरसमुद्भवम्।\nतस्मात्सर्वगतं ब्रह्म नित्यं यज्ञे प्रतिष्ठितम्॥","t":"karma brahmodbhavaṃ viddhi brahmākṣarasamudbhavam|\ntasmātsarvagataṃ brahma nityaṃ yajñe pratiṣṭhitam||","e":"Thus action is of Brahma, who is One,\nThe Only, All-pervading; at all times\nPresent in sacrifice."},
{"c":3,"v":16,"d":"एवं प्रवर्तितं चक्रं नानुवर्तयतीह यः।\nअघायुरिन्द्रियारामो मोघं पार्थ स जीवति॥","t":"evaṃ pravartitaṃ cakraṃ nānuvartayatīha yaḥ|\naghāyurindriyārāmo moghaṃ pārtha sa jīvati||","e":"He that abstains\nTo help the rolling wheels of this great world,\nGlutting his idle sense, lives a lost life,\nShameful and vain."},
{"c":3,"v":17,"d":"यस्त्वात्मरतिरेव स्यादात्मतृप्तश्च मानवः।\nआत्मन्येव च सन्तुष्टस्तस्य कार्यं न विद्यते॥","t":"yastvātmaratireva syādātmatṛptaśca mānavaḥ|\nātmanyeva ca santuṣṭastasya kāryaṃ na vidyate||","e":"Existing for himself,\nSelf-concentrated, serving self alone,\nNo part hath he in aught;"},
{"c":3,"v":18,"d":"नैव तस्य कृतेनार्थो नाकृतेनेह कश्चन।\nन चास्य सर्वभूतेषु कश्िचदर्थव्यपाश्रयः॥","t":"naiva tasya kṛtenārtho nākṛteneha kaścana|\nna cāsya sarvabhūteṣu kaścadarthavyapāśrayaḥ||","e":"nothing achieved,\nNought wrought or unwrought toucheth him; no hope\nOf help for all the living things of earth\nDepends from him."},
{"c":3,"v":19,"d":"तस्मादसक्तः सततं कार्यं कर्म समाचर।\nअसक्तो ह्याचरन्कर्म परमाप्नोति पूरुषः॥","t":"tasmādasaktaḥ satataṃ kāryaṃ karma samācara|\nasakto hyācarankarma paramāpnoti pūruṣaḥ||","e":"Therefore, thy task prescribed\nWith spirit unattached gladly perform,\nSince in performance of plain duty man\nMounts to his highest bliss."},
{"c":3,"v":20,"d":"कर्मणैव हि संसिद्धिमास्थिता जनकादयः।\nलोकसंग्रहमेवापि संपश्यन्कर्तुमर्हसि॥","t":"karmaṇaiva hi saṃsiddhimāsthitā janakādayaḥ|\nlokasaṃgrahamevāpi saṃpaśyankartumarhasi||","e":"By works alone\nJanak and ancient saints reached blessedness!\nMoreover, for the upholding of thy kind,\nAction thou should'st embrace."},
{"c":3,"v":21,"d":"यद्यदाचरति श्रेष्ठस्तत्तदेवेतरो जनः।\nस यत्प्रमाणं कुरुते लोकस्तदनुवर्तते॥","t":"yadyadācarati śreṣṭhastattadevetaro janaḥ|\nsa yatpramāṇaṃ kurute lokastadanuvartate||","e":"What the wise choose\nThe unwise people take; what best men do\nThe multitude will follow."},
{"c":3,"v":22,"d":"न मे पार्थास्ति कर्तव्यं त्रिषु लोकेषु किञ्चन।\nनानवाप्तमवाप्तव्यं वर्त एव च कर्मणि॥","t":"na me pārthāsti kartavyaṃ triṣu lokeṣu kiñcana|\nnānavāptamavāptavyaṃ varta eva ca karmaṇi||","e":"Look on me,\nThou Son of Pritha! in the three wide worlds\nI am not bound to any toil, no height\nAwaits to scale, no gift remains to gain,\nYet I act here!"},
{"c":3,"v":23,"d":"यदि ह्यहं न वर्तेयं जातु कर्मण्यतन्द्रितः।\nमम वर्त्मानुवर्तन्ते मनुष्याः पार्थ सर्वशः॥","t":"yadi hyahaṃ na varteyaṃ jātu karmaṇyatandritaḥ|\nmama vartmānuvartante manuṣyāḥ pārtha sarvaśaḥ||","e":"and, if I acted not--\nEarnest and watchful--those that look to me\nFor guidance, sinking back to sloth again\nBecause I slumbered, would decline from good,"},
{"c":3,"v":24,"d":"उत्सीदेयुरिमे लोका न कुर्यां कर्म चेदहम्।\nसङ्करस्य च कर्ता स्यामुपहन्यामिमाः प्रजाः॥","t":"utsīdeyurime lokā na kuryāṃ karma cedaham|\nsaṅkarasya ca kartā syāmupahanyāmimāḥ prajāḥ||","e":"And I should break earth's order and commit\nHer offspring unto ruin, Bharata!"},
{"c":3,"v":25,"d":"सक्ताः कर्मण्यविद्वांसो यथा कुर्वन्ति भारत।\nकुर्याद्विद्वांस्तथासक्तश्िचकीर्षुर्लोकसंग्रहम्॥","t":"saktāḥ karmaṇyavidvāṃso yathā kurvanti bhārata|\nkuryādvidvāṃstathāsaktaścakīrṣurlokasaṃgraham||","e":"Even as the unknowing toil, wedded to sense,\nSo let the enlightened toil, sense-freed, but set\nTo bring the world deliverance, and its bliss;"},
{"c":3,"v":26,"d":"न बुद्धिभेदं जनयेदज्ञानां कर्मसङ्गिनाम्।\nजोषयेत्सर्वकर्माणि विद्वान् युक्तः समाचरन्॥","t":"na buddhibhedaṃ janayedajñānāṃ karmasaṅginām|\njoṣayetsarvakarmāṇi vidvān yuktaḥ samācaran||","e":"Not sowing in those simple, busy hearts\nSeed of despair. Yea! let each play his part\nIn all he finds to do, with unyoked soul."},
{"c":3,"v":27,"d":"प्रकृतेः क्रियमाणानि गुणैः कर्माणि सर्वशः।\nअहङ्कारविमूढात्मा कर्ताऽहमिति मन्यते॥","t":"prakṛteḥ kriyamāṇāni guṇaiḥ karmāṇi sarvaśaḥ|\nahaṅkāravimūḍhātmā kartā'hamiti manyate||","e":"All things are everywhere by Nature wrought\nIn interaction of the qualities.\nThe fool, cheated by self, thinks, \"This I did\"\nAnd \"That I wrought; \""},
{"c":3,"v":28,"d":"तत्त्ववित्तु महाबाहो गुणकर्मविभागयोः।\nगुणा गुणेषु वर्तन्त इति मत्वा न सज्जते॥","t":"tattvavittu mahābāho guṇakarmavibhāgayoḥ|\nguṇā guṇeṣu vartanta iti matvā na sajjate||","e":"but--ah, thou strong-armed Prince!--\nA better-lessoned mind, knowing the play\nOf visible things within the world of sense,\nAnd how the qualities must qualify,\nStandeth aloof even from his acts."},
{"c":3,"v":29,"d":"प्रकृतेर्गुणसम्मूढाः सज्जन्ते गुणकर्मसु।\nतानकृत्स्नविदो मन्दान्कृत्स्नविन्न विचालयेत्॥","t":"prakṛterguṇasammūḍhāḥ sajjante guṇakarmasu|\ntānakṛtsnavido mandānkṛtsnavinna vicālayet||","e":"Th' untaught\nLive mixed with them, knowing not Nature's way,\nOf highest aims unwitting, slow and dull.\nThose make thou not to stumble, having the light;"},
{"c":3,"v":30,"d":"मयि सर्वाणि कर्माणि संन्यस्याध्यात्मचेतसा।\nनिराशीर्निर्ममो भूत्वा युध्यस्व विगतज्वरः॥","t":"mayi sarvāṇi karmāṇi saṃnyasyādhyātmacetasā|\nnirāśīrnirmamo bhūtvā yudhyasva vigatajvaraḥ||","e":"But all thy dues discharging, for My sake,\nWith meditation centred inwardly,\nSeeking no profit, satisfied, serene,\nHeedless of issue--fight!"},
{"c":3,"v":31,"d":"ये मे मतमिदं नित्यमनुतिष्ठन्ति मानवाः।\nश्रद्धावन्तोऽनसूयन्तो मुच्यन्ते तेऽपि कर्मभिः॥","t":"ye me matamidaṃ nityamanutiṣṭhanti mānavāḥ|\nśraddhāvanto'nasūyanto mucyante te'pi karmabhiḥ||","e":"They who shall keep\nMy ordinance thus, the wise and willing hearts,\nHave quittance from all issue of their acts;"},
{"c":3,"v":32,"d":"ये त्वेतदभ्यसूयन्तो नानुतिष्ठन्ति मे मतम्।\nसर्वज्ञानविमूढांस्तान्विद्धि नष्टानचेतसः॥","t":"ye tvetadabhyasūyanto nānutiṣṭhanti me matam|\nsarvajñānavimūḍhāṃstānviddhi naṣṭānacetasaḥ||","e":"But those who disregard My ordinance,\nThinking they know, know nought, and fall to loss,\nConfused and foolish."},
{"c":3,"v":33,"d":"सदृशं चेष्टते स्वस्याः प्रकृतेर्ज्ञानवानपि।\nप्रकृतिं यान्ति भूतानि निग्रहः किं करिष्यति॥","t":"sadṛśaṃ ceṣṭate svasyāḥ prakṛterjñānavānapi|\nprakṛtiṃ yānti bhūtāni nigrahaḥ kiṃ kariṣyati||","e":"'Sooth, the instructed one\nDoth of his kind, following what fits him most:\nAnd lower creatures of their kind; in vain\nContending 'gainst the law."},
{"c":3,"v":34,"d":"इन्द्रियस्येन्द्रियस्यार्थे रागद्वेषौ व्यवस्थितौ।\nतयोर्न वशमागच्छेत्तौ ह्यस्य परिपन्थिनौ॥","t":"indriyasyendriyasyārthe rāgadveṣau vyavasthitau|\ntayorna vaśamāgacchettau hyasya paripanthinau||","e":"Needs must it be\nThe objects of the sense will stir the sense\nTo like and dislike, yet th' enlightened man\nYields not to these, knowing them enemies."},
{"c":3,"v":35,"d":"श्रेयान्स्वधर्मो विगुणः परधर्मात्स्वनुष्ठितात्।\nस्वधर्मे निधनं श्रेयः परधर्मो भयावहः॥","t":"śreyānsvadharmo viguṇaḥ paradharmātsvanuṣṭhitāt|\nsvadharme nidhanaṃ śreyaḥ paradharmo bhayāvahaḥ||","e":"Finally, this is better, that one do\nHis own task as he may, even though he fail,\nThan take tasks not his own, though they seem good.\nTo die performing duty is no ill;\nBut who seeks other roads shall wander still."},
{"c":3,"v":36,"d":"अर्जुन उवाच\nअथ केन प्रयुक्तोऽयं पापं चरति पूरुषः।\nअनिच्छन्नपि वार्ष्णेय बलादिव नियोजितः॥","t":"arjuna uvāca\natha kena prayukto'yaṃ pāpaṃ carati pūruṣaḥ|\nanicchannapi vārṣṇeya balādiva niyojitaḥ||","e":"Arjuna.\nYet tell me, Teacher! by what force doth man\nGo to his ill, unwilling; as if one\nPushed him that evil path?"},
{"c":3,"v":37,"d":"श्री भगवानुवाच\nकाम एष क्रोध एष रजोगुणसमुद्भवः।\nमहाशनो महापाप्मा विद्ध्येनमिह वैरिणम्॥","t":"śrī bhagavānuvāca\nkāma eṣa krodha eṣa rajoguṇasamudbhavaḥ|\nmahāśano mahāpāpmā viddhyenamiha vairiṇam||","e":"Krishna.\nKama it is!\nPassion it is! born of the Darknesses,\nWhich pusheth him. Mighty of appetite,\nSinful, and strong is this!--man's enemy!"},
{"c":3,"v":38,"d":"धूमेनाव्रियते वह्निर्यथाऽऽदर्शो मलेन च।\nयथोल्बेनावृतो गर्भस्तथा तेनेदमावृतम्॥","t":"dhūmenāvriyate vahniryathā''darśo malena ca|\nyatholbenāvṛto garbhastathā tenedamāvṛtam||","e":"As smoke blots the white fire, as clinging rust\nMars the bright mirror, as the womb surrounds\nThe babe unborn, so is the world of things\nFoiled, soiled, enclosed in this desire of flesh."},
{"c":3,"v":39,"d":"आवृतं ज्ञानमेतेन ज्ञानिनो नित्यवैरिणा।\nकामरूपेण कौन्तेय दुष्पूरेणानलेन च॥","t":"āvṛtaṃ jñānametena jñānino nityavairiṇā|\nkāmarūpeṇa kaunteya duṣpūreṇānalena ca||","e":"The wise fall, caught in it; the unresting foe\nIt is of wisdom, wearing countless forms,\nFair but deceitful, subtle as a flame."},
{"c":3,"v":40,"d":"इन्द्रियाणि मनो बुद्धिरस्याधिष्ठानमुच्यते।\nएतैर्विमोहयत्येष ज्ञानमावृत्य देहिनम्॥","t":"indriyāṇi mano buddhirasyādhiṣṭhānamucyate|\netairvimohayatyeṣa jñānamāvṛtya dehinam||","e":"Sense, mind, and reason--these, O Kunti's Son!\nAre booty for it; in its play with these\nIt maddens man, beguiling, blinding him."},
{"c":3,"v":41,"d":"तस्मात्त्वमिन्द्रियाण्यादौ नियम्य भरतर्षभ।\nपाप्मानं प्रजहि ह्येनं ज्ञानविज्ञाननाशनम्॥","t":"tasmāttvamindriyāṇyādau niyamya bharatarṣabha|\npāpmānaṃ prajahi hyenaṃ jñānavijñānanāśanam||","e":"Therefore, thou noblest child of Bharata!\nGovern thy heart! Constrain th' entangled sense!\nResist the false, soft sinfulness which saps\nKnowledge and judgment!"},
{"c":3,"v":42,"d":"इन्द्रियाणि पराण्याहुरिन्द्रियेभ्यः परं मनः।\nमनसस्तु परा बुद्धिर्यो बुद्धेः परतस्तु सः॥","t":"indriyāṇi parāṇyāhurindriyebhyaḥ paraṃ manaḥ|\nmanasastu parā buddhiryo buddheḥ paratastu saḥ||","e":"Yea, the world is strong,\nBut what discerns it stronger, and the mind\nStrongest; and high o'er all the ruling Soul."},
{"c":3,"v":43,"d":"एवं बुद्धेः परं बुद्ध्वा संस्तभ्यात्मानमात्मना।\nजहि शत्रुं महाबाहो कामरूपं दुरासदम्॥","t":"evaṃ buddheḥ paraṃ buddhvā saṃstabhyātmānamātmanā|\njahi śatruṃ mahābāho kāmarūpaṃ durāsadam||","e":"Wherefore, perceiving Him who reigns supreme,\nPut forth full force of Soul in thy own soul!\nFight! vanquish foes and doubts, dear Hero! slay\nWhat haunts thee in fond shapes, and would betray!"},
{"c":4,"v":1,"d":"श्री भगवानुवाच\nइमं विवस्वते योगं प्रोक्तवानहमव्ययम्।\nविवस्वान् मनवे प्राह मनुरिक्ष्वाकवेऽब्रवीत्॥","t":"śrī bhagavānuvāca\nimaṃ vivasvate yogaṃ proktavānahamavyayam|\nvivasvān manave prāha manurikṣvākave'bravīt||","e":"Krishna.\nThis deathless Yoga, this deep union,\nI taught Vivaswata, the Lord of Light;\nVivaswata to Manu gave it; he\nTo Ikshwaku;"},
{"c":4,"v":2,"d":"एवं परम्पराप्राप्तमिमं राजर्षयो विदुः।\nस कालेनेह महता योगो नष्टः परन्तप॥","t":"evaṃ paramparāprāptamimaṃ rājarṣayo viduḥ|\nsa kāleneha mahatā yogo naṣṭaḥ parantapa||","e":"so passed it down the line\nOf all my royal Rishis. Then, with years,\nThe truth grew dim and perished, noble Prince!"},
{"c":4,"v":3,"d":"स एवायं मया तेऽद्य योगः प्रोक्तः पुरातनः।\nभक्तोऽसि मे सखा चेति रहस्यं ह्येतदुत्तमम्॥","t":"sa evāyaṃ mayā te'dya yogaḥ proktaḥ purātanaḥ|\nbhakto'si me sakhā ceti rahasyaṃ hyetaduttamam||","e":"Now once again to thee it is declared--\nThis ancient lore, this mystery supreme--\nSeeing I find thee votary and friend."},
{"c":4,"v":4,"d":"अर्जुन उवाच\nअपरं भवतो जन्म परं जन्म विवस्वतः।\nकथमेतद्विजानीयां त्वमादौ प्रोक्तवानिति॥","t":"arjuna uvāca\naparaṃ bhavato janma paraṃ janma vivasvataḥ|\nkathametadvijānīyāṃ tvamādau proktavāniti||","e":"Arjuna.\nThy birth, dear Lord, was in these later days,\nAnd bright Vivaswata's preceded time!\nHow shall I comprehend this thing thou sayest,\n\"From the beginning it was I who taught?\""},
{"c":4,"v":5,"d":"श्री भगवानुवाच\nबहूनि मे व्यतीतानि जन्मानि तव चार्जुन।\nतान्यहं वेद सर्वाणि न त्वं वेत्थ परन्तप॥","t":"śrī bhagavānuvāca\nbahūni me vyatītāni janmāni tava cārjuna|\ntānyahaṃ veda sarvāṇi na tvaṃ vettha parantapa||","e":"Krishna.\nManifold the renewals of my birth\nHave been, Arjuna! and of thy births, too!\nBut mine I know, and thine thou knowest not,\nO Slayer of thy Foes!"},
{"c":4,"v":6,"d":"अजोऽपि सन्नव्ययात्मा भूतानामीश्वरोऽपि सन्।\nप्रकृतिं स्वामधिष्ठाय संभवाम्यात्ममायया॥","t":"ajo'pi sannavyayātmā bhūtānāmīśvaro'pi san|\nprakṛtiṃ svāmadhiṣṭhāya saṃbhavāmyātmamāyayā||","e":"Albeit I be\nUnborn, undying, indestructible,\nThe Lord of all things living; not the less--\nBy Maya, by my magic which I stamp\nOn floating Nature-forms, the primal vast--\nI come, and go, and come."},
{"c":4,"v":7,"d":"यदा यदा हि धर्मस्य ग्लानिर्भवति भारत।\nअभ्युत्थानमधर्मस्य तदाऽऽत्मानं सृजाम्यहम्॥","t":"yadā yadā hi dharmasya glānirbhavati bhārata|\nabhyutthānamadharmasya tadā''tmānaṃ sṛjāmyaham||","e":"When Righteousness\nDeclines, O Bharata! when Wickedness\nIs strong, I rise,"},
{"c":4,"v":8,"d":"परित्राणाय साधूनां विनाशाय च दुष्कृताम्।\nधर्मसंस्थापनार्थाय संभवामि युगे युगे॥","t":"paritrāṇāya sādhūnāṃ vināśāya ca duṣkṛtām|\ndharmasaṃsthāpanārthāya saṃbhavāmi yuge yuge||","e":"from age to age, and take\nVisible shape, and move a man with men,\nSuccouring the good, thrusting the evil back,\nAnd setting Virtue on her seat again."},
{"c":4,"v":9,"d":"जन्म कर्म च मे दिव्यमेवं यो वेत्ति तत्त्वतः।\nत्यक्त्वा देहं पुनर्जन्म नैति मामेति सोऽर्जुन॥","t":"janma karma ca me divyamevaṃ yo vetti tattvataḥ|\ntyaktvā dehaṃ punarjanma naiti māmeti so'rjuna||","e":"Who knows the truth touching my births on earth\nAnd my divine work, when he quits the flesh\nPuts on its load no more, falls no more down\nTo earthly birth: to Me he comes, dear Prince!"},
{"c":4,"v":10,"d":"वीतरागभयक्रोधा मन्मया मामुपाश्रिताः।\nबहवो ज्ञानतपसा पूता मद्भावमागताः॥","t":"vītarāgabhayakrodhā manmayā māmupāśritāḥ|\nbahavo jñānatapasā pūtā madbhāvamāgatāḥ||","e":"Many there be who come! from fear set free,\nFrom anger, from desire; keeping their hearts\nFixed upon me--my Faithful--purified\nBy sacred flame of Knowledge. Such as these\nMix with my being."},
{"c":4,"v":11,"d":"ये यथा मां प्रपद्यन्ते तांस्तथैव भजाम्यहम्।\nमम वर्त्मानुवर्तन्ते मनुष्याः पार्थ सर्वशः॥","t":"ye yathā māṃ prapadyante tāṃstathaiva bhajāmyaham|\nmama vartmānuvartante manuṣyāḥ pārtha sarvaśaḥ||","e":"Whoso worship me,\nThem I exalt; but all men everywhere\nShall fall into my path;"},
{"c":4,"v":12,"d":"काङ्क्षन्तः कर्मणां सिद्धिं यजन्त इह देवताः।\nक्षिप्रं हि मानुषे लोके सिद्धिर्भवति कर्मजा॥","t":"kāṅkṣantaḥ karmaṇāṃ siddhiṃ yajanta iha devatāḥ|\nkṣipraṃ hi mānuṣe loke siddhirbhavati karmajā||","e":"albeit, those souls\nWhich seek reward for works, make sacrifice\nNow, to the lower gods. I say to thee\nHere have they their reward."},
{"c":4,"v":13,"d":"चातुर्वर्ण्यं मया सृष्टं गुणकर्मविभागशः।\nतस्य कर्तारमपि मां विद्ध्यकर्तारमव्ययम्॥","t":"cāturvarṇyaṃ mayā sṛṣṭaṃ guṇakarmavibhāgaśaḥ|\ntasya kartāramapi māṃ viddhyakartāramavyayam||","e":"But I am He\nMade the Four Castes, and portioned them a place\nAfter their qualities and gifts. Yea, I\nCreated, the Reposeful; I that live\nImmortally, made all those mortal births:"},
{"c":4,"v":14,"d":"न मां कर्माणि लिम्पन्ति न मे कर्मफले स्पृहा।\nइति मां योऽभिजानाति कर्मभिर्न स बध्यते॥","t":"na māṃ karmāṇi limpanti na me karmaphale spṛhā|\niti māṃ yo'bhijānāti karmabhirna sa badhyate||","e":"For works soil not my essence, being works\nWrought uninvolved. Who knows me acting thus\nUnchained by action, action binds not him;"},
{"c":4,"v":15,"d":"एवं ज्ञात्वा कृतं कर्म पूर्वैरपि मुमुक्षुभिः।\nकुरु कर्मैव तस्मात्त्वं पूर्वैः पूर्वतरं कृतम्॥","t":"evaṃ jñātvā kṛtaṃ karma pūrvairapi mumukṣubhiḥ|\nkuru karmaiva tasmāttvaṃ pūrvaiḥ pūrvataraṃ kṛtam||","e":"And, so perceiving, all those saints of old\nWorked, seeking for deliverance. Work thou\nAs, in the days gone by, thy fathers did."},
{"c":4,"v":16,"d":"किं कर्म किमकर्मेति कवयोऽप्यत्र मोहिताः।\nतत्ते कर्म प्रवक्ष्यामि यज्ज्ञात्वा मोक्ष्यसेऽशुभात्॥","t":"kiṃ karma kimakarmeti kavayo'pyatra mohitāḥ|\ntatte karma pravakṣyāmi yajjñātvā mokṣyase'śubhāt||","e":"Thou sayst, perplexed, It hath been asked before\nBy singers and by sages, \"What is act,\nAnd what inaction? \"I will teach thee this,\nAnd, knowing, thou shalt learn which work doth save"},
{"c":4,"v":17,"d":"कर्मणो ह्यपि बोद्धव्यं बोद्धव्यं च विकर्मणः।\nअकर्मणश्च बोद्धव्यं गहना कर्मणो गतिः॥","t":"karmaṇo hyapi boddhavyaṃ boddhavyaṃ ca vikarmaṇaḥ|\nakarmaṇaśca boddhavyaṃ gahanā karmaṇo gatiḥ||","e":"Needs must one rightly meditate those three--\nDoing,--not doing,--and undoing. Here\nThorny and dark the path is!"},
{"c":4,"v":18,"d":"कर्मण्यकर्म यः पश्येदकर्मणि च कर्म यः।\nस बुद्धिमान् मनुष्येषु स युक्तः कृत्स्नकर्मकृत्॥","t":"karmaṇyakarma yaḥ paśyedakarmaṇi ca karma yaḥ|\nsa buddhimān manuṣyeṣu sa yuktaḥ kṛtsnakarmakṛt||","e":"He who sees\nHow action may be rest, rest action--he\nIs wisest 'mid his kind; he hath the truth!\nHe doeth well, acting or resting."},
{"c":4,"v":19,"d":"यस्य सर्वे समारम्भाः कामसङ्कल्पवर्जिताः।\nज्ञानाग्निदग्धकर्माणं तमाहुः पण्डितं बुधाः॥","t":"yasya sarve samārambhāḥ kāmasaṅkalpavarjitāḥ|\njñānāgnidagdhakarmāṇaṃ tamāhuḥ paṇḍitaṃ budhāḥ||","e":"Freed\nIn all his works from prickings of desire,\nBurned clean in act by the white fire of truth,\nThe wise call that man wise;"},
{"c":4,"v":20,"d":"त्यक्त्वा कर्मफलासङ्गं नित्यतृप्तो निराश्रयः।\nकर्मण्यभिप्रवृत्तोऽपि नैव किञ्चित्करोति सः॥","t":"tyaktvā karmaphalāsaṅgaṃ nityatṛpto nirāśrayaḥ|\nkarmaṇyabhipravṛtto'pi naiva kiñcitkaroti saḥ||","e":"and such an one,\nRenouncing fruit of deeds, always content.\nAlways self-satisfying, if he works,\nDoth nothing that shall stain his separate soul,"},
{"c":4,"v":21,"d":"निराशीर्यतचित्तात्मा त्यक्तसर्वपरिग्रहः।\nशारीरं केवलं कर्म कुर्वन्नाप्नोति किल्बिषम्॥","t":"nirāśīryatacittātmā tyaktasarvaparigrahaḥ|\nśārīraṃ kevalaṃ karma kurvannāpnoti kilbiṣam||","e":"Which--quit of fear and hope--subduing self--\nRejecting outward impulse--yielding up\nTo body's need nothing save body, dwells\nSinless amid all sin,"},
{"c":4,"v":22,"d":"यदृच्छालाभसन्तुष्टो द्वन्द्वातीतो विमत्सरः।\nसमः सिद्धावसिद्धौ च कृत्वापि न निबध्यते॥","t":"yadṛcchālābhasantuṣṭo dvandvātīto vimatsaraḥ|\nsamaḥ siddhāvasiddhau ca kṛtvāpi na nibadhyate||","e":"with equal calm\nTaking what may befall, by grief unmoved,\nUnmoved by joy, unenvyingly; the same\nIn good and evil fortunes; nowise bound\nBy bond of deeds."},
{"c":4,"v":23,"d":"गतसङ्गस्य मुक्तस्य ज्ञानावस्थितचेतसः।\nयज्ञायाचरतः कर्म समग्रं प्रविलीयते॥","t":"gatasaṅgasya muktasya jñānāvasthitacetasaḥ|\nyajñāyācarataḥ karma samagraṃ pravilīyate||","e":"Nay, but of such an one,\nWhose crave is gone, whose soul is liberate,\nWhose heart is set on truth--of such an one\nWhat work he does is work of sacrifice,\nWhich passeth purely into ash and smoke\nConsumed upon the altar!"},
{"c":4,"v":24,"d":"ब्रह्मार्पणं ब्रह्महविर्ब्रह्माग्नौ ब्रह्मणा हुतम्।\nब्रह्मैव तेन गन्तव्यं ब्रह्मकर्मसमाधिना॥","t":"brahmārpaṇaṃ brahmahavirbrahmāgnau brahmaṇā hutam|\nbrahmaiva tena gantavyaṃ brahmakarmasamādhinā||","e":"All's then God!\nThe sacrifice is Brahm, the ghee and grain\nAre Brahm, the fire is Brahm, the flesh it eats\nIs Brahm, and unto Brahm attaineth he\nWho, in such office, meditates on Brahm."},
{"c":4,"v":25,"d":"दैवमेवापरे यज्ञं योगिनः पर्युपासते।\nब्रह्माग्नावपरे यज्ञं यज्ञेनैवोपजुह्वति॥","t":"daivamevāpare yajñaṃ yoginaḥ paryupāsate|\nbrahmāgnāvapare yajñaṃ yajñenaivopajuhvati||","e":"Some votaries there be who serve the gods\nWith flesh and altar-smoke; but other some\nWho, lighting subtler fires, make purer rite\nWith will of worship."},
{"c":4,"v":26,"d":"श्रोत्रादीनीन्द्रियाण्यन्ये संयमाग्निषु जुह्वति।\nशब्दादीन्विषयानन्य इन्द्रियाग्निषु जुह्वति॥","t":"śrotrādīnīndriyāṇyanye saṃyamāgniṣu juhvati|\nśabdādīnviṣayānanya indriyāgniṣu juhvati||","e":"Of the which be they\nWho, in white flame of continence, consume\nJoys of the sense, delights of eye and ear,\nForgoing tender speech and sound of song:"},
{"c":4,"v":27,"d":"सर्वाणीन्द्रियकर्माणि प्राणकर्माणि चापरे।\nआत्मसंयमयोगाग्नौ जुह्वति ज्ञानदीपिते॥","t":"sarvāṇīndriyakarmāṇi prāṇakarmāṇi cāpare|\nātmasaṃyamayogāgnau juhvati jñānadīpite||","e":"And they who, kindling fires with torch of Truth,\nBurn on a hidden altar-stone the bliss\nOf youth and love, renouncing happiness:"},
{"c":4,"v":28,"d":"द्रव्ययज्ञास्तपोयज्ञा योगयज्ञास्तथापरे।\nस्वाध्यायज्ञानयज्ञाश्च यतयः संशितव्रताः॥","t":"dravyayajñāstapoyajñā yogayajñāstathāpare|\nsvādhyāyajñānayajñāśca yatayaḥ saṃśitavratāḥ||","e":"And they who lay for offering there their wealth,\nTheir penance, meditation, piety,\nTheir steadfast reading of the scrolls, their lore\nPainfully gained with long austerities:"},
{"c":4,"v":29,"d":"अपाने जुह्वति प्राण प्राणेऽपानं तथाऽपरे।\nप्राणापानगती रुद्ध्वा प्राणायामपरायणाः॥","t":"apāne juhvati prāṇa prāṇe'pānaṃ tathā'pare|\nprāṇāpānagatī ruddhvā prāṇāyāmaparāyaṇāḥ||","e":"And they who, making silent sacrifice,\nDraw in their breath to feed the flame of thought,\nAnd breathe it forth to waft the heart on high,\nGoverning the ventage of each entering air\nLest one sigh pass which helpeth not the soul:"},
{"c":4,"v":30,"d":"अपरे नियताहाराः प्राणान्प्राणेषु जुह्वति।\nसर्वेऽप्येते यज्ञविदो यज्ञक्षपितकल्मषाः॥","t":"apare niyatāhārāḥ prāṇānprāṇeṣu juhvati|\nsarve'pyete yajñavido yajñakṣapitakalmaṣāḥ||","e":"And they who, day by day denying needs,\nLay life itself upon the altar-flame,\nBurning the body wan. Lo! all these keep\nThe rite of offering, as if they slew\nVictims; and all thereby efface much sin."},
{"c":4,"v":31,"d":"यज्ञशिष्टामृतभुजो यान्ति ब्रह्म सनातनम्।\nनायं लोकोऽस्त्ययज्ञस्य कुतो़ऽन्यः कुरुसत्तम॥","t":"yajñaśiṣṭāmṛtabhujo yānti brahma sanātanam|\nnāyaṃ loko'styayajñasya kuto'nyaḥ kurusattama||","e":"Yea! and who feed on the immortal food\nLeft of such sacrifice, to Brahma pass,\nTo The Unending. But for him that makes\nNo sacrifice, he hath nor part nor lot\nEven in the present world. How should he share\nAnother, O thou Glory of thy Line?"},
{"c":4,"v":32,"d":"एवं बहुविधा यज्ञा वितता ब्रह्मणो मुखे।\nकर्मजान्विद्धि तान्सर्वानेवं ज्ञात्वा विमोक्ष्यसे॥","t":"evaṃ bahuvidhā yajñā vitatā brahmaṇo mukhe|\nkarmajānviddhi tānsarvānevaṃ jñātvā vimokṣyase||","e":"In sight of Brahma all these offerings\nAre spread and are accepted! Comprehend\nThat all proceed by act; for knowing this,\nThou shalt be quit of doubt."},
{"c":4,"v":33,"d":"श्रेयान्द्रव्यमयाद्यज्ञाज्ज्ञानयज्ञः परन्तप।\nसर्वं कर्माखिलं पार्थ ज्ञाने परिसमाप्यते॥","t":"śreyāndravyamayādyajñājjñānayajñaḥ parantapa|\nsarvaṃ karmākhilaṃ pārtha jñāne parisamāpyate||","e":"The sacrifice\nWhich Knowledge pays is better than great gifts\nOffered by wealth, since gifts' worth--O my Prince!\nLies in the mind which gives, the will that serves:"},
{"c":4,"v":34,"d":"तद्विद्धि प्रणिपातेन परिप्रश्नेन सेवया।\nउपदेक्ष्यन्ति ते ज्ञानं ज्ञानिनस्तत्त्वदर्शिनः॥","t":"tadviddhi praṇipātena paripraśnena sevayā|\nupadekṣyanti te jñānaṃ jñāninastattvadarśinaḥ||","e":"And these are gained by reverence, by strong search,\nBy humble heed of those who see the Truth\nAnd teach it."},
{"c":4,"v":35,"d":"यज्ज्ञात्वा न पुनर्मोहमेवं यास्यसि पाण्डव।\nयेन भूतान्यशेषेण द्रक्ष्यस्यात्मन्यथो मयि॥","t":"yajjñātvā na punarmohamevaṃ yāsyasi pāṇḍava|\nyena bhūtānyaśeṣeṇa drakṣyasyātmanyatho mayi||","e":"Knowing Truth, thy heart no more\nWill ache with error, for the Truth shall show\nAll things subdued to thee, as thou to Me."},
{"c":4,"v":36,"d":"अपि चेदसि पापेभ्यः सर्वेभ्यः पापकृत्तमः।\nसर्वं ज्ञानप्लवेनैव वृजिनं सन्तरिष्यसि॥","t":"api cedasi pāpebhyaḥ sarvebhyaḥ pāpakṛttamaḥ|\nsarvaṃ jñānaplavenaiva vṛjinaṃ santariṣyasi||","e":"Moreover, Son of Pandu! wert thou worst\nOf all wrong-doers, this fair ship of Truth\nShould bear thee safe and dry across the sea\nOf thy transgressions."},
{"c":4,"v":37,"d":"यथैधांसि समिद्धोऽग्निर्भस्मसात्कुरुतेऽर्जुन।\nज्ञानाग्निः सर्वकर्माणि भस्मसात्कुरुते तथा॥","t":"yathaidhāṃsi samiddho'gnirbhasmasātkurute'rjuna|\njñānāgniḥ sarvakarmāṇi bhasmasātkurute tathā||","e":"As the kindled flame\nFeeds on the fuel till it sinks to ash,\nSo unto ash, Arjuna! unto nought\nThe flame of Knowledge wastes works' dross away!"},
{"c":4,"v":38,"d":"न हि ज्ञानेन सदृशं पवित्रमिह विद्यते।\nतत्स्वयं योगसंसिद्धः कालेनात्मनि विन्दति॥","t":"na hi jñānena sadṛśaṃ pavitramiha vidyate|\ntatsvayaṃ yogasaṃsiddhaḥ kālenātmani vindati||","e":"There is no purifier like thereto\nIn all this world, and he who seeketh it\nShall find it--being grown perfect--in himself."},
{"c":4,"v":39,"d":"श्रद्धावाँल्लभते ज्ञानं तत्परः संयतेन्द्रियः।\nज्ञानं लब्ध्वा परां शान्तिमचिरेणाधिगच्छति॥","t":"śraddhāvām̐llabhate jñānaṃ tatparaḥ saṃyatendriyaḥ|\njñānaṃ labdhvā parāṃ śāntimacireṇādhigacchati||","e":"Believing, he receives it when the soul\nMasters itself, and cleaves to Truth, and comes--\nPossessing knowledge--to the higher peace,\nThe uttermost repose."},
{"c":4,"v":40,"d":"अज्ञश्चाश्रद्दधानश्च संशयात्मा विनश्यति।\nनायं लोकोऽस्ति न परो न सुखं संशयात्मनः॥","t":"ajñaścāśraddadhānaśca saṃśayātmā vinaśyati|\nnāyaṃ loko'sti na paro na sukhaṃ saṃśayātmanaḥ||","e":"But those untaught,\nAnd those without full faith, and those who fear\nAre shent; no peace is here or other where,\nNo hope, nor happiness for whoso doubts."},
{"c":4,"v":41,"d":"योगसंन्यस्तकर्माणं ज्ञानसंछिन्नसंशयम्।\nआत्मवन्तं न कर्माणि निबध्नन्ति धनञ्जय॥","t":"yogasaṃnyastakarmāṇaṃ jñānasaṃchinnasaṃśayam|\nātmavantaṃ na karmāṇi nibadhnanti dhanañjaya||","e":"He that, being self-contained, hath vanquished doubt,\nDisparting self from service, soul from works,\nEnlightened and emancipate, my Prince!\nWorks fetter him no more!"},
{"c":4,"v":42,"d":"तस्मादज्ञानसंभूतं हृत्स्थं ज्ञानासिनाऽऽत्मनः।\nछित्त्वैनं संशयं योगमातिष्ठोत्तिष्ठ भारत॥","t":"tasmādajñānasaṃbhūtaṃ hṛtsthaṃ jñānāsinā''tmanaḥ|\nchittvainaṃ saṃśayaṃ yogamātiṣṭhottiṣṭha bhārata||","e":"Cut then atwain\nWith sword of wisdom, Son of Bharata!\nThis doubt that binds thy heart-beats! cleave the bond\nBorn of thy ignorance! Be bold and wise!\nGive thyself to the field with me! Arise!"},
{"c":5,"v":1,"d":"अर्जुन उवाच\nसंन्यासं कर्मणां कृष्ण पुनर्योगं च शंससि।\nयच्छ्रेय एतयोरेकं तन्मे ब्रूहि सुनिश्िचतम्॥","t":"arjuna uvāca\nsaṃnyāsaṃ karmaṇāṃ kṛṣṇa punaryogaṃ ca śaṃsasi|\nyacchreya etayorekaṃ tanme brūhi suniścatam||","e":"Arjuna.\nYet, Krishna! at the one time thou dost laud\nSurcease of works, and, at another time,\nService through work. Of these twain plainly tell\nWhich is the better way?"},
{"c":5,"v":2,"d":"श्री भगवानुवाच\nसंन्यासः कर्मयोगश्च निःश्रेयसकरावुभौ।\nतयोस्तु कर्मसंन्यासात्कर्मयोगो विशिष्यते॥","t":"śrī bhagavānuvāca\nsaṃnyāsaḥ karmayogaśca niḥśreyasakarāvubhau|\ntayostu karmasaṃnyāsātkarmayogo viśiṣyate||","e":"Krishna.\nTo cease from works\nIs well, and to do works in holiness\nIs well; and both conduct to bliss supreme;\nBut of these twain the better way is his\nWho working piously refraineth not."},
{"c":5,"v":3,"d":"ज्ञेयः स नित्यसंन्यासी यो न द्वेष्टि न काङ्क्षति।\nनिर्द्वन्द्वो हि महाबाहो सुखं बन्धात्प्रमुच्यते॥","t":"jñeyaḥ sa nityasaṃnyāsī yo na dveṣṭi na kāṅkṣati|\nnirdvandvo hi mahābāho sukhaṃ bandhātpramucyate||","e":"That is the true Renouncer, firm and fixed,\nWho--seeking nought, rejecting nought--dwells proof\nAgainst the \"opposites.\" O valiant Prince!\nIn doing, such breaks lightly from all deed:"},
{"c":5,"v":4,"d":"सांख्ययोगौ पृथग्बालाः प्रवदन्ति न पण्डिताः।\nएकमप्यास्थितः सम्यगुभयोर्विन्दते फलम्॥","t":"sāṃkhyayogau pṛthagbālāḥ pravadanti na paṇḍitāḥ|\nekamapyāsthitaḥ samyagubhayorvindate phalam||","e":"'Tis the new scholar talks as they were two,\nThis Sankhya and this Yoga: wise men know\nWho husbands one plucks golden fruit of both!"},
{"c":5,"v":5,"d":"यत्सांख्यैः प्राप्यते स्थानं तद्योगैरपि गम्यते।\nएकं सांख्यं च योगं च यः पश्यति स पश्यति॥","t":"yatsāṃkhyaiḥ prāpyate sthānaṃ tadyogairapi gamyate|\nekaṃ sāṃkhyaṃ ca yogaṃ ca yaḥ paśyati sa paśyati||","e":"The region of high rest which Sankhyans reach\nYogins attain. Who sees these twain as one\nSees with clear eyes!"},
{"c":5,"v":6,"d":"संन्यासस्तु महाबाहो दुःखमाप्तुमयोगतः।\nयोगयुक्तो मुनिर्ब्रह्म नचिरेणाधिगच्छति॥","t":"saṃnyāsastu mahābāho duḥkhamāptumayogataḥ|\nyogayukto munirbrahma nacireṇādhigacchati||","e":"Yet such abstraction, Chief!\nIs hard to win without much holiness.\nWhoso is fixed in holiness, self-ruled,\nPure-hearted, lord of senses and of self,\nLost in the common life of all which lives--\nA \"Yogayukt\"--he is a Saint who wends\nStraightway to Brahm. Such an one is not touched\nBy taint of deeds.","g":[6,7]},
{"c":5,"v":7,"d":"योगयुक्तो विशुद्धात्मा विजितात्मा जितेन्द्रियः।\nसर्वभूतात्मभूतात्मा कुर्वन्नपि न लिप्यते॥","t":"yogayukto viśuddhātmā vijitātmā jitendriyaḥ|\nsarvabhūtātmabhūtātmā kurvannapi na lipyate||","e":"Yet such abstraction, Chief!\nIs hard to win without much holiness.\nWhoso is fixed in holiness, self-ruled,\nPure-hearted, lord of senses and of self,\nLost in the common life of all which lives--\nA \"Yogayukt\"--he is a Saint who wends\nStraightway to Brahm. Such an one is not touched\nBy taint of deeds.","g":[6,7]},
{"c":5,"v":8,"d":"नैव किंचित्करोमीति युक्तो मन्येत तत्त्ववित्।\nपश्यन् श्रृणवन्स्पृशञ्जिघ्रन्नश्नन्गच्छन्स्वपन् श्वसन्॥","t":"naiva kiṃcitkaromīti yukto manyeta tattvavit|\npaśyan śrṛṇavanspṛśañjighrannaśnangacchansvapan śvasan||","e":"\"Nought of myself I do!\"\nThus will he think-who holds the truth of truths--\nIn seeing, hearing, touching, smelling; when\nHe eats, or goes, or breathes; slumbers"},
{"c":5,"v":9,"d":"प्रलपन्विसृजन्गृह्णन्नुन्मिषन्निमिषन्नपि।\nइन्द्रियाणीन्द्रियार्थेषु वर्तन्त इति धारयन्॥","t":"pralapanvisṛjangṛhṇannunmiṣannimiṣannapi|\nindriyāṇīndriyārtheṣu vartanta iti dhārayan||","e":"or talks,\nHolds fast or loosens, opes his eyes or shuts;\nAlways assured \"This is the sense-world plays\nWith senses.\""},
{"c":5,"v":10,"d":"ब्रह्मण्याधाय कर्माणि सङ्गं त्यक्त्वा करोति यः।\nलिप्यते न स पापेन पद्मपत्रमिवाम्भसा॥","t":"brahmaṇyādhāya karmāṇi saṅgaṃ tyaktvā karoti yaḥ|\nlipyate na sa pāpena padmapatramivāmbhasā||","e":"He that acts in thought of Brahm,\nDetaching end from act, with act content,\nThe world of sense can no more stain his soul\nThan waters mar th' enamelled lotus-leaf."},
{"c":5,"v":11,"d":"कायेन मनसा बुद्ध्या केवलैरिन्द्रियैरपि।\nयोगिनः कर्म कुर्वन्ति सङ्गं त्यक्त्वाऽऽत्मशुद्धये॥","t":"kāyena manasā buddhyā kevalairindriyairapi|\nyoginaḥ karma kurvanti saṅgaṃ tyaktvā''tmaśuddhaye||","e":"With life, with heart, with mind,-nay, with the help\nOf all five senses--letting selfhood go--\nYogins toil ever towards their souls' release."},
{"c":5,"v":12,"d":"युक्तः कर्मफलं त्यक्त्वा शान्तिमाप्नोति नैष्ठिकीम्।\nअयुक्तः कामकारेण फले सक्तो निबध्यते॥","t":"yuktaḥ karmaphalaṃ tyaktvā śāntimāpnoti naiṣṭhikīm|\nayuktaḥ kāmakāreṇa phale sakto nibadhyate||","e":"Such votaries, renouncing fruit of deeds,\nGain endless peace: the unvowed, the passion-bound,\nSeeking a fruit from works, are fastened down."},
{"c":5,"v":13,"d":"सर्वकर्माणि मनसा संन्यस्यास्ते सुखं वशी।\nनवद्वारे पुरे देही नैव कुर्वन्न कारयन्॥","t":"sarvakarmāṇi manasā saṃnyasyāste sukhaṃ vaśī|\nnavadvāre pure dehī naiva kurvanna kārayan||","e":"The embodied sage, withdrawn within his soul,\nAt every act sits godlike in \"the town\nWhich hath nine gateways,\" neither doing aught\nNor causing any deed."},
{"c":5,"v":14,"d":"न कर्तृत्वं न कर्माणि लोकस्य सृजति प्रभुः।\nन कर्मफलसंयोगं स्वभावस्तु प्रवर्तते॥","t":"na kartṛtvaṃ na karmāṇi lokasya sṛjati prabhuḥ|\nna karmaphalasaṃyogaṃ svabhāvastu pravartate||","e":"This world's Lord makes\nNeither the work, nor passion for the work,\nNor lust for fruit of work; the man's own self\nPushes to these!"},
{"c":5,"v":15,"d":"नादत्ते कस्यचित्पापं न चैव सुकृतं विभुः।\nअज्ञानेनावृतं ज्ञानं तेन मुह्यन्ति जन्तवः॥","t":"nādatte kasyacitpāpaṃ na caiva sukṛtaṃ vibhuḥ|\najñānenāvṛtaṃ jñānaṃ tena muhyanti jantavaḥ||","e":"The Master of this World\nTakes on himself the good or evil deeds\nOf no man--dwelling beyond! Mankind errs here\nBy folly, darkening knowledge."},
{"c":5,"v":16,"d":"ज्ञानेन तु तदज्ञानं येषां नाशितमात्मनः।\nतेषामादित्यवज्ज्ञानं प्रकाशयति तत्परम्॥","t":"jñānena tu tadajñānaṃ yeṣāṃ nāśitamātmanaḥ|\nteṣāmādityavajjñānaṃ prakāśayati tatparam||","e":"But, for whom\nThat darkness of the soul is chased by light,\nSplendid and clear shines manifest the Truth\nAs if a Sun of Wisdom sprang to shed\nIts beams of dawn."},
{"c":5,"v":17,"d":"तद्बुद्धयस्तदात्मानस्तन्निष्ठास्तत्परायणाः।\nगच्छन्त्यपुनरावृत्तिं ज्ञाननिर्धूतकल्मषाः॥","t":"tadbuddhayastadātmānastanniṣṭhāstatparāyaṇāḥ|\ngacchantyapunarāvṛttiṃ jñānanirdhūtakalmaṣāḥ||","e":"Him meditating still,\nHim seeking, with Him blended, stayed on Him,\nThe souls illuminated take that road\nWhich hath no turning back--their sins flung off\nBy strength of faith. [Who will may have this Light;\nWho hath it sees.]"},
{"c":5,"v":18,"d":"विद्याविनयसंपन्ने ब्राह्मणे गवि हस्तिनि।\nशुनि चैव श्वपाके च पण्डिताः समदर्शिनः॥","t":"vidyāvinayasaṃpanne brāhmaṇe gavi hastini|\nśuni caiva śvapāke ca paṇḍitāḥ samadarśinaḥ||","e":"To him who wisely sees,\nThe Brahman with his scrolls and sanctities,\nThe cow, the elephant, the unclean dog,\nThe Outcast gorging dog's meat, are all one."},
{"c":5,"v":19,"d":"इहैव तैर्जितः सर्गो येषां साम्ये स्थितं मनः।\nनिर्दोषं हि समं ब्रह्म तस्माद्ब्रह्मणि ते स्थिताः॥","t":"ihaiva tairjitaḥ sargo yeṣāṃ sāmye sthitaṃ manaḥ|\nnirdoṣaṃ hi samaṃ brahma tasmādbrahmaṇi te sthitāḥ||","e":"The world is overcome--aye! even here!\nBy such as fix their faith on Unity.\nThe sinless Brahma dwells in Unity,\nAnd they in Brahma."},
{"c":5,"v":20,"d":"न प्रहृष्येत्प्रियं प्राप्य नोद्विजेत्प्राप्य चाप्रियम्।\nस्थिरबुद्धिरसम्मूढो ब्रह्मविद्ब्रह्मणि स्थितः॥","t":"na prahṛṣyetpriyaṃ prāpya nodvijetprāpya cāpriyam|\nsthirabuddhirasammūḍho brahmavidbrahmaṇi sthitaḥ||","e":"Be not over-glad\nAttaining joy, and be not over-sad\nEncountering grief, but, stayed on Brahma, still\nConstant let each abide!"},
{"c":5,"v":21,"d":"बाह्यस्पर्शेष्वसक्तात्मा विन्दत्यात्मनि यत्सुखम्।\nस ब्रह्मयोगयुक्तात्मा सुखमक्षयमश्नुते॥","t":"bāhyasparśeṣvasaktātmā vindatyātmani yatsukham|\nsa brahmayogayuktātmā sukhamakṣayamaśnute||","e":"The sage whose soul\nHolds off from outer contacts, in himself\nFinds bliss; to Brahma joined by piety,\nHis spirit tastes eternal peace."},
{"c":5,"v":22,"d":"ये हि संस्पर्शजा भोगा दुःखयोनय एव ते।\nआद्यन्तवन्तः कौन्तेय न तेषु रमते बुधः॥","t":"ye hi saṃsparśajā bhogā duḥkhayonaya eva te|\nādyantavantaḥ kaunteya na teṣu ramate budhaḥ||","e":"The joys\nSpringing from sense-life are but quickening wombs\nWhich breed sure griefs: those joys begin and end!\nThe wise mind takes no pleasure, Kunti's Son!\nIn such as those!"},
{"c":5,"v":23,"d":"शक्नोतीहैव यः सोढुं प्राक्शरीरविमोक्षणात्।\nकामक्रोधोद्भवं वेगं स युक्तः स सुखी नरः॥","t":"śaknotīhaiva yaḥ soḍhuṃ prākśarīravimokṣaṇāt|\nkāmakrodhodbhavaṃ vegaṃ sa yuktaḥ sa sukhī naraḥ||","e":"But if a man shall learn,\nEven while he lives and bears his body's chain,\nTo master lust and anger, he is blest!"},
{"c":5,"v":24,"d":"योऽन्तःसुखोऽन्तरारामस्तथान्तर्ज्योतिरेव यः।\nस योगी ब्रह्मनिर्वाणं ब्रह्मभूतोऽधिगच्छति॥","t":"yo'ntaḥsukho'ntarārāmastathāntarjyotireva yaḥ|\nsa yogī brahmanirvāṇaṃ brahmabhūto'dhigacchati||","e":"He is the Yukta; he hath happiness,\nContentment, light, within: his life is merged\nIn Brahma's life; he doth Nirvana touch!"},
{"c":5,"v":25,"d":"लभन्ते ब्रह्मनिर्वाणमृषयः क्षीणकल्मषाः।\nछिन्नद्वैधा यतात्मानः सर्वभूतहिते रताः॥","t":"labhante brahmanirvāṇamṛṣayaḥ kṣīṇakalmaṣāḥ|\nchinnadvaidhā yatātmānaḥ sarvabhūtahite ratāḥ||","e":"Thus go the Rishis unto rest, who dwell\nWith sins effaced, with doubts at end, with hearts\nGoverned and calm. Glad in all good they live,\nNigh to the peace of God;"},
{"c":5,"v":26,"d":"कामक्रोधवियुक्तानां यतीनां यतचेतसाम्।\nअभितो ब्रह्मनिर्वाणं वर्तते विदितात्मनाम्॥","t":"kāmakrodhaviyuktānāṃ yatīnāṃ yatacetasām|\nabhito brahmanirvāṇaṃ vartate viditātmanām||","e":"and all those live\nWho pass their days exempt from greed and wrath,\nSubduing self and senses, knowing the Soul!"},
{"c":5,"v":27,"d":"स्पर्शान्कृत्वा बहिर्बाह्यांश्चक्षुश्चैवान्तरे भ्रुवोः।\nप्राणापानौ समौ कृत्वा नासाभ्यन्तरचारिणौ॥","t":"sparśānkṛtvā bahirbāhyāṃścakṣuścaivāntare bhruvoḥ|\nprāṇāpānau samau kṛtvā nāsābhyantaracāriṇau||","e":"The Saint who shuts outside his placid soul\nAll touch of sense, letting no contact through;\nWhose quiet eyes gaze straight from fixed brows,\nWhose outward breath and inward breath are drawn\nEqual and slow through nostrils still and close;"},
{"c":5,"v":28,"d":"यतेन्द्रियमनोबुद्धिर्मुनिर्मोक्षपरायणः।\nविगतेच्छाभयक्रोधो यः सदा मुक्त एव सः॥","t":"yatendriyamanobuddhirmunirmokṣaparāyaṇaḥ|\nvigatecchābhayakrodho yaḥ sadā mukta eva saḥ||","e":"That one-with organs, heart, and mind constrained,\nBent on deliverance, having put away\nPassion, and fear, and rage;--hath, even now,\nObtained deliverance, ever and ever freed."},
{"c":5,"v":29,"d":"भोक्तारं यज्ञतपसां सर्वलोकमहेश्वरम्।\nसुहृदं सर्वभूतानां ज्ञात्वा मां शान्तिमृच्छति॥","t":"bhoktāraṃ yajñatapasāṃ sarvalokamaheśvaram|\nsuhṛdaṃ sarvabhūtānāṃ jñātvā māṃ śāntimṛcchati||","e":"Yea! for he knows Me Who am He that heeds\nThe sacrifice and worship, God revealed;\nAnd He who heeds not, being Lord of Worlds,\nLover of all that lives, God unrevealed,\nWherein who will shall find surety and shield!"},
{"c":6,"v":1,"d":"श्री भगवानुवाच\nअनाश्रितः कर्मफलं कार्यं कर्म करोति यः।\nस संन्यासी च योगी च न निरग्निर्न चाक्रियः॥","t":"śrī bhagavānuvāca\nanāśritaḥ karmaphalaṃ kāryaṃ karma karoti yaḥ|\nsa saṃnyāsī ca yogī ca na niragnirna cākriyaḥ||","e":"Krishna.\nTherefore, who doeth work rightful to do,\nNot seeking gain from work, that man, O Prince!\nIs Sanyasi and Yogi--both in one\nAnd he is neither who lights not the flame\nOf sacrifice, nor setteth hand to task."},
{"c":6,"v":2,"d":"यं संन्यासमिति प्राहुर्योगं तं विद्धि पाण्डव।\nन ह्यसंन्यस्तसङ्कल्पो योगी भवति कश्चन॥","t":"yaṃ saṃnyāsamiti prāhuryogaṃ taṃ viddhi pāṇḍava|\nna hyasaṃnyastasaṅkalpo yogī bhavati kaścana||","e":"Regard as true Renouncer him that makes\nWorship by work, for who renounceth not\nWorks not as Yogin."},
{"c":6,"v":3,"d":"आरुरुक्षोर्मुनेर्योगं कर्म कारणमुच्यते।\nयोगारूढस्य तस्यैव शमः कारणमुच्यते॥","t":"ārurukṣormuneryogaṃ karma kāraṇamucyate|\nyogārūḍhasya tasyaiva śamaḥ kāraṇamucyate||","e":"So is that well said:\n\"By works the votary doth rise to faith,\nAnd saintship is the ceasing from all works;"},
{"c":6,"v":4,"d":"यदा हि नेन्द्रियार्थेषु न कर्मस्वनुषज्जते।\nसर्वसङ्कल्पसंन्यासी योगारूढस्तदोच्यते॥","t":"yadā hi nendriyārtheṣu na karmasvanuṣajjate|\nsarvasaṅkalpasaṃnyāsī yogārūḍhastadocyate||","e":"Because the perfect Yogin acts--but acts\nUnmoved by passions and unbound by deeds,\nSetting result aside."},
{"c":6,"v":5,"d":"उद्धरेदात्मनाऽऽत्मानं नात्मानमवसादयेत्।\nआत्मैव ह्यात्मनो बन्धुरात्मैव रिपुरात्मनः॥","t":"uddharedātmanā''tmānaṃ nātmānamavasādayet|\nātmaiva hyātmano bandhurātmaiva ripurātmanaḥ||","e":"Let each man raise\nThe Self by Soul, not trample down his Self,\nSince Soul that is Self's friend may grow Self's foe."},
{"c":6,"v":6,"d":"बन्धुरात्माऽऽत्मनस्तस्य येनात्मैवात्मना जितः।\nअनात्मनस्तु शत्रुत्वे वर्तेतात्मैव शत्रुवत्॥","t":"bandhurātmā''tmanastasya yenātmaivātmanā jitaḥ|\nanātmanastu śatrutve vartetātmaiva śatruvat||","e":"Soul is Self's friend when Self doth rule o'er Self,\nBut Self turns enemy if Soul's own self\nHates Self as not itself."},
{"c":6,"v":7,"d":"जितात्मनः प्रशान्तस्य परमात्मा समाहितः।\nशीतोष्णसुखदुःखेषु तथा मानापमानयोः॥","t":"jitātmanaḥ praśāntasya paramātmā samāhitaḥ|\nśītoṣṇasukhaduḥkheṣu tathā mānāpamānayoḥ||","e":"The sovereign soul\nOf him who lives self-governed and at peace\nIs centred in itself, taking alike\nPleasure and pain; heat, cold; glory and shame."},
{"c":6,"v":8,"d":"ज्ञानविज्ञानतृप्तात्मा कूटस्थो विजितेन्द्रियः।\nयुक्त इत्युच्यते योगी समलोष्टाश्मकाञ्चनः॥","t":"jñānavijñānatṛptātmā kūṭastho vijitendriyaḥ|\nyukta ityucyate yogī samaloṣṭāśmakāñcanaḥ||","e":"He is the Yogi, he is Yukta, glad\nWith joy of light and truth; dwelling apart\nUpon a peak, with senses subjugate\nWhereto the clod, the rock, the glistering gold\nShow all as one."},
{"c":6,"v":9,"d":"सुहृन्मित्रार्युदासीनमध्यस्थद्वेष्यबन्धुषु।\nसाधुष्वपि च पापेषु समबुद्धिर्विशिष्यते॥","t":"suhṛnmitrāryudāsīnamadhyasthadveṣyabandhuṣu|\nsādhuṣvapi ca pāpeṣu samabuddhirviśiṣyate||","e":"By this sign is he known\nBeing of equal grace to comrades, friends,\nChance-comers, strangers, lovers, enemies,\nAliens and kinsmen; loving all alike,\nEvil or good."},
{"c":6,"v":10,"d":"योगी युञ्जीत सततमात्मानं रहसि स्थितः।\nएकाकी यतचित्तात्मा निराशीरपरिग्रहः॥","t":"yogī yuñjīta satatamātmānaṃ rahasi sthitaḥ|\nekākī yatacittātmā nirāśīraparigrahaḥ||","e":"Sequestered should he sit,\nSteadfastly meditating, solitary,\nHis thoughts controlled, his passions laid away,\nQuit of belongings."},
{"c":6,"v":11,"d":"शुचौ देशे प्रतिष्ठाप्य स्थिरमासनमात्मनः।\nनात्युच्छ्रितं नातिनीचं चैलाजिनकुशोत्तरम्॥","t":"śucau deśe pratiṣṭhāpya sthiramāsanamātmanaḥ|\nnātyucchritaṃ nātinīcaṃ cailājinakuśottaram||","e":"In a fair, still spot\nHaving his fixed abode,--not too much raised,\nNor yet too low,--let him abide, his goods\nA cloth, a deerskin, and the Kusa-grass."},
{"c":6,"v":12,"d":"तत्रैकाग्रं मनः कृत्वा यतचित्तेन्द्रियक्रियः।\nउपविश्यासने युञ्ज्याद्योगमात्मविशुद्धये॥","t":"tatraikāgraṃ manaḥ kṛtvā yatacittendriyakriyaḥ|\nupaviśyāsane yuñjyādyogamātmaviśuddhaye||","e":"There, setting hard his mind upon The One,\nRestraining heart and senses, silent, calm,\nLet him accomplish Yoga, and achieve\nPureness of soul,"},
{"c":6,"v":13,"d":"समं कायशिरोग्रीवं धारयन्नचलं स्थिरः।\nसंप्रेक्ष्य नासिकाग्रं स्वं दिशश्चानवलोकयन्॥","t":"samaṃ kāyaśirogrīvaṃ dhārayannacalaṃ sthiraḥ|\nsaṃprekṣya nāsikāgraṃ svaṃ diśaścānavalokayan||","e":"holding immovable\nBody and neck and head, his gaze absorbed\nUpon his nose-end, rapt from all around,"},
{"c":6,"v":14,"d":"प्रशान्तात्मा विगतभीर्ब्रह्मचारिव्रते स्थितः।\nमनः संयम्य मच्चित्तो युक्त आसीत मत्परः॥","t":"praśāntātmā vigatabhīrbrahmacārivrate sthitaḥ|\nmanaḥ saṃyamya maccitto yukta āsīta matparaḥ||","e":"Tranquil in spirit, free of fear, intent\nUpon his Brahmacharya vow, devout,\nMusing on Me, lost in the thought of Me."},
{"c":6,"v":15,"d":"युञ्जन्नेवं सदाऽऽत्मानं योगी नियतमानसः।\nशान्तिं निर्वाणपरमां मत्संस्थामधिगच्छति॥","t":"yuñjannevaṃ sadā''tmānaṃ yogī niyatamānasaḥ|\nśāntiṃ nirvāṇaparamāṃ matsaṃsthāmadhigacchati||","e":"That Yojin, so devoted, so controlled,\nComes to the peace beyond,--My peace, the peace\nOf high Nirvana!"},
{"c":6,"v":16,"d":"नात्यश्नतस्तु योगोऽस्ति न चैकान्तमनश्नतः।\nन चातिस्वप्नशीलस्य जाग्रतो नैव चार्जुन॥","t":"nātyaśnatastu yogo'sti na caikāntamanaśnataḥ|\nna cātisvapnaśīlasya jāgrato naiva cārjuna||","e":"But for earthly needs\nReligion is not his who too much fasts\nOr too much feasts, nor his who sleeps away\nAn idle mind; nor his who wears to waste\nHis strength in vigils."},
{"c":6,"v":17,"d":"युक्ताहारविहारस्य युक्तचेष्टस्य कर्मसु।\nयुक्तस्वप्नावबोधस्य योगो भवति दुःखहा॥","t":"yuktāhāravihārasya yuktaceṣṭasya karmasu|\nyuktasvapnāvabodhasya yogo bhavati duḥkhahā||","e":"Nay, Arjuna! call\nThat the true piety which most removes\nEarth-aches and ills, where one is moderate\nIn eating and in resting, and in sport;\nMeasured in wish and act; sleeping betimes,\nWaking betimes for duty."},
{"c":6,"v":18,"d":"यदा विनियतं चित्तमात्मन्येवावतिष्ठते।\nनिःस्पृहः सर्वकामेभ्यो युक्त इत्युच्यते तदा॥","t":"yadā viniyataṃ cittamātmanyevāvatiṣṭhate|\nniḥspṛhaḥ sarvakāmebhyo yukta ityucyate tadā||","e":"When the man,\nSo living, centres on his soul the thought\nStraitly restrained--untouched internally\nBy stress of sense--then is he Yukta."},
{"c":6,"v":19,"d":"यथा दीपो निवातस्थो नेङ्गते सोपमा स्मृता।\nयोगिनो यतचित्तस्य युञ्जतो योगमात्मनः॥","t":"yathā dīpo nivātastho neṅgate sopamā smṛtā|\nyogino yatacittasya yuñjato yogamātmanaḥ||","e":"See!\nSteadfast a lamp burns sheltered from the wind;\nSuch is the likeness of the Yogi's mind\nShut from sense-storms and burning bright to Heaven."},
{"c":6,"v":20,"d":"यत्रोपरमते चित्तं निरुद्धं योगसेवया।\nयत्र चैवात्मनाऽऽत्मानं पश्यन्नात्मनि तुष्यति॥","t":"yatroparamate cittaṃ niruddhaṃ yogasevayā|\nyatra caivātmanā''tmānaṃ paśyannātmani tuṣyati||","e":"When mind broods placid, soothed with holy wont;\nWhen Self contemplates self, and in itself\nHath comfort;"},
{"c":6,"v":21,"d":"सुखमात्यन्तिकं यत्तद्बुद्धिग्राह्यमतीन्द्रियम्।\nवेत्ति यत्र न चैवायं स्थितश्चलति तत्त्वतः॥","t":"sukhamātyantikaṃ yattadbuddhigrāhyamatīndriyam|\nvetti yatra na caivāyaṃ sthitaścalati tattvataḥ||","e":"when it knows the nameless joy\nBeyond all scope of sense, revealed to soul--\nOnly to soul! and, knowing, wavers not,\nTrue to the farther Truth;"},
{"c":6,"v":22,"d":"यं लब्ध्वा चापरं लाभं मन्यते नाधिकं ततः।\nयस्मिन्स्थितो न दुःखेन गुरुणापि विचाल्यते॥","t":"yaṃ labdhvā cāparaṃ lābhaṃ manyate nādhikaṃ tataḥ|\nyasminsthito na duḥkhena guruṇāpi vicālyate||","e":"when, holding this,\nIt deems no other treasure comparable,\nBut, harboured there, cannot be stirred or shook\nBy any gravest grief,"},
{"c":6,"v":23,"d":"तं विद्याद् दुःखसंयोगवियोगं योगसंज्ञितम्।\nस निश्चयेन योक्तव्यो योगोऽनिर्विण्णचेतसा॥","t":"taṃ vidyād duḥkhasaṃyogaviyogaṃ yogasaṃjñitam|\nsa niścayena yoktavyo yogo'nirviṇṇacetasā||","e":"call that state \"peace,\"\nThat happy severance Yoga; call that man\nThe perfect Yogin!\nSteadfastly the will\nMust toil thereto, till efforts end in ease,\nAnd thought has passed from thinking."},
{"c":6,"v":24,"d":"सङ्कल्पप्रभवान्कामांस्त्यक्त्वा सर्वानशेषतः।\nमनसैवेन्द्रियग्रामं विनियम्य समन्ततः॥","t":"saṅkalpaprabhavānkāmāṃstyaktvā sarvānaśeṣataḥ|\nmanasaivendriyagrāmaṃ viniyamya samantataḥ||","e":"Shaking off\nAll longings bred by dreams of fame and gain,\nShutting the doorways of the senses close\nWith watchful ward;"},
{"c":6,"v":25,"d":"शनैः शनैरुपरमेद् बुद्ध्या धृतिगृहीतया।\nआत्मसंस्थं मनः कृत्वा न किञ्चिदपि चिन्तयेत्॥","t":"śanaiḥ śanairuparamed buddhyā dhṛtigṛhītayā|\nātmasaṃsthaṃ manaḥ kṛtvā na kiñcidapi cintayet||","e":"so, step by step, it comes\nTo gift of peace assured and heart assuaged,\nWhen the mind dwells self-wrapped, and the soul broods\nCumberless."},
{"c":6,"v":26,"d":"यतो यतो निश्चरति मनश्चञ्चलमस्थिरम्।\nततस्ततो नियम्यैतदात्मन्येव वशं नयेत्॥","t":"yato yato niścarati manaścañcalamasthiram|\ntatastato niyamyaitadātmanyeva vaśaṃ nayet||","e":"But, as often as the heart\nBreaks--wild and wavering--from control, so oft\nLet him re-curb it, let him rein it back\nTo the soul's governance;"},
{"c":6,"v":27,"d":"प्रशान्तमनसं ह्येनं योगिनं सुखमुत्तमम्।\nउपैति शान्तरजसं ब्रह्मभूतमकल्मषम्॥","t":"praśāntamanasaṃ hyenaṃ yoginaṃ sukhamuttamam|\nupaiti śāntarajasaṃ brahmabhūtamakalmaṣam||","e":"for perfect bliss\nGrows only in the bosom tranquillised,\nThe spirit passionless, purged from offence,\nVowed to the Infinite."},
{"c":6,"v":28,"d":"युञ्जन्नेवं सदाऽऽत्मानं योगी विगतकल्मषः।\nसुखेन ब्रह्मसंस्पर्शमत्यन्तं सुखमश्नुते॥","t":"yuñjannevaṃ sadā''tmānaṃ yogī vigatakalmaṣaḥ|\nsukhena brahmasaṃsparśamatyantaṃ sukhamaśnute||","e":"He who thus vows\nHis soul to the Supreme Soul, quitting sin,\nPasses unhindered to the endless bliss\nOf unity with Brahma."},
{"c":6,"v":29,"d":"सर्वभूतस्थमात्मानं सर्वभूतानि चात्मनि।\nईक्षते योगयुक्तात्मा सर्वत्र समदर्शनः॥","t":"sarvabhūtasthamātmānaṃ sarvabhūtāni cātmani|\nīkṣate yogayuktātmā sarvatra samadarśanaḥ||","e":"He so vowed,\nSo blended, sees the Life-Soul resident\nIn all things living, and all living things\nIn that Life-Soul contained."},
{"c":6,"v":30,"d":"यो मां पश्यति सर्वत्र सर्वं च मयि पश्यति।\nतस्याहं न प्रणश्यामि स च मे न प्रणश्यति॥","t":"yo māṃ paśyati sarvatra sarvaṃ ca mayi paśyati|\ntasyāhaṃ na praṇaśyāmi sa ca me na praṇaśyati||","e":"And whoso thus\nDiscerneth Me in all, and all in Me,\nI never let him go; nor looseneth he\nHold upon Me;"},
{"c":6,"v":31,"d":"सर्वभूतस्थितं यो मां भजत्येकत्वमास्थितः।\nसर्वथा वर्तमानोऽपि स योगी मयि वर्तते॥","t":"sarvabhūtasthitaṃ yo māṃ bhajatyekatvamāsthitaḥ|\nsarvathā vartamāno'pi sa yogī mayi vartate||","e":"but, dwell he where he may,\nWhate'er his life, in Me he dwells and lives,\nBecause he knows and worships Me, Who dwell\nIn all which lives, and cleaves to Me in all."},
{"c":6,"v":32,"d":"आत्मौपम्येन सर्वत्र समं पश्यति योऽर्जुन।\nसुखं वा यदि वा दुःखं सः योगी परमो मतः॥","t":"ātmaupamyena sarvatra samaṃ paśyati yo'rjuna|\nsukhaṃ vā yadi vā duḥkhaṃ saḥ yogī paramo mataḥ||","e":"Arjuna! if a man sees everywhere--\nTaught by his own similitude--one Life,\nOne Essence in the Evil and the Good,\nHold him a Yogi, yea! well-perfected!"},
{"c":6,"v":33,"d":"अर्जुन उवाच\nयोऽयं योगस्त्वया प्रोक्तः साम्येन मधुसूदन।\nएतस्याहं न पश्यामि चञ्चलत्वात् स्थितिं स्थिराम्॥","t":"arjuna uvāca\nyo'yaṃ yogastvayā proktaḥ sāmyena madhusūdana|\netasyāhaṃ na paśyāmi cañcalatvāt sthitiṃ sthirām||","e":"Arjuna.\nSlayer of Madhu! yet again, this Yog,\nThis Peace, derived from equanimity,\nMade known by thee--I see no fixity\nTherein, no rest,"},
{"c":6,"v":34,"d":"चञ्चलं हि मनः कृष्ण प्रमाथि बलवद्दृढम्।\nतस्याहं निग्रहं मन्ये वायोरिव सुदुष्करम्॥","t":"cañcalaṃ hi manaḥ kṛṣṇa pramāthi balavaddṛḍham|\ntasyāhaṃ nigrahaṃ manye vāyoriva suduṣkaram||","e":"because the heart of men\nIs unfixed, Krishna! rash, tumultuous,\nWilful and strong. It were all one, I think,\nTo hold the wayward wind, as tame man's heart."},
{"c":6,"v":35,"d":"श्री भगवानुवाच\nअसंशयं महाबाहो मनो दुर्निग्रहं चलं।\nअभ्यासेन तु कौन्तेय वैराग्येण च गृह्यते॥","t":"śrī bhagavānuvāca\nasaṃśayaṃ mahābāho mano durnigrahaṃ calaṃ|\nabhyāsena tu kaunteya vairāgyeṇa ca gṛhyate||","e":"Krishna.\nHero long-armed! beyond denial, hard\nMan's heart is to restrain, and wavering;\nYet may it grow restrained by habit, Prince!\nBy wont of self-command."},
{"c":6,"v":36,"d":"असंयतात्मना योगो दुष्प्राप इति मे मतिः।\nवश्यात्मना तु यतता शक्योऽवाप्तुमुपायतः॥","t":"asaṃyatātmanā yogo duṣprāpa iti me matiḥ|\nvaśyātmanā tu yatatā śakyo'vāptumupāyataḥ||","e":"This Yog, I say,\nCometh not lightly to th' ungoverned ones;\nBut he who will be master of himself\nShall win it, if he stoutly strive thereto."},
{"c":6,"v":37,"d":"अर्जुन उवाच\nअयतिः श्रद्धयोपेतो योगाच्चलितमानसः।\nअप्राप्य योगसंसिद्धिं कां गतिं कृष्ण गच्छति॥","t":"arjuna uvāca\nayatiḥ śraddhayopeto yogāccalitamānasaḥ|\naprāpya yogasaṃsiddhiṃ kāṃ gatiṃ kṛṣṇa gacchati||","e":"Arjuna.\nAnd what road goeth he who, having faith,\nFails, Krishna! in the striving; falling back\nFrom holiness, missing the perfect rule?"},
{"c":6,"v":38,"d":"कच्चिन्नोभयविभ्रष्टश्छिन्नाभ्रमिव नश्यति।\nअप्रतिष्ठो महाबाहो विमूढो ब्रह्मणः पथि॥","t":"kaccinnobhayavibhraṣṭaśchinnābhramiva naśyati|\napratiṣṭho mahābāho vimūḍho brahmaṇaḥ pathi||","e":"Is he not lost, straying from Brahma's light,\nLike the vain cloud, which floats 'twixt earth and heaven\nWhen lightning splits it, and it vanisheth?"},
{"c":6,"v":39,"d":"एतन्मे संशयं कृष्ण छेत्तुमर्हस्यशेषतः।\nत्वदन्यः संशयस्यास्य छेत्ता न ह्युपपद्यते॥","t":"etanme saṃśayaṃ kṛṣṇa chettumarhasyaśeṣataḥ|\ntvadanyaḥ saṃśayasyāsya chettā na hyupapadyate||","e":"Fain would I hear thee answer me herein,\nSince, Krishna! none save thou can clear the doubt."},
{"c":6,"v":40,"d":"श्री भगवानुवाच\nपार्थ नैवेह नामुत्र विनाशस्तस्य विद्यते।\nनहि कल्याणकृत्कश्िचद्दुर्गतिं तात गच्छति॥","t":"śrī bhagavānuvāca\npārtha naiveha nāmutra vināśastasya vidyate|\nnahi kalyāṇakṛtkaścaddurgatiṃ tāta gacchati||","e":"Krishna.\nHe is not lost, thou Son of Pritha! No!\nNor earth, nor heaven is forfeit, even for him,\nBecause no heart that holds one right desire\nTreadeth the road of loss!"},
{"c":6,"v":41,"d":"प्राप्य पुण्यकृतां लोकानुषित्वा शाश्वतीः समाः।\nशुचीनां श्रीमतां गेहे योगभ्रष्टोऽभिजायते॥","t":"prāpya puṇyakṛtāṃ lokānuṣitvā śāśvatīḥ samāḥ|\nśucīnāṃ śrīmatāṃ gehe yogabhraṣṭo'bhijāyate||","e":"He who should fail,\nDesiring righteousness, cometh at death\nUnto the Region of the Just; dwells there\nMeasureless years, and being born anew,\nBeginneth life again in some fair home\nAmid the mild and happy."},
{"c":6,"v":42,"d":"अथवा योगिनामेव कुले भवति धीमताम्।\nएतद्धि दुर्लभतरं लोके जन्म यदीदृशम्॥","t":"athavā yogināmeva kule bhavati dhīmatām|\netaddhi durlabhataraṃ loke janma yadīdṛśam||","e":"It may chance\nHe doth descend into a Yogin house\nOn Virtue's breast; but that is rare! Such birth\nIs hard to be obtained on this earth, Chief!"},
{"c":6,"v":43,"d":"तत्र तं बुद्धिसंयोगं लभते पौर्वदेहिकम्।\nयतते च ततो भूयः संसिद्धौ कुरुनन्दन॥","t":"tatra taṃ buddhisaṃyogaṃ labhate paurvadehikam|\nyatate ca tato bhūyaḥ saṃsiddhau kurunandana||","e":"So hath he back again what heights of heart\nHe did achieve, and so he strives anew\nTo perfectness, with better hope, dear Prince!"},
{"c":6,"v":44,"d":"पूर्वाभ्यासेन तेनैव ह्रियते ह्यवशोऽपि सः।\nजिज्ञासुरपि योगस्य शब्दब्रह्मातिवर्तते॥","t":"pūrvābhyāsena tenaiva hriyate hyavaśo'pi saḥ|\njijñāsurapi yogasya śabdabrahmātivartate||","e":"For by the old desire he is drawn on\nUnwittingly; and only to desire\nThe purity of Yog is to pass\nBeyond the Sabdabrahm, the spoken Ved."},
{"c":6,"v":45,"d":"प्रयत्नाद्यतमानस्तु योगी संशुद्धकिल्बिषः।\nअनेकजन्मसंसिद्धस्ततो याति परां गतिम्॥","t":"prayatnādyatamānastu yogī saṃśuddhakilbiṣaḥ|\nanekajanmasaṃsiddhastato yāti parāṃ gatim||","e":"But, being Yogi, striving strong and long,\nPurged from transgressions, perfected by births\nFollowing on births, he plants his feet at last\nUpon the farther path."},
{"c":6,"v":46,"d":"तपस्विभ्योऽधिको योगी ज्ञानिभ्योऽपि मतोऽधिकः।\nकर्मिभ्यश्चाधिको योगी तस्माद्योगी भवार्जुन॥","t":"tapasvibhyo'dhiko yogī jñānibhyo'pi mato'dhikaḥ|\nkarmibhyaścādhiko yogī tasmādyogī bhavārjuna||","e":"Such as one ranks\nAbove ascetics, higher than the wise,\nBeyond achievers of vast deeds! Be thou\nYogi Arjuna!"},
{"c":6,"v":47,"d":"योगिनामपि सर्वेषां मद्गतेनान्तरात्मना।\nश्रद्धावान्भजते यो मां स मे युक्ततमो मतः॥","t":"yogināmapi sarveṣāṃ madgatenāntarātmanā|\nśraddhāvānbhajate yo māṃ sa me yuktatamo mataḥ||","e":"And of such believe,\nTruest and best is he who worships Me\nWith inmost soul, stayed on My Mystery!"},
{"c":7,"v":1,"d":"श्री भगवानुवाच\nमय्यासक्तमनाः पार्थ योगं युञ्जन्मदाश्रयः।\nअसंशयं समग्रं मां यथा ज्ञास्यसि तच्छृणु॥","t":"śrī bhagavānuvāca\nmayyāsaktamanāḥ pārtha yogaṃ yuñjanmadāśrayaḥ|\nasaṃśayaṃ samagraṃ māṃ yathā jñāsyasi tacchṛṇu||","e":"Krishna.\nLearn now, dear Prince! how, if thy soul be set\nEver on Me--still exercising Yog,\nStill making Me thy Refuge--thou shalt come\nMost surely unto perfect hold of Me."},
{"c":7,"v":2,"d":"ज्ञानं तेऽहं सविज्ञानमिदं वक्ष्याम्यशेषतः।\nयज्ज्ञात्वा नेह भूयोऽन्यज्ज्ञातव्यमवशिष्यते॥","t":"jñānaṃ te'haṃ savijñānamidaṃ vakṣyāmyaśeṣataḥ|\nyajjñātvā neha bhūyo'nyajjñātavyamavaśiṣyate||","e":"I will declare to thee that utmost lore,\nWhole and particular, which, when thou knowest,\nLeaveth no more to know here in this world."},
{"c":7,"v":3,"d":"मनुष्याणां सहस्रेषु कश्िचद्यतति सिद्धये।\nयततामपि सिद्धानां कश्िचन्मां वेत्ति तत्त्वतः॥","t":"manuṣyāṇāṃ sahasreṣu kaścadyatati siddhaye|\nyatatāmapi siddhānāṃ kaścanmāṃ vetti tattvataḥ||","e":"Of many thousand mortals, one, perchance,\nStriveth for Truth; and of those few that strive--\nNay, and rise high--one only--here and there--\nKnoweth Me, as I am, the very Truth."},
{"c":7,"v":4,"d":"भूमिरापोऽनलो वायुः खं मनो बुद्धिरेव च।\nअहङ्कार इतीयं मे भिन्ना प्रकृतिरष्टधा॥","t":"bhūmirāpo'nalo vāyuḥ khaṃ mano buddhireva ca|\nahaṅkāra itīyaṃ me bhinnā prakṛtiraṣṭadhā||","e":"Earth, water, flame, air, ether, life, and mind,\nAnd individuality--those eight\nMake up the showing of Me, Manifest."},
{"c":7,"v":5,"d":"अपरेयमितस्त्वन्यां प्रकृतिं विद्धि मे पराम्।\nजीवभूतां महाबाहो ययेदं धार्यते जगत्॥","t":"apareyamitastvanyāṃ prakṛtiṃ viddhi me parām|\njīvabhūtāṃ mahābāho yayedaṃ dhāryate jagat||","e":"These be my lower Nature; learn the higher,\nWhereby, thou Valiant One! this Universe\nIs, by its principle of life, produced;"},
{"c":7,"v":6,"d":"एतद्योनीनि भूतानि सर्वाणीत्युपधारय।\nअहं कृत्स्नस्य जगतः प्रभवः प्रलयस्तथा॥","t":"etadyonīni bhūtāni sarvāṇītyupadhāraya|\nahaṃ kṛtsnasya jagataḥ prabhavaḥ pralayastathā||","e":"Whereby the worlds of visible things are born\nAs from a Yoni. Know! I am that womb:\nI make and I unmake this Universe:"},
{"c":7,"v":7,"d":"मत्तः परतरं नान्यत्किञ्चिदस्ति धनञ्जय।\nमयि सर्वमिदं प्रोतं सूत्रे मणिगणा इव॥","t":"mattaḥ parataraṃ nānyatkiñcidasti dhanañjaya|\nmayi sarvamidaṃ protaṃ sūtre maṇigaṇā iva||","e":"Than me there is no other Master, Prince!\nNo other Maker! All these hang on me\nAs hangs a row of pearls upon its string."},
{"c":7,"v":8,"d":"रसोऽहमप्सु कौन्तेय प्रभास्मि शशिसूर्ययोः।\nप्रणवः सर्ववेदेषु शब्दः खे पौरुषं नृषु॥","t":"raso'hamapsu kaunteya prabhāsmi śaśisūryayoḥ|\npraṇavaḥ sarvavedeṣu śabdaḥ khe pauruṣaṃ nṛṣu||","e":"I am the fresh taste of the water; I\nThe silver of the moon, the gold o' the sun,\nThe word of worship in the Veds, the thrill\nThat passeth in the ether, and the strength\nOf man's shed seed."},
{"c":7,"v":9,"d":"पुण्यो गन्धः पृथिव्यां च तेजश्चास्मि विभावसौ।\nजीवनं सर्वभूतेषु तपश्चास्मि तपस्विषु॥","t":"puṇyo gandhaḥ pṛthivyāṃ ca tejaścāsmi vibhāvasau|\njīvanaṃ sarvabhūteṣu tapaścāsmi tapasviṣu||","e":"I am the good sweet smell\nOf the moistened earth, I am the fire's red light,\nThe vital air moving in all which moves,\nThe holiness of hallowed souls,"},
{"c":7,"v":10,"d":"बीजं मां सर्वभूतानां विद्धि पार्थ सनातनम्।\nबुद्धिर्बुद्धिमतामस्मि तेजस्तेजस्विनामहम्॥","t":"bījaṃ māṃ sarvabhūtānāṃ viddhi pārtha sanātanam|\nbuddhirbuddhimatāmasmi tejastejasvināmaham||","e":"the root\nUndying, whence hath sprung whatever is;\nThe wisdom of the wise, the intellect\nOf the informed, the greatness of the great.\nThe splendour of the splendid."},
{"c":7,"v":11,"d":"बलं बलवतां चाहं कामरागविवर्जितम्।\nधर्माविरुद्धो भूतेषु कामोऽस्मि भरतर्षभ॥","t":"balaṃ balavatāṃ cāhaṃ kāmarāgavivarjitam|\ndharmāviruddho bhūteṣu kāmo'smi bharatarṣabha||","e":"Kunti's Son!\nThese am I, free from passion and desire;\nYet am I right desire in all who yearn,\nChief of the Bharatas!"},
{"c":7,"v":12,"d":"ये चैव सात्त्विका भावा राजसास्तामसाश्च ये।\nमत्त एवेति तान्विद्धि नत्वहं तेषु ते मयि॥","t":"ye caiva sāttvikā bhāvā rājasāstāmasāśca ye|\nmatta eveti tānviddhi natvahaṃ teṣu te mayi||","e":"for all those moods,\nSoothfast, or passionate, or ignorant,\nWhich Nature frames, deduce from me; but all\nAre merged in me--not I in them!"},
{"c":7,"v":13,"d":"त्रिभिर्गुणमयैर्भावैरेभिः सर्वमिदं जगत्।\nमोहितं नाभिजानाति मामेभ्यः परमव्ययम्॥","t":"tribhirguṇamayairbhāvairebhiḥ sarvamidaṃ jagat|\nmohitaṃ nābhijānāti māmebhyaḥ paramavyayam||","e":"The world--\nDeceived by those three qualities of being--\nWotteth not Me Who am outside them all,\nAbove them all, Eternal!"},
{"c":7,"v":14,"d":"दैवी ह्येषा गुणमयी मम माया दुरत्यया।\nमामेव ये प्रपद्यन्ते मायामेतां तरन्ति ते॥","t":"daivī hyeṣā guṇamayī mama māyā duratyayā|\nmāmeva ye prapadyante māyāmetāṃ taranti te||","e":"Hard it is\nTo pierce that veil divine of various shows\nWhich hideth Me; yet they who worship Me\nPierce it and pass beyond."},
{"c":7,"v":15,"d":"न मां दुष्कृतिनो मूढाः प्रपद्यन्ते नराधमाः।\nमाययापहृतज्ञाना आसुरं भावमाश्रिताः॥","t":"na māṃ duṣkṛtino mūḍhāḥ prapadyante narādhamāḥ|\nmāyayāpahṛtajñānā āsuraṃ bhāvamāśritāḥ||","e":"I am not known\nTo evil-doers, nor to foolish ones,\nNor to the base and churlish; nor to those\nWhose mind is cheated by the show of things,\nNor those that take the way of Asuras."},
{"c":7,"v":16,"d":"चतुर्विधा भजन्ते मां जनाः सुकृतिनोऽर्जुन।\nआर्तो जिज्ञासुरर्थार्थी ज्ञानी च भरतर्षभ॥","t":"caturvidhā bhajante māṃ janāḥ sukṛtino'rjuna|\nārto jijñāsurarthārthī jñānī ca bharatarṣabha||","e":"Four sorts of mortals know me: he who weeps,\nArjuna! and the man who yearns to know;\nAnd he who toils to help; and he who sits\nCertain of me, enlightened."},
{"c":7,"v":17,"d":"तेषां ज्ञानी नित्ययुक्त एकभक्ितर्विशिष्यते।\nप्रियो हि ज्ञानिनोऽत्यर्थमहं स च मम प्रियः॥","t":"teṣāṃ jñānī nityayukta ekabhaktarviśiṣyate|\npriyo hi jñānino'tyarthamahaṃ sa ca mama priyaḥ||","e":"Of these four,\nO Prince of India! highest, nearest, best\nThat last is, the devout soul, wise, intent\nUpon \"The One.\" Dear, above all, am I\nTo him; and he is dearest unto me!"},
{"c":7,"v":18,"d":"उदाराः सर्व एवैते ज्ञानी त्वात्मैव मे मतम्।\nआस्थितः स हि युक्तात्मा मामेवानुत्तमां गतिम्॥","t":"udārāḥ sarva evaite jñānī tvātmaiva me matam|\nāsthitaḥ sa hi yuktātmā māmevānuttamāṃ gatim||","e":"All four are good, and seek me; but mine own,\nThe true of heart, the faithful--stayed on me,\nTaking me as their utmost blessedness,\nThey are not \"mine,\"but I--even I myself!"},
{"c":7,"v":19,"d":"बहूनां जन्मनामन्ते ज्ञानवान्मां प्रपद्यते।\nवासुदेवः सर्वमिति स महात्मा सुदुर्लभः॥","t":"bahūnāṃ janmanāmante jñānavānmāṃ prapadyate|\nvāsudevaḥ sarvamiti sa mahātmā sudurlabhaḥ||","e":"At end of many births to Me they come!\nYet hard the wise Mahatma is to find,\nThat man who sayeth, \"All is Vasudev!\""},
{"c":7,"v":20,"d":"कामैस्तैस्तैर्हृतज्ञानाः प्रपद्यन्तेऽन्यदेवताः।\nतं तं नियममास्थाय प्रकृत्या नियताः स्वया॥","t":"kāmaistaistairhṛtajñānāḥ prapadyante'nyadevatāḥ|\ntaṃ taṃ niyamamāsthāya prakṛtyā niyatāḥ svayā||","e":"There be those, too, whose knowledge, turned aside\nBy this desire or that, gives them to serve\nSome lower gods, with various rites, constrained\nBy that which mouldeth them."},
{"c":7,"v":21,"d":"यो यो यां यां तनुं भक्तः श्रद्धयार्चितुमिच्छति।\nतस्य तस्याचलां श्रद्धां तामेव विदधाम्यहम्॥","t":"yo yo yāṃ yāṃ tanuṃ bhaktaḥ śraddhayārcitumicchati|\ntasya tasyācalāṃ śraddhāṃ tāmeva vidadhāmyaham||","e":"Unto all such--\nWorship what shrine they will, what shapes, in faith--\n'Tis I who give them faith! I am content!"},
{"c":7,"v":22,"d":"स तया श्रद्धया युक्तस्तस्याराधनमीहते।\nलभते च ततः कामान्मयैव विहितान् हि तान्॥","t":"sa tayā śraddhayā yuktastasyārādhanamīhate|\nlabhate ca tataḥ kāmānmayaiva vihitān hi tān||","e":"The heart thus asking favour from its God,\nDarkened but ardent, hath the end it craves,\nThe lesser blessing--but 'tis I who give!"},
{"c":7,"v":23,"d":"अन्तवत्तु फलं तेषां तद्भवत्यल्पमेधसाम्।\nदेवान्देवयजो यान्ति मद्भक्ता यान्ति मामपि॥","t":"antavattu phalaṃ teṣāṃ tadbhavatyalpamedhasām|\ndevāndevayajo yānti madbhaktā yānti māmapi||","e":"Yet soon is withered what small fruit they reap:\nThose men of little minds, who worship so,\nGo where they worship, passing with their gods.\nBut Mine come unto me!"},
{"c":7,"v":24,"d":"अव्यक्तं व्यक्ितमापन्नं मन्यन्ते मामबुद्धयः।\nपरं भावमजानन्तो ममाव्ययमनुत्तमम्॥","t":"avyaktaṃ vyaktamāpannaṃ manyante māmabuddhayaḥ|\nparaṃ bhāvamajānanto mamāvyayamanuttamam||","e":"Blind are the eyes\nWhich deem th' Unmanifested manifest,\nNot comprehending Me in my true Self!"},
{"c":7,"v":25,"d":"नाहं प्रकाशः सर्वस्य योगमायासमावृतः।\nमूढोऽयं नाभिजानाति लोको मामजमव्ययम्॥","t":"nāhaṃ prakāśaḥ sarvasya yogamāyāsamāvṛtaḥ|\nmūḍho'yaṃ nābhijānāti loko māmajamavyayam||","e":"Imperishable, viewless, undeclared,\nHidden behind my magic veil of shows,\nI am not seen by all; I am not known--\nUnborn and changeless--to the idle world."},
{"c":7,"v":26,"d":"वेदाहं समतीतानि वर्तमानानि चार्जुन।\nभविष्याणि च भूतानि मां तु वेद न कश्चन॥","t":"vedāhaṃ samatītāni vartamānāni cārjuna|\nbhaviṣyāṇi ca bhūtāni māṃ tu veda na kaścana||","e":"But I, Arjuna! know all things which were,\nAnd all which are, and all which are to be,\nAlbeit not one among them knoweth Me!"},
{"c":7,"v":27,"d":"इच्छाद्वेषसमुत्थेन द्वन्द्वमोहेन भारत।\nसर्वभूतानि संमोहं सर्गे यान्ति परन्तप॥","t":"icchādveṣasamutthena dvandvamohena bhārata|\nsarvabhūtāni saṃmohaṃ sarge yānti parantapa||","e":"By passion for the \"pairs of opposites,\"\nBy those twain snares of Like and Dislike, Prince!\nAll creatures live bewildered,"},
{"c":7,"v":28,"d":"येषां त्वन्तगतं पापं जनानां पुण्यकर्मणाम्।\nते द्वन्द्वमोहनिर्मुक्ता भजन्ते मां दृढव्रताः॥","t":"yeṣāṃ tvantagataṃ pāpaṃ janānāṃ puṇyakarmaṇām|\nte dvandvamohanirmuktā bhajante māṃ dṛḍhavratāḥ||","e":"save some few\nWho, quit of sins, holy in act, informed,\nFreed from the \"opposites,\"and fixed in faith,\nCleave unto Me."},
{"c":7,"v":29,"d":"जरामरणमोक्षाय मामाश्रित्य यतन्ति ये।\nते ब्रह्म तद्विदुः कृत्स्नमध्यात्मं कर्म चाखिलम्॥","t":"jarāmaraṇamokṣāya māmāśritya yatanti ye|\nte brahma tadviduḥ kṛtsnamadhyātmaṃ karma cākhilam||","e":"Who cleave, who seek in Me\nRefuge from birth and death, those have the Truth!\nThose know Me BRAHMA; know Me Soul of Souls,\nThe ADHYATMAN; know KARMA, my work;"},
{"c":7,"v":30,"d":"साधिभूताधिदैवं मां साधियज्ञं च ये विदुः।\nप्रयाणकालेऽपि च मां ते विदुर्युक्तचेतसः॥","t":"sādhibhūtādhidaivaṃ māṃ sādhiyajñaṃ ca ye viduḥ|\nprayāṇakāle'pi ca māṃ te viduryuktacetasaḥ||","e":"Know I am ADHIBHUTA, Lord of Life,\nAnd ADHIDAIVA, Lord of all the Gods,\nAnd ADHIYAJNA, Lord of Sacrifice;\nWorship Me well, with hearts of love and faith,\nAnd find and hold me in the hour of death."},
{"c":8,"v":1,"d":"अर्जुन उवाच\nकिं तद्ब्रह्म किमध्यात्मं किं कर्म पुरुषोत्तम।\nअधिभूतं च किं प्रोक्तमधिदैवं किमुच्यते॥","t":"arjuna uvāca\nkiṃ tadbrahma kimadhyātmaṃ kiṃ karma puruṣottama|\nadhibhūtaṃ ca kiṃ proktamadhidaivaṃ kimucyate||","e":"Arjuna.\nWho is that BRAHMA? What that Soul of Souls,\nThe ADHYATMAN? What, Thou Best of All!\nThy work, the KARMA? Tell me what it is\nThou namest ADHIBHUTA? What again\nMeans ADHIDAIVA?"},
{"c":8,"v":2,"d":"अधियज्ञः कथं कोऽत्र देहेऽस्मिन्मधुसूदन।\nप्रयाणकाले च कथं ज्ञेयोऽसि नियतात्मभिः॥","t":"adhiyajñaḥ kathaṃ ko'tra dehe'sminmadhusūdana|\nprayāṇakāle ca kathaṃ jñeyo'si niyatātmabhiḥ||","e":"Yea, and how it comes\nThou canst be ADHIYAJNA in thy flesh?\nSlayer of Madhu! Further, make me know\nHow good men find thee in the hour of death?"},
{"c":8,"v":3,"d":"श्री भगवानुवाच\nअक्षरं ब्रह्म परमं स्वभावोऽध्यात्ममुच्यते।\nभूतभावोद्भवकरो विसर्गः कर्मसंज्ञितः॥","t":"śrī bhagavānuvāca\nakṣaraṃ brahma paramaṃ svabhāvo'dhyātmamucyate|\nbhūtabhāvodbhavakaro visargaḥ karmasaṃjñitaḥ||","e":"Krishna.\nI BRAHMA am! the One Eternal GOD,\nAnd ADHYATMAN is My Being's name,\nThe Soul of Souls! What goeth forth from Me,\nCausing all life to live, is KARMA called:"},
{"c":8,"v":4,"d":"अधिभूतं क्षरो भावः पुरुषश्चाधिदैवतम्।\nअधियज्ञोऽहमेवात्र देहे देहभृतां वर॥","t":"adhibhūtaṃ kṣaro bhāvaḥ puruṣaścādhidaivatam|\nadhiyajño'hamevātra dehe dehabhṛtāṃ vara||","e":"And, Manifested in divided forms,\nI am the ADHIBHUTA, Lord of Lives;\nAnd ADHIDAIVA, Lord of all the Gods,\nBecause I am PURUSHA, who begets.\nAnd ADHIYAJNA, Lord of Sacrifice,\nI--speaking with thee in this body here--\nAm, thou embodied one! (for all the shrines\nFlame unto Me!)"},
{"c":8,"v":5,"d":"अन्तकाले च मामेव स्मरन्मुक्त्वा कलेवरम्।\nयः प्रयाति स मद्भावं याति नास्त्यत्र संशयः॥","t":"antakāle ca māmeva smaranmuktvā kalevaram|\nyaḥ prayāti sa madbhāvaṃ yāti nāstyatra saṃśayaḥ||","e":"And, at the hour of death,\nHe that hath meditated Me alone,\nIn putting off his flesh, comes forth to Me,\nEnters into My Being--doubt thou not!"},
{"c":8,"v":6,"d":"यं यं वापि स्मरन्भावं त्यजत्यन्ते कलेवरम्।\nतं तमेवैति कौन्तेय सदा तद्भावभावितः॥","t":"yaṃ yaṃ vāpi smaranbhāvaṃ tyajatyante kalevaram|\ntaṃ tamevaiti kaunteya sadā tadbhāvabhāvitaḥ||","e":"But, if he meditated otherwise\nAt hour of death, in putting off the flesh,\nHe goes to what he looked for, Kunti's Son!\nBecause the Soul is fashioned to its like."},
{"c":8,"v":7,"d":"तस्मात्सर्वेषु कालेषु मामनुस्मर युध्य च।\nमय्यर्पितमनोबुद्धिर्मामेवैष्यस्यसंशयम्॥","t":"tasmātsarveṣu kāleṣu māmanusmara yudhya ca|\nmayyarpitamanobuddhirmāmevaiṣyasyasaṃśayam||","e":"Have Me, then, in thy heart always! and fight!\nThou too, when heart and mind are fixed on Me,\nShalt surely come to Me!"},
{"c":8,"v":8,"d":"अभ्यासयोगयुक्तेन चेतसा नान्यगामिना।\nपरमं पुरुषं दिव्यं याति पार्थानुचिन्तयन्॥","t":"abhyāsayogayuktena cetasā nānyagāminā|\nparamaṃ puruṣaṃ divyaṃ yāti pārthānucintayan||","e":"All come who cleave\nWith never-wavering will of firmest faith,\nOwning none other Gods: all come to Me,\nThe Uttermost, Purusha, Holiest!"},
{"c":8,"v":9,"d":"कविं पुराणमनुशासितार\nमणोरणीयांसमनुस्मरेद्यः।\nसर्वस्य धातारमचिन्त्यरूप\nमादित्यवर्णं तमसः परस्तात्॥","t":"kaviṃ purāṇamanuśāsitāra\nmaṇoraṇīyāṃsamanusmaredyaḥ|\nsarvasya dhātāramacintyarūpa\nmādityavarṇaṃ tamasaḥ parastāt||","e":"Whoso hath known Me, Lord of sage and singer,\nAncient of days; of all the Three Worlds Stay,\nBoundless,--but unto every atom Bringer\nOf that which quickens it: whoso, I say,\nHath known My form, which passeth mortal knowing;\nSeen my effulgence--which no eye hath seen--\nThan the sun's burning gold more brightly glowing,\nDispersing darkness,--unto him hath been"},
{"c":8,"v":10,"d":"प्रयाणकाले मनसाऽचलेन\nभक्त्या युक्तो योगबलेन चैव।\nभ्रुवोर्मध्ये प्राणमावेश्य सम्यक्\nस तं परं पुरुषमुपैति दिव्यम्॥","t":"prayāṇakāle manasā'calena\nbhaktyā yukto yogabalena caiva|\nbhruvormadhye prāṇamāveśya samyak\nsa taṃ paraṃ puruṣamupaiti divyam||","e":"Right life! And, in the hour when life is ending,\nWith mind set fast and trustful piety,\nDrawing still breath beneath calm brows unbending,\nIn happy peace that faithful one doth die,--\nIn glad peace passeth to Purusha's heaven."},
{"c":8,"v":11,"d":"यदक्षरं वेदविदो वदन्ति\nविशन्ति यद्यतयो वीतरागाः।\nयदिच्छन्तो ब्रह्मचर्यं चरन्ति\nतत्ते पदं संग्रहेण प्रवक्ष्ये॥","t":"yadakṣaraṃ vedavido vadanti\nviśanti yadyatayo vītarāgāḥ|\nyadicchanto brahmacaryaṃ caranti\ntatte padaṃ saṃgraheṇa pravakṣye||","e":"The place which they who read the Vedas name\nAKSHARAM, \"Ultimate;\" whereto have striven\nSaints and ascetics--their road is the same."},
{"c":8,"v":12,"d":"सर्वद्वाराणि संयम्य मनो हृदि निरुध्य च।\nमूर्ध्न्याधायात्मनः प्राणमास्थितो योगधारणाम्॥","t":"sarvadvārāṇi saṃyamya mano hṛdi nirudhya ca|\nmūrdhnyādhāyātmanaḥ prāṇamāsthito yogadhāraṇām||","e":"That way--the highest way--goes he who shuts\nThe gates of all his senses, locks desire\nSafe in his heart, centres the vital airs\nUpon his parting thought, steadfastly set;"},
{"c":8,"v":13,"d":"ओमित्येकाक्षरं ब्रह्म व्याहरन्मामनुस्मरन्।\nयः प्रयाति त्यजन्देहं स याति परमां गतिम्॥","t":"omityekākṣaraṃ brahma vyāharanmāmanusmaran|\nyaḥ prayāti tyajandehaṃ sa yāti paramāṃ gatim||","e":"And, murmuring OM, the sacred syllable--\nEmblem of BRAHM--dies, meditating Me."},
{"c":8,"v":14,"d":"अनन्यचेताः सततं यो मां स्मरति नित्यशः।\nतस्याहं सुलभः पार्थ नित्ययुक्तस्य योगिनः॥","t":"ananyacetāḥ satataṃ yo māṃ smarati nityaśaḥ|\ntasyāhaṃ sulabhaḥ pārtha nityayuktasya yoginaḥ||","e":"For who, none other Gods regarding, looks\nEver to Me, easily am I gained\nBy such a Yogi;"},
{"c":8,"v":15,"d":"मामुपेत्य पुनर्जन्म दुःखालयमशाश्वतम्।\nनाप्नुवन्ति महात्मानः संसिद्धिं परमां गताः॥","t":"māmupetya punarjanma duḥkhālayamaśāśvatam|\nnāpnuvanti mahātmānaḥ saṃsiddhiṃ paramāṃ gatāḥ||","e":"and, attaining Me,\nThey fall not--those Mahatmas--back to birth,\nTo life, which is the place of pain, which ends,\nBut take the way of utmost blessedness."},
{"c":8,"v":16,"d":"आब्रह्मभुवनाल्लोकाः पुनरावर्तिनोऽर्जुन।\nमामुपेत्य तु कौन्तेय पुनर्जन्म न विद्यते॥","t":"ābrahmabhuvanāllokāḥ punarāvartino'rjuna|\nmāmupetya tu kaunteya punarjanma na vidyate||","e":"The worlds, Arjuna!--even Brahma's world--\nRoll back again from Death to Life's unrest;\nBut they, O Kunti's Son! that reach to Me,\nTaste birth no more."},
{"c":8,"v":17,"d":"सहस्रयुगपर्यन्तमहर्यद्ब्रह्मणो विदुः।\nरात्रिं युगसहस्रान्तां तेऽहोरात्रविदो जनाः॥","t":"sahasrayugaparyantamaharyadbrahmaṇo viduḥ|\nrātriṃ yugasahasrāntāṃ te'horātravido janāḥ||","e":"If ye know Brahma's Day\nWhich is a thousand Yugas; if ye know\nThe thousand Yugas making Brahma's Night,\nThen know ye Day and Night as He doth know!"},
{"c":8,"v":18,"d":"अव्यक्ताद्व्यक्तयः सर्वाः प्रभवन्त्यहरागमे।\nरात्र्यागमे प्रलीयन्ते तत्रैवाव्यक्तसंज्ञके॥","t":"avyaktādvyaktayaḥ sarvāḥ prabhavantyaharāgame|\nrātryāgame pralīyante tatraivāvyaktasaṃjñake||","e":"When that vast Dawn doth break, th' Invisible\nIs brought anew into the Visible;\nWhen that deep Night doth darken, all which is\nFades back again to Him Who sent it forth;"},
{"c":8,"v":19,"d":"भूतग्रामः स एवायं भूत्वा भूत्वा प्रलीयते।\nरात्र्यागमेऽवशः पार्थ प्रभवत्यहरागमे॥","t":"bhūtagrāmaḥ sa evāyaṃ bhūtvā bhūtvā pralīyate|\nrātryāgame'vaśaḥ pārtha prabhavatyaharāgame||","e":"Yea! this vast company of living things--\nAgain and yet again produced--expires\nAt Brahma's Nightfall; and, at Brahma's Dawn,\nRiseth, without its will, to life new-born."},
{"c":8,"v":20,"d":"परस्तस्मात्तु भावोऽन्योऽव्यक्तोऽव्यक्तात्सनातनः।\nयः स सर्वेषु भूतेषु नश्यत्सु न विनश्यति॥","t":"parastasmāttu bhāvo'nyo'vyakto'vyaktātsanātanaḥ|\nyaḥ sa sarveṣu bhūteṣu naśyatsu na vinaśyati||","e":"But--higher, deeper, innermost--abides\nAnother Life, not like the life of sense,\nEscaping sight, unchanging. This endures\nWhen all created things have passed away:"},
{"c":8,"v":21,"d":"अव्यक्तोऽक्षर इत्युक्तस्तमाहुः परमां गतिम्।\nयं प्राप्य न निवर्तन्ते तद्धाम परमं मम॥","t":"avyakto'kṣara ityuktastamāhuḥ paramāṃ gatim|\nyaṃ prāpya na nivartante taddhāma paramaṃ mama||","e":"This is that Life named the Unmanifest,\nThe Infinite! the All! the Uttermost.\nThither arriving none return. That Life\nIs Mine, and I am there!"},
{"c":8,"v":22,"d":"पुरुषः स परः पार्थ भक्त्या लभ्यस्त्वनन्यया।\nयस्यान्तःस्थानि भूतानि येन सर्वमिदं ततम्॥","t":"puruṣaḥ sa paraḥ pārtha bhaktyā labhyastvananyayā|\nyasyāntaḥsthāni bhūtāni yena sarvamidaṃ tatam||","e":"And, Prince! by faith\nWhich wanders not, there is a way to come\nThither. I, the PURUSHA, I Who spread\nThe Universe around me--in Whom dwell\nAll living Things--may so be reached and seen!"},
{"c":8,"v":23,"d":"यत्र काले त्वनावृत्तिमावृत्तिं चैव योगिनः।\nप्रयाता यान्ति तं कालं वक्ष्यामि भरतर्षभ॥","t":"yatra kāle tvanāvṛttimāvṛttiṃ caiva yoginaḥ|\nprayātā yānti taṃ kālaṃ vakṣyāmi bharatarṣabha||","e":"","g":[23,24,25,26,27]},
{"c":8,"v":24,"d":"अग्निर्ज्योतिरहः शुक्लः षण्मासा उत्तरायणम्।\nतत्र प्रयाता गच्छन्ति ब्रह्म ब्रह्मविदो जनाः॥","t":"agnirjyotirahaḥ śuklaḥ ṣaṇmāsā uttarāyaṇam|\ntatra prayātā gacchanti brahma brahmavido janāḥ||","e":"","g":[23,24,25,26,27]},
{"c":8,"v":25,"d":"धूमो रात्रिस्तथा कृष्णः षण्मासा दक्षिणायनम्।\nतत्र चान्द्रमसं ज्योतिर्योगी प्राप्य निवर्तते॥","t":"dhūmo rātristathā kṛṣṇaḥ ṣaṇmāsā dakṣiṇāyanam|\ntatra cāndramasaṃ jyotiryogī prāpya nivartate||","e":"","g":[23,24,25,26,27]},
{"c":8,"v":26,"d":"शुक्लकृष्णे गती ह्येते जगतः शाश्वते मते।\nएकया यात्यनावृत्तिमन्ययाऽऽवर्तते पुनः॥","t":"śuklakṛṣṇe gatī hyete jagataḥ śāśvate mate|\nekayā yātyanāvṛttimanyayā''vartate punaḥ||","e":"","g":[23,24,25,26,27]},
{"c":8,"v":27,"d":"नैते सृती पार्थ जानन्योगी मुह्यति कश्चन।\nतस्मात्सर्वेषु कालेषु योगयुक्तो भवार्जुन॥","t":"naite sṛtī pārtha jānanyogī muhyati kaścana|\ntasmātsarveṣu kāleṣu yogayukto bhavārjuna||","e":"","g":[23,24,25,26,27]},
{"c":8,"v":28,"d":"वेदेषु यज्ञेषु तपःसु चैव\nदानेषु यत्पुण्यफलं प्रदिष्टम्।\nअत्येति तत्सर्वमिदं विदित्वा\nयोगी परं स्थानमुपैति चाद्यम्॥","t":"vedeṣu yajñeṣu tapaḥsu caiva\ndāneṣu yatpuṇyaphalaṃ pradiṣṭam|\natyeti tatsarvamidaṃ viditvā\nyogī paraṃ sthānamupaiti cādyam||","e":"Richer than holy fruit on Vedas growing,\nGreater than gifts, better than prayer or fast,\nSuch wisdom is! The Yogi, this way knowing,\nComes to the Utmost Perfect Peace at last."},
{"c":9,"v":1,"d":"श्री भगवानुवाच\nइदं तु ते गुह्यतमं प्रवक्ष्याम्यनसूयवे।\nज्ञानं विज्ञानसहितं यज्ज्ञात्वा मोक्ष्यसेऽशुभात्॥","t":"śrī bhagavānuvāca\nidaṃ tu te guhyatamaṃ pravakṣyāmyanasūyave|\njñānaṃ vijñānasahitaṃ yajjñātvā mokṣyase'śubhāt||","e":"Krishna.\nNow will I open unto thee--whose heart\nRejects not--that last lore, deepest-concealed,\nThat farthest secret of My Heavens and Earths,\nWhich but to know shall set thee free from ills,--"},
{"c":9,"v":2,"d":"राजविद्या राजगुह्यं पवित्रमिदमुत्तमम्।\nप्रत्यक्षावगमं धर्म्यं सुसुखं कर्तुमव्ययम्॥","t":"rājavidyā rājaguhyaṃ pavitramidamuttamam|\npratyakṣāvagamaṃ dharmyaṃ susukhaṃ kartumavyayam||","e":"A royal lore! a Kingly mystery!\nYea! for the soul such light as purgeth it\nFrom every sin; a light of holiness\nWith inmost splendour shining; plain to see;\nEasy to walk by, inexhaustible!"},
{"c":9,"v":3,"d":"अश्रद्दधानाः पुरुषा धर्मस्यास्य परन्तप।\nअप्राप्य मां निवर्तन्ते मृत्युसंसारवर्त्मनि॥","t":"aśraddadhānāḥ puruṣā dharmasyāsya parantapa|\naprāpya māṃ nivartante mṛtyusaṃsāravartmani||","e":"They that receive not this, failing in faith\nTo grasp the greater wisdom, reach not Me,\nDestroyer of thy foes! They sink anew\nInto the realm of Flesh, where all things change!"},
{"c":9,"v":4,"d":"मया ततमिदं सर्वं जगदव्यक्तमूर्तिना।\nमत्स्थानि सर्वभूतानि न चाहं तेष्ववस्थितः॥","t":"mayā tatamidaṃ sarvaṃ jagadavyaktamūrtinā|\nmatsthāni sarvabhūtāni na cāhaṃ teṣvavasthitaḥ||","e":"By Me the whole vast Universe of things\nIs spread abroad;--by Me, the Unmanifest!\nIn Me are all existences contained;\nNot I in them!"},
{"c":9,"v":5,"d":"न च मत्स्थानि भूतानि पश्य मे योगमैश्वरम्।\nभूतभृन्न च भूतस्थो ममात्मा भूतभावनः॥","t":"na ca matsthāni bhūtāni paśya me yogamaiśvaram|\nbhūtabhṛnna ca bhūtastho mamātmā bhūtabhāvanaḥ||","e":"Yet they are not contained,\nThose visible things! Receive and strive to embrace\nThe mystery majestical! My Being--\nCreating all, sustaining all--still dwells\nOutside of all!"},
{"c":9,"v":6,"d":"यथाऽऽकाशस्थितो नित्यं वायुः सर्वत्रगो महान्।\nतथा सर्वाणि भूतानि मत्स्थानीत्युपधारय॥","t":"yathā''kāśasthito nityaṃ vāyuḥ sarvatrago mahān|\ntathā sarvāṇi bhūtāni matsthānītyupadhāraya||","e":"See! as the shoreless airs\nMove in the measureless space, but are not space,\n[And space were space without the moving airs];\nSo all things are in Me, but are not I."},
{"c":9,"v":7,"d":"सर्वभूतानि कौन्तेय प्रकृतिं यान्ति मामिकाम्।\nकल्पक्षये पुनस्तानि कल्पादौ विसृजाम्यहम्॥","t":"sarvabhūtāni kaunteya prakṛtiṃ yānti māmikām|\nkalpakṣaye punastāni kalpādau visṛjāmyaham||","e":"At closing of each Kalpa, Indian Prince!\nAll things which be back to My Being come:\nAt the beginning of each Kalpa, all\nIssue new-born from Me."},
{"c":9,"v":8,"d":"प्रकृतिं स्वामवष्टभ्य विसृजामि पुनः पुनः।\nभूतग्राममिमं कृत्स्नमवशं प्रकृतेर्वशात्॥","t":"prakṛtiṃ svāmavaṣṭabhya visṛjāmi punaḥ punaḥ|\nbhūtagrāmamimaṃ kṛtsnamavaśaṃ prakṛtervaśāt||","e":"By Energy\nAnd help of Prakriti my outer Self,\nAgain, and yet again, I make go forth\nThe realms of visible things--without their will--\nAll of them--by the power of Prakriti."},
{"c":9,"v":9,"d":"न च मां तानि कर्माणि निबध्नन्ति धनञ्जय।\nउदासीनवदासीनमसक्तं तेषु कर्मसु॥","t":"na ca māṃ tāni karmāṇi nibadhnanti dhanañjaya|\nudāsīnavadāsīnamasaktaṃ teṣu karmasu||","e":"Yet these great makings, Prince! involve Me not\nEnchain Me not! I sit apart from them,\nOther, and Higher, and Free; nowise attached!"},
{"c":9,"v":10,"d":"मयाऽध्यक्षेण प्रकृतिः सूयते सचराचरम्।\nहेतुनाऽनेन कौन्तेय जगद्विपरिवर्तते॥","t":"mayā'dhyakṣeṇa prakṛtiḥ sūyate sacarācaram|\nhetunā'nena kaunteya jagadviparivartate||","e":"Thus doth the stuff of worlds, moulded by Me,\nBring forth all that which is, moving or still,\nLiving or lifeless! Thus the worlds go on!"},
{"c":9,"v":11,"d":"अवजानन्ति मां मूढा मानुषीं तनुमाश्रितम्।\nपरं भावमजानन्तो मम भूतमहेश्वरम्॥","t":"avajānanti māṃ mūḍhā mānuṣīṃ tanumāśritam|\nparaṃ bhāvamajānanto mama bhūtamaheśvaram||","e":"The minds untaught mistake Me, veiled in form;--\nNaught see they of My secret Presence, nought\nOf My hid Nature, ruling all which lives."},
{"c":9,"v":12,"d":"मोघाशा मोघकर्माणो मोघज्ञाना विचेतसः।\nराक्षसीमासुरीं चैव प्रकृतिं मोहिनीं श्रिताः॥","t":"moghāśā moghakarmāṇo moghajñānā vicetasaḥ|\nrākṣasīmāsurīṃ caiva prakṛtiṃ mohinīṃ śritāḥ||","e":"Vain hopes pursuing, vain deeds doing; fed\nOn vainest knowledge, senselessly they seek\nAn evil way, the way of brutes and fiends."},
{"c":9,"v":13,"d":"महात्मानस्तु मां पार्थ दैवीं प्रकृतिमाश्रिताः।\nभजन्त्यनन्यमनसो ज्ञात्वा भूतादिमव्ययम्॥","t":"mahātmānastu māṃ pārtha daivīṃ prakṛtimāśritāḥ|\nbhajantyananyamanaso jñātvā bhūtādimavyayam||","e":"But My Mahatmas, those of noble soul\nWho tread the path celestial, worship Me\nWith hearts unwandering,--knowing Me the Source,\nTh' Eternal Source, of Life."},
{"c":9,"v":14,"d":"सततं कीर्तयन्तो मां यतन्तश्च दृढव्रताः।\nनमस्यन्तश्च मां भक्त्या नित्ययुक्ता उपासते॥","t":"satataṃ kīrtayanto māṃ yatantaśca dṛḍhavratāḥ|\nnamasyantaśca māṃ bhaktyā nityayuktā upāsate||","e":"Unendingly\nThey glorify Me; seek Me; keep their vows\nOf reverence and love, with changeless faith\nAdoring Me."},
{"c":9,"v":15,"d":"ज्ञानयज्ञेन चाप्यन्ये यजन्तो मामुपासते।\nएकत्वेन पृथक्त्वेन बहुधा विश्वतोमुखम्॥","t":"jñānayajñena cāpyanye yajanto māmupāsate|\nekatvena pṛthaktvena bahudhā viśvatomukham||","e":"Yea, and those too adore,\nWho, offering sacrifice of wakened hearts,\nHave sense of one pervading Spirit's stress,\nOne Force in every place, though manifold!"},
{"c":9,"v":16,"d":"अहं क्रतुरहं यज्ञः स्वधाऽहमहमौषधम्।\nमंत्रोऽहमहमेवाज्यमहमग्निरहं हुतम्॥","t":"ahaṃ kraturahaṃ yajñaḥ svadhā'hamahamauṣadham|\nmaṃtro'hamahamevājyamahamagnirahaṃ hutam||","e":"I am the Sacrifice! I am the Prayer!\nI am the Funeral-Cake set for the dead!\nI am the healing herb! I am the ghee,\nThe Mantra, and the flame, and that which burns!"},
{"c":9,"v":17,"d":"पिताऽहमस्य जगतो माता धाता पितामहः।\nवेद्यं पवित्रमोंकार ऋक् साम यजुरेव च॥","t":"pitā'hamasya jagato mātā dhātā pitāmahaḥ|\nvedyaṃ pavitramoṃkāra ṛk sāma yajureva ca||","e":"I am-of all this boundless Universe-\nThe Father, Mother, Ancestor, and Guard!\nThe end of Learning! That which purifies\nIn lustral water! I am OM! I am\nRig-Veda, Sama-Veda, Yajur-Ved;"},
{"c":9,"v":18,"d":"गतिर्भर्ता प्रभुः साक्षी निवासः शरणं सुहृत्।\nप्रभवः प्रलयः स्थानं निधानं बीजमव्ययम्॥","t":"gatirbhartā prabhuḥ sākṣī nivāsaḥ śaraṇaṃ suhṛt|\nprabhavaḥ pralayaḥ sthānaṃ nidhānaṃ bījamavyayam||","e":"The Way, the Fosterer, the Lord, the Judge,\nThe Witness; the Abode, the Refuge-House,\nThe Friend, the Fountain and the Sea of Life\nWhich sends, and swallows up; Treasure of Worlds\nAnd Treasure-Chamber! Seed and Seed-Sower,\nWhence endless harvests spring!"},
{"c":9,"v":19,"d":"तपाम्यहमहं वर्षं निगृह्णाम्युत्सृजामि च।\nअमृतं चैव मृत्युश्च सदसच्चाहमर्जुन॥","t":"tapāmyahamahaṃ varṣaṃ nigṛhṇāmyutsṛjāmi ca|\namṛtaṃ caiva mṛtyuśca sadasaccāhamarjuna||","e":"Sun's heat is mine;\nHeaven's rain is mine to grant or to withhold;\nDeath am I, and Immortal Life I am,\nArjuna! SAT and ASAT, Visible Life,\nAnd Life Invisible!"},
{"c":9,"v":20,"d":"त्रैविद्या मां सोमपाः पूतपापा\nयज्ञैरिष्ट्वा स्वर्गतिं प्रार्थयन्ते।\nते पुण्यमासाद्य सुरेन्द्रलोक\nमश्नन्ति दिव्यान्दिवि देवभोगान्॥","t":"traividyā māṃ somapāḥ pūtapāpā\nyajñairiṣṭvā svargatiṃ prārthayante|\nte puṇyamāsādya surendraloka\nmaśnanti divyāndivi devabhogān||","e":"Yea! those who learn\nThe threefold Veds, who drink the Soma-wine,\nPurge sins, pay sacrifice--from Me they earn\nPassage to Swarga; where the meats divine\nOf great gods feed them in high Indra's heaven."},
{"c":9,"v":21,"d":"ते तं भुक्त्वा स्वर्गलोकं विशालं\nक्षीणे पुण्ये मर्त्यलोकं विशन्ति।\nएव त्रयीधर्ममनुप्रपन्ना\nगतागतं कामकामा लभन्ते॥","t":"te taṃ bhuktvā svargalokaṃ viśālaṃ\nkṣīṇe puṇye martyalokaṃ viśanti|\neva trayīdharmamanuprapannā\ngatāgataṃ kāmakāmā labhante||","e":"Yet they, when that prodigious joy is o'er,\nParadise spent, and wage for merits given,\nCome to the world of death and change once more.\nThey had their recompense! they stored their treasure,\nFollowing the threefold Scripture and its writ;\nWho seeketh such gaineth the fleeting pleasure\nOf joy which comes and goes! I grant them it!"},
{"c":9,"v":22,"d":"अनन्याश्चिन्तयन्तो मां ये जनाः पर्युपासते।\nतेषां नित्याभियुक्तानां योगक्षेमं वहाम्यहम्॥","t":"ananyāścintayanto māṃ ye janāḥ paryupāsate|\nteṣāṃ nityābhiyuktānāṃ yogakṣemaṃ vahāmyaham||","e":"But to those blessed ones who worship Me,\nTurning not otherwhere, with minds set fast,\nI bring assurance of full bliss beyond."},
{"c":9,"v":23,"d":"येऽप्यन्यदेवता भक्ता यजन्ते श्रद्धयाऽन्विताः।\nतेऽपि मामेव कौन्तेय यजन्त्यविधिपूर्वकम्॥","t":"ye'pyanyadevatā bhaktā yajante śraddhayā'nvitāḥ|\nte'pi māmeva kaunteya yajantyavidhipūrvakam||","e":"Nay, and of hearts which follow other gods\nIn simple faith, their prayers arise to me,\nO Kunti's Son! though they pray wrongfully;"},
{"c":9,"v":24,"d":"अहं हि सर्वयज्ञानां भोक्ता च प्रभुरेव च।\nन तु मामभिजानन्ति तत्त्वेनातश्च्यवन्ति ते॥","t":"ahaṃ hi sarvayajñānāṃ bhoktā ca prabhureva ca|\nna tu māmabhijānanti tattvenātaścyavanti te||","e":"For I am the Receiver and the Lord\nOf every sacrifice, which these know not\nRightfully; so they fall to earth again!"},
{"c":9,"v":25,"d":"यान्ति देवव्रता देवान् पितृ़न्यान्ति पितृव्रताः।\nभूतानि यान्ति भूतेज्या यान्ति मद्याजिनोऽपि माम्॥","t":"yānti devavratā devān pitṛnyānti pitṛvratāḥ|\nbhūtāni yānti bhūtejyā yānti madyājino'pi mām||","e":"Who follow gods go to their gods; who vow\nTheir souls to Pitris go to Pitris; minds\nTo evil Bhuts given o'er sink to the Bhuts;\nAnd whoso loveth Me cometh to Me."},
{"c":9,"v":26,"d":"पत्रं पुष्पं फलं तोयं यो मे भक्त्या प्रयच्छति।\nतदहं भक्त्युपहृतमश्नामि प्रयतात्मनः॥","t":"patraṃ puṣpaṃ phalaṃ toyaṃ yo me bhaktyā prayacchati|\ntadahaṃ bhaktyupahṛtamaśnāmi prayatātmanaḥ||","e":"Whoso shall offer Me in faith and love\nA leaf, a flower, a fruit, water poured forth,\nThat offering I accept, lovingly made\nWith pious will."},
{"c":9,"v":27,"d":"यत्करोषि यदश्नासि यज्जुहोषि ददासि यत्।\nयत्तपस्यसि कौन्तेय तत्कुरुष्व मदर्पणम्॥","t":"yatkaroṣi yadaśnāsi yajjuhoṣi dadāsi yat|\nyattapasyasi kaunteya tatkuruṣva madarpaṇam||","e":"Whate'er thou doest, Prince!\nEating or sacrificing, giving gifts,\nPraying or fasting, let it all be done\nFor Me, as Mine."},
{"c":9,"v":28,"d":"शुभाशुभफलैरेवं मोक्ष्यसे कर्मबन्धनैः।\nसंन्यासयोगयुक्तात्मा विमुक्तो मामुपैष्यसि॥","t":"śubhāśubhaphalairevaṃ mokṣyase karmabandhanaiḥ|\nsaṃnyāsayogayuktātmā vimukto māmupaiṣyasi||","e":"So shalt thou free thyself\nFrom Karmabandh, the chain which holdeth men\nTo good and evil issue, so shalt come\nSafe unto Me-when thou art quit of flesh--\nBy faith and abdication joined to Me!"},
{"c":9,"v":29,"d":"समोऽहं सर्वभूतेषु न मे द्वेष्योऽस्ति न प्रियः।\nये भजन्ति तु मां भक्त्या मयि ते तेषु चाप्यहम्॥","t":"samo'haṃ sarvabhūteṣu na me dveṣyo'sti na priyaḥ|\nye bhajanti tu māṃ bhaktyā mayi te teṣu cāpyaham||","e":"I am alike for all! I know not hate,\nI know not favour! What is made is Mine!\nBut them that worship Me with love, I love;\nThey are in Me, and I in them!"},
{"c":9,"v":30,"d":"अपि चेत्सुदुराचारो भजते मामनन्यभाक्।\nसाधुरेव स मन्तव्यः सम्यग्व्यवसितो हि सः॥","t":"api cetsudurācāro bhajate māmananyabhāk|\nsādhureva sa mantavyaḥ samyagvyavasito hi saḥ||","e":"Nay, Prince!\nIf one of evil life turn in his thought\nStraightly to Me, count him amidst the good;\nHe hath the high way chosen;"},
{"c":9,"v":31,"d":"क्षिप्रं भवति धर्मात्मा शश्वच्छान्तिं निगच्छति।\nकौन्तेय प्रतिजानीहि न मे भक्तः प्रणश्यति॥","t":"kṣipraṃ bhavati dharmātmā śaśvacchāntiṃ nigacchati|\nkaunteya pratijānīhi na me bhaktaḥ praṇaśyati||","e":"he shall grow\nRighteous ere long; he shall attain that peace\nWhich changes not. Thou Prince of India!\nBe certain none can perish, trusting Me!"},
{"c":9,"v":32,"d":"मां हि पार्थ व्यपाश्रित्य येऽपि स्युः पापयोनयः।\nस्त्रियो वैश्यास्तथा शूद्रास्तेऽपि यान्ति परां गतिम्॥","t":"māṃ hi pārtha vyapāśritya ye'pi syuḥ pāpayonayaḥ|\nstriyo vaiśyāstathā śūdrāste'pi yānti parāṃ gatim||","e":"O Pritha's Son! whoso will turn to Me,\nThough they be born from the very womb of Sin,\nWoman or man; sprung of the Vaisya caste\nOr lowly disregarded Sudra,--all\nPlant foot upon the highest path;"},
{"c":9,"v":33,"d":"किं पुनर्ब्राह्मणाः पुण्या भक्ता राजर्षयस्तथा।\nअनित्यमसुखं लोकमिमं प्राप्य भजस्व माम्॥","t":"kiṃ punarbrāhmaṇāḥ puṇyā bhaktā rājarṣayastathā|\nanityamasukhaṃ lokamimaṃ prāpya bhajasva mām||","e":"how then\nThe holy Brahmans and My Royal Saints?\nAh! ye who into this ill world are come--\nFleeting and false--set your faith fast on Me!"},
{"c":9,"v":34,"d":"मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु।\nमामेवैष्यसि युक्त्वैवमात्मानं मत्परायणः॥","t":"manmanā bhava madbhakto madyājī māṃ namaskuru|\nmāmevaiṣyasi yuktvaivamātmānaṃ matparāyaṇaḥ||","e":"Fix heart and thought on Me! Adore Me! Bring\nOfferings to Me! Make Me prostrations! Make\nMe your supremest joy! and, undivided,\nUnto My rest your spirits shall be guided."},
{"c":10,"v":1,"d":"श्री भगवानुवाच\nभूय एव महाबाहो श्रृणु मे परमं वचः।\nयत्तेऽहं प्रीयमाणाय वक्ष्यामि हितकाम्यया॥","t":"śrī bhagavānuvāca\nbhūya eva mahābāho śrṛṇu me paramaṃ vacaḥ|\nyatte'haṃ prīyamāṇāya vakṣyāmi hitakāmyayā||","e":"Krishna.[FN#l6]\nHear farther yet, thou Long-Armed Lord! these latest words I say--\nUttered to bring thee bliss and peace, who lovest Me alway--"},
{"c":10,"v":2,"d":"न मे विदुः सुरगणाः प्रभवं न महर्षयः।\nअहमादिर्हि देवानां महर्षीणां च सर्वशः॥","t":"na me viduḥ suragaṇāḥ prabhavaṃ na maharṣayaḥ|\nahamādirhi devānāṃ maharṣīṇāṃ ca sarvaśaḥ||","e":"Not the great company of gods nor kingly Rishis know\nMy Nature, Who have made the gods and Rishis long ago;"},
{"c":10,"v":3,"d":"यो मामजमनादिं च वेत्ति लोकमहेश्वरम्।\nअसम्मूढः स मर्त्येषु सर्वपापैः प्रमुच्यते॥","t":"yo māmajamanādiṃ ca vetti lokamaheśvaram|\nasammūḍhaḥ sa martyeṣu sarvapāpaiḥ pramucyate||","e":"He only knoweth-only he is free of sin, and wise,\nWho seeth Me, Lord of the Worlds, with faith-enlightened eyes,\nUnborn, undying, unbegun."},
{"c":10,"v":4,"d":"बुद्धिर्ज्ञानमसंमोहः क्षमा सत्यं दमः शमः।\nसुखं दुःखं भवोऽभावो भयं चाभयमेव च॥","t":"buddhirjñānamasaṃmohaḥ kṣamā satyaṃ damaḥ śamaḥ|\nsukhaṃ duḥkhaṃ bhavo'bhāvo bhayaṃ cābhayameva ca||","e":"Whatever Natures be\nTo mortal men distributed, those natures spring from Me!\nIntellect, skill, enlightenment, endurance, self-control,\nTruthfulness, equability, and grief or joy of soul,\nAnd birth and death, and fearfulness, and fearlessness, and shame,\nAnd honour, and sweet harmlessness, and peace which is the\nsame\nWhate'er befalls, and mirth, and tears, and piety, and thrift,\nAnd wish to give, and will to help,--all cometh of My gift!","g":[4,5]},
{"c":10,"v":5,"d":"अहिंसा समता तुष्टिस्तपो दानं यशोऽयशः।\nभवन्ति भावा भूतानां मत्त एव पृथग्विधाः॥","t":"ahiṃsā samatā tuṣṭistapo dānaṃ yaśo'yaśaḥ|\nbhavanti bhāvā bhūtānāṃ matta eva pṛthagvidhāḥ||","e":"Whatever Natures be\nTo mortal men distributed, those natures spring from Me!\nIntellect, skill, enlightenment, endurance, self-control,\nTruthfulness, equability, and grief or joy of soul,\nAnd birth and death, and fearfulness, and fearlessness, and shame,\nAnd honour, and sweet harmlessness, and peace which is the\nsame\nWhate'er befalls, and mirth, and tears, and piety, and thrift,\nAnd wish to give, and will to help,--all cometh of My gift!","g":[4,5]},
{"c":10,"v":6,"d":"महर्षयः सप्त पूर्वे चत्वारो मनवस्तथा।\nमद्भावा मानसा जाता येषां लोक इमाः प्रजाः॥","t":"maharṣayaḥ sapta pūrve catvāro manavastathā|\nmadbhāvā mānasā jātā yeṣāṃ loka imāḥ prajāḥ||","e":"The Seven Chief Saints, the Elders Four, the Lordly Manus set--\nSharing My work--to rule the worlds, these too did I beget;\nAnd Rishis, Pitris, Manus, all, by one thought of My mind;\nThence did arise, to fill this world, the races of mankind;"},
{"c":10,"v":7,"d":"एतां विभूतिं योगं च मम यो वेत्ति तत्त्वतः।\nसोऽविकम्पेन योगेन युज्यते नात्र संशयः॥","t":"etāṃ vibhūtiṃ yogaṃ ca mama yo vetti tattvataḥ|\nso'vikampena yogena yujyate nātra saṃśayaḥ||","e":"Wherefrom who comprehends My Reign of mystic Majesty--\nThat truth of truths--is thenceforth linked in faultless faith to Me:"},
{"c":10,"v":8,"d":"अहं सर्वस्य प्रभवो मत्तः सर्वं प्रवर्तते।\nइति मत्वा भजन्ते मां बुधा भावसमन्विताः॥","t":"ahaṃ sarvasya prabhavo mattaḥ sarvaṃ pravartate|\niti matvā bhajante māṃ budhā bhāvasamanvitāḥ||","e":"Yea! knowing Me the source of all, by Me all creatures wrought,\nThe wise in spirit cleave to Me, into My Being brought;"},
{"c":10,"v":9,"d":"मच्चित्ता मद्गतप्राणा बोधयन्तः परस्परम्।\nकथयन्तश्च मां नित्यं तुष्यन्ति च रमन्ति च॥","t":"maccittā madgataprāṇā bodhayantaḥ parasparam|\nkathayantaśca māṃ nityaṃ tuṣyanti ca ramanti ca||","e":"Hearts fixed on Me; breaths breathed to Me; praising Me, each to each,\nSo have they happiness and peace, with pious thought and speech;"},
{"c":10,"v":10,"d":"तेषां सततयुक्तानां भजतां प्रीतिपूर्वकम्।\nददामि बुद्धियोगं तं येन मामुपयान्ति ते॥","t":"teṣāṃ satatayuktānāṃ bhajatāṃ prītipūrvakam|\ndadāmi buddhiyogaṃ taṃ yena māmupayānti te||","e":"And unto these--thus serving well, thus loving ceaselessly--\nI give a mind of perfect mood, whereby they draw to Me;"},
{"c":10,"v":11,"d":"तेषामेवानुकम्पार्थमहमज्ञानजं तमः।\nनाशयाम्यात्मभावस्थो ज्ञानदीपेन भास्वता॥","t":"teṣāmevānukampārthamahamajñānajaṃ tamaḥ|\nnāśayāmyātmabhāvastho jñānadīpena bhāsvatā||","e":"And, all for love of them, within their darkened souls I dwell,\nAnd, with bright rays of wisdom's lamp, their ignorance dispel."},
{"c":10,"v":12,"d":"अर्जुन उवाच\nपरं ब्रह्म परं धाम पवित्रं परमं भवान्।\nपुरुषं शाश्वतं दिव्यमादिदेवमजं विभुम्॥","t":"arjuna uvāca\nparaṃ brahma paraṃ dhāma pavitraṃ paramaṃ bhavān|\npuruṣaṃ śāśvataṃ divyamādidevamajaṃ vibhum||","e":"Arjuna.\nYes! Thou art Parabrahm! The High Abode!\nThe Great Purification! Thou art God\nEternal, All-creating, Holy, First,\nWithout beginning! Lord of Lords and Gods!"},
{"c":10,"v":13,"d":"आहुस्त्वामृषयः सर्वे देवर्षिर्नारदस्तथा।\nअसितो देवलो व्यासः स्वयं चैव ब्रवीषि मे॥","t":"āhustvāmṛṣayaḥ sarve devarṣirnāradastathā|\nasito devalo vyāsaḥ svayaṃ caiva bravīṣi me||","e":"Declared by all the Saints--by Narada,\nVyasa Asita, and Devalas;\nAnd here Thyself declaring unto me!"},
{"c":10,"v":14,"d":"सर्वमेतदृतं मन्ये यन्मां वदसि केशव।\nन हि ते भगवन् व्यक्ितं विदुर्देवा न दानवाः॥","t":"sarvametadṛtaṃ manye yanmāṃ vadasi keśava|\nna hi te bhagavan vyaktaṃ vidurdevā na dānavāḥ||","e":"What Thou hast said now know I to be truth,\nO Kesava! that neither gods nor men\nNor demons comprehend Thy mystery\nMade manifest, Divinest!"},
{"c":10,"v":15,"d":"स्वयमेवात्मनाऽत्मानं वेत्थ त्वं पुरुषोत्तम।\nभूतभावन भूतेश देवदेव जगत्पते॥","t":"svayamevātmanā'tmānaṃ vettha tvaṃ puruṣottama|\nbhūtabhāvana bhūteśa devadeva jagatpate||","e":"Thou Thyself\nThyself alone dost know, Maker Supreme!\nMaster of all the living! Lord of Gods!\nKing of the Universe!"},
{"c":10,"v":16,"d":"वक्तुमर्हस्यशेषेण दिव्या ह्यात्मविभूतयः।\nयाभिर्विभूतिभिर्लोकानिमांस्त्वं व्याप्य तिष्ठसि॥","t":"vaktumarhasyaśeṣeṇa divyā hyātmavibhūtayaḥ|\nyābhirvibhūtibhirlokānimāṃstvaṃ vyāpya tiṣṭhasi||","e":"To Thee alone\nBelongs to tell the heavenly excellence\nOf those perfections wherewith Thou dost fill\nThese worlds of Thine; Pervading, Immanent!"},
{"c":10,"v":17,"d":"कथं विद्यामहं योगिंस्त्वां सदा परिचिन्तयन्।\nकेषु केषु च भावेषु चिन्त्योऽसि भगवन्मया॥","t":"kathaṃ vidyāmahaṃ yogiṃstvāṃ sadā paricintayan|\nkeṣu keṣu ca bhāveṣu cintyo'si bhagavanmayā||","e":"How shall I learn, Supremest Mystery!\nTo know Thee, though I muse continually?\nUnder what form of Thine unnumbered forms\nMayst Thou be grasped?"},
{"c":10,"v":18,"d":"विस्तरेणात्मनो योगं विभूतिं च जनार्दन।\nभूयः कथय तृप्तिर्हि श्रृण्वतो नास्ति मेऽमृतम्॥","t":"vistareṇātmano yogaṃ vibhūtiṃ ca janārdana|\nbhūyaḥ kathaya tṛptirhi śrṛṇvato nāsti me'mṛtam||","e":"Ah! yet again recount,\nClear and complete, Thy great appearances,\nThe secrets of Thy Majesty and Might,\nThou High Delight of Men! Never enough\nCan mine ears drink the Amrit of such words!"},
{"c":10,"v":19,"d":"श्री भगवानुवाच\nहन्त ते कथयिष्यामि दिव्या ह्यात्मविभूतयः।\nप्राधान्यतः कुरुश्रेष्ठ नास्त्यन्तो विस्तरस्य मे॥","t":"śrī bhagavānuvāca\nhanta te kathayiṣyāmi divyā hyātmavibhūtayaḥ|\nprādhānyataḥ kuruśreṣṭha nāstyanto vistarasya me||","e":"Krishna.\nHanta! So be it! Kuru Prince! I will to thee unfold\nSome portions of My Majesty, whose powers are manifold!"},
{"c":10,"v":20,"d":"अहमात्मा गुडाकेश सर्वभूताशयस्थितः।\nअहमादिश्च मध्यं च भूतानामन्त एव च॥","t":"ahamātmā guḍākeśa sarvabhūtāśayasthitaḥ|\nahamādiśca madhyaṃ ca bhūtānāmanta eva ca||","e":"I am the Spirit seated deep in every creature's heart;\nFrom Me they come; by Me they live; at My word they depart!"},
{"c":10,"v":21,"d":"आदित्यानामहं विष्णुर्ज्योतिषां रविरंशुमान्।\nमरीचिर्मरुतामस्मि नक्षत्राणामहं शशी॥","t":"ādityānāmahaṃ viṣṇurjyotiṣāṃ raviraṃśumān|\nmarīcirmarutāmasmi nakṣatrāṇāmahaṃ śaśī||","e":"Vishnu of the Adityas I am, those Lords of Light;\nMaritchi of the Maruts, the Kings of Storm and Blight;\nBy day I gleam, the golden Sun of burning cloudless Noon;\nBy Night, amid the asterisms I glide, the dappled Moon!"},
{"c":10,"v":22,"d":"वेदानां सामवेदोऽस्मि देवानामस्मि वासवः।\nइन्द्रियाणां मनश्चास्मि भूतानामस्मि चेतना॥","t":"vedānāṃ sāmavedo'smi devānāmasmi vāsavaḥ|\nindriyāṇāṃ manaścāsmi bhūtānāmasmi cetanā||","e":"Of Vedas I am Sama-Ved, of gods in Indra's Heaven\nVasava; of the faculties to living beings given\nThe mind which apprehends and thinks;"},
{"c":10,"v":23,"d":"रुद्राणां शङ्करश्चास्मि वित्तेशो यक्षरक्षसाम्।\nवसूनां पावकश्चास्मि मेरुः शिखरिणामहम्॥","t":"rudrāṇāṃ śaṅkaraścāsmi vitteśo yakṣarakṣasām|\nvasūnāṃ pāvakaścāsmi meruḥ śikhariṇāmaham||","e":"of Rudras Sankara;\nOf Yakshas and of Rakshasas, Vittesh; and Pavaka\nOf Vasus, and of mountain-peaks Meru;"},
{"c":10,"v":24,"d":"पुरोधसां च मुख्यं मां विद्धि पार्थ बृहस्पतिम्।\nसेनानीनामहं स्कन्दः सरसामस्मि सागरः॥","t":"purodhasāṃ ca mukhyaṃ māṃ viddhi pārtha bṛhaspatim|\nsenānīnāmahaṃ skandaḥ sarasāmasmi sāgaraḥ||","e":"Vrihaspati\nKnow Me 'mid planetary Powers; 'mid Warriors heavenly\nSkanda; of all the water-floods the Sea which drinketh each,"},
{"c":10,"v":25,"d":"महर्षीणां भृगुरहं गिरामस्म्येकमक्षरम्।\nयज्ञानां जपयज्ञोऽस्मि स्थावराणां हिमालयः॥","t":"maharṣīṇāṃ bhṛgurahaṃ girāmasmyekamakṣaram|\nyajñānāṃ japayajño'smi sthāvarāṇāṃ himālayaḥ||","e":"And Bhrigu of the holy Saints, and OM of sacred speech;\nOf prayers the prayer ye whisper; of hills Himala's snow,"},
{"c":10,"v":26,"d":"अश्वत्थः सर्ववृक्षाणां देवर्षीणां च नारदः।\nगन्धर्वाणां चित्ररथः सिद्धानां कपिलो मुनिः॥","t":"aśvatthaḥ sarvavṛkṣāṇāṃ devarṣīṇāṃ ca nāradaḥ|\ngandharvāṇāṃ citrarathaḥ siddhānāṃ kapilo muniḥ||","e":"And Aswattha, the fig-tree, of all the trees that grow;\nOf the Devarshis, Narada; and Chitrarath of them\nThat sing in Heaven, and Kapila of Munis,"},
{"c":10,"v":27,"d":"उच्चैःश्रवसमश्वानां विद्धि माममृतोद्भवम्।\nऐरावतं गजेन्द्राणां नराणां च नराधिपम्॥","t":"uccaiḥśravasamaśvānāṃ viddhi māmamṛtodbhavam|\nairāvataṃ gajendrāṇāṃ narāṇāṃ ca narādhipam||","e":"and the gem\nOf flying steeds, Uchchaisravas, from Amrit-wave which burst;\nOf elephants Airavata; of males the Best and First;"},
{"c":10,"v":28,"d":"आयुधानामहं वज्रं धेनूनामस्मि कामधुक्।\nप्रजनश्चास्मि कन्दर्पः सर्पाणामस्मि वासुकिः॥","t":"āyudhānāmahaṃ vajraṃ dhenūnāmasmi kāmadhuk|\nprajanaścāsmi kandarpaḥ sarpāṇāmasmi vāsukiḥ||","e":"Of weapons Heav'n's hot thunderbolt; of cows white Kamadhuk,\nFrom whose great milky udder-teats all hearts' desires are strook;\nVasuki of the serpent-tribes, round Mandara entwined;"},
{"c":10,"v":29,"d":"अनन्तश्चास्मि नागानां वरुणो यादसामहम्।\nपितृ़णामर्यमा चास्मि यमः संयमतामहम्॥","t":"anantaścāsmi nāgānāṃ varuṇo yādasāmaham|\npitṛṇāmaryamā cāsmi yamaḥ saṃyamatāmaham||","e":"And thousand-fanged Ananta, on whose broad coils reclined\nLeans Vishnu; and of water-things Varuna; Aryam\nOf Pitris, and, of those that judge, Yama the Judge I am;"},
{"c":10,"v":30,"d":"प्रह्लादश्चास्मि दैत्यानां कालः कलयतामहम्।\nमृगाणां च मृगेन्द्रोऽहं वैनतेयश्च पक्षिणाम्॥","t":"prahlādaścāsmi daityānāṃ kālaḥ kalayatāmaham|\nmṛgāṇāṃ ca mṛgendro'haṃ vainateyaśca pakṣiṇām||","e":"Of Daityas dread Prahlada; of what metes days and years,\nTime's self I am; of woodland-beasts-buffaloes, deers, and bears-\nThe lordly-painted tiger; of birds the vast Garud,"},
{"c":10,"v":31,"d":"पवनः पवतामस्मि रामः शस्त्रभृतामहम्।\nझषाणां मकरश्चास्मि स्रोतसामस्मि जाह्नवी॥","t":"pavanaḥ pavatāmasmi rāmaḥ śastrabhṛtāmaham|\njhaṣāṇāṃ makaraścāsmi srotasāmasmi jāhnavī||","e":"The whirlwind 'mid the winds; 'mid chiefs Rama with blood imbrued,\nMakar 'mid fishes of the sea, and Ganges 'mid the streams;"},
{"c":10,"v":32,"d":"सर्गाणामादिरन्तश्च मध्यं चैवाहमर्जुन।\nअध्यात्मविद्या विद्यानां वादः प्रवदतामहम्॥","t":"sargāṇāmādirantaśca madhyaṃ caivāhamarjuna|\nadhyātmavidyā vidyānāṃ vādaḥ pravadatāmaham||","e":"Yea! First, and Last, and Centre of all which is or seems\nI am, Arjuna! Wisdom Supreme of what is wise,\nWords on the uttering lips I am, and eyesight of the eyes,"},
{"c":10,"v":33,"d":"अक्षराणामकारोऽस्मि द्वन्द्वः सामासिकस्य च।\nअहमेवाक्षयः कालो धाताऽहं विश्वतोमुखः॥","t":"akṣarāṇāmakāro'smi dvandvaḥ sāmāsikasya ca|\nahamevākṣayaḥ kālo dhātā'haṃ viśvatomukhaḥ||","e":"And \"A\" of written characters, Dwandwa of knitted speech,\nAnd Endless Life, and boundless Love, whose power sustaineth each;"},
{"c":10,"v":34,"d":"मृत्युः सर्वहरश्चाहमुद्भवश्च भविष्यताम्।\nकीर्तिः श्रीर्वाक्च नारीणां स्मृतिर्मेधा धृतिः क्षमा॥","t":"mṛtyuḥ sarvaharaścāhamudbhavaśca bhaviṣyatām|\nkīrtiḥ śrīrvākca nārīṇāṃ smṛtirmedhā dhṛtiḥ kṣamā||","e":"And bitter Death which seizes all, and joyous sudden Birth,\nWhich brings to light all beings that are to be on earth;\nAnd of the viewless virtues, Fame, Fortune, Song am I,\nAnd Memory, and Patience; and Craft, and Constancy:"},
{"c":10,"v":35,"d":"बृहत्साम तथा साम्नां गायत्री छन्दसामहम्।\nमासानां मार्गशीर्षोऽहमृतूनां कुसुमाकरः॥","t":"bṛhatsāma tathā sāmnāṃ gāyatrī chandasāmaham|\nmāsānāṃ mārgaśīrṣo'hamṛtūnāṃ kusumākaraḥ||","e":"Of Vedic hymns the Vrihatsam, of metres Gayatri,\nOf months the Margasirsha, of all the seasons three\nThe flower-wreathed Spring;"},
{"c":10,"v":36,"d":"द्यूतं छलयतामस्मि तेजस्तेजस्विनामहम्।\nजयोऽस्मि व्यवसायोऽस्मि सत्त्वं सत्त्ववतामहम्॥","t":"dyūtaṃ chalayatāmasmi tejastejasvināmaham|\njayo'smi vyavasāyo'smi sattvaṃ sattvavatāmaham||","e":"in dicer's-play the conquering\nDouble-Eight;\nThe splendour of the splendid, and the greatness of the great,\nVictory I am, and Action! and the goodness of the good,"},
{"c":10,"v":37,"d":"वृष्णीनां वासुदेवोऽस्मि पाण्डवानां धनंजयः।\nमुनीनामप्यहं व्यासः कवीनामुशना कविः॥","t":"vṛṣṇīnāṃ vāsudevo'smi pāṇḍavānāṃ dhanaṃjayaḥ|\nmunīnāmapyahaṃ vyāsaḥ kavīnāmuśanā kaviḥ||","e":"And Vasudev of Vrishni's race, and of this Pandu brood\nThyself!--Yea, my Arjuna! thyself; for thou art Mine!\nOf poets Usana, of saints Vyasa, sage divine;"},
{"c":10,"v":38,"d":"दण्डो दमयतामस्मि नीतिरस्मि जिगीषताम्।\nमौनं चैवास्मि गुह्यानां ज्ञानं ज्ञानवतामहम्॥","t":"daṇḍo damayatāmasmi nītirasmi jigīṣatām|\nmaunaṃ caivāsmi guhyānāṃ jñānaṃ jñānavatāmaham||","e":"The policy of conquerors, the potency of kings,\nThe great unbroken silence in learning's secret things;\nThe lore of all the learned,"},
{"c":10,"v":39,"d":"यच्चापि सर्वभूतानां बीजं तदहमर्जुन।\nन तदस्ति विना यत्स्यान्मया भूतं चराचरम्॥","t":"yaccāpi sarvabhūtānāṃ bījaṃ tadahamarjuna|\nna tadasti vinā yatsyānmayā bhūtaṃ carācaram||","e":"the seed of all which springs.\nLiving or lifeless, still or stirred, whatever beings be,\nNone of them is in all the worlds, but it exists by Me!"},
{"c":10,"v":40,"d":"नान्तोऽस्ति मम दिव्यानां विभूतीनां परंतप।\nएष तूद्देशतः प्रोक्तो विभूतेर्विस्तरो मया॥","t":"nānto'sti mama divyānāṃ vibhūtīnāṃ paraṃtapa|\neṣa tūddeśataḥ prokto vibhūtervistaro mayā||","e":"Nor tongue can tell, Arjuna! nor end of telling come\nOf these My boundless glories, whereof I teach thee some;"},
{"c":10,"v":41,"d":"यद्यद्विभूतिमत्सत्त्वं श्रीमदूर्जितमेव वा।\nतत्तदेवावगच्छ त्वं मम तेजोंऽशसंभवम्॥","t":"yadyadvibhūtimatsattvaṃ śrīmadūrjitameva vā|\ntattadevāvagaccha tvaṃ mama tejoṃ'śasaṃbhavam||","e":"For wheresoe'er is wondrous work, and majesty, and might,\nFrom Me hath all proceeded. Receive thou this aright!"},
{"c":10,"v":42,"d":"अथवा बहुनैतेन किं ज्ञातेन तवार्जुन।\nविष्टभ्याहमिदं कृत्स्नमेकांशेन स्थितो जगत्॥","t":"athavā bahunaitena kiṃ jñātena tavārjuna|\nviṣṭabhyāhamidaṃ kṛtsnamekāṃśena sthito jagat||","e":"Yet how shouldst thou receive, O Prince! the vastness of this word?\nI, who am all, and made it all, abide its separate Lord!"},
{"c":11,"v":1,"d":"अर्जुन उवाच\nमदनुग्रहाय परमं गुह्यमध्यात्मसंज्ञितम्।\nयत्त्वयोक्तं वचस्तेन मोहोऽयं विगतो मम॥","t":"arjuna uvāca\nmadanugrahāya paramaṃ guhyamadhyātmasaṃjñitam|\nyattvayoktaṃ vacastena moho'yaṃ vigato mama||","e":"Arjuna.\nThis, for my soul's peace, have I heard from Thee,\nThe unfolding of the Mystery Supreme\nNamed Adhyatman; comprehending which,\nMy darkness is dispelled;"},
{"c":11,"v":2,"d":"भवाप्ययौ हि भूतानां श्रुतौ विस्तरशो मया।\nत्वत्तः कमलपत्राक्ष माहात्म्यमपि चाव्ययम्॥","t":"bhavāpyayau hi bhūtānāṃ śrutau vistaraśo mayā|\ntvattaḥ kamalapatrākṣa māhātmyamapi cāvyayam||","e":"for now I know--\nO Lotus-eyed!--whence is the birth of men,\nAnd whence their death, and what the majesties\nOf Thine immortal rule."},
{"c":11,"v":3,"d":"एवमेतद्यथात्थ त्वमात्मानं परमेश्वर।\nद्रष्टुमिच्छामि ते रूपमैश्वरं पुरुषोत्तम॥","t":"evametadyathāttha tvamātmānaṃ parameśvara|\ndraṣṭumicchāmi te rūpamaiśvaraṃ puruṣottama||","e":"Fain would I see,\nAs thou Thyself declar'st it, Sovereign Lord!\nThe likeness of that glory of Thy Form\nWholly revealed."},
{"c":11,"v":4,"d":"मन्यसे यदि तच्छक्यं मया द्रष्टुमिति प्रभो।\nयोगेश्वर ततो मे त्वं दर्शयाऽत्मानमव्ययम्॥","t":"manyase yadi tacchakyaṃ mayā draṣṭumiti prabho|\nyogeśvara tato me tvaṃ darśayā'tmānamavyayam||","e":"O Thou Divinest One!\nIf this can be, if I may bear the sight,\nMake Thyself visible, Lord of all prayers!\nShow me Thy very self, the Eternal God!"},
{"c":11,"v":5,"d":"श्री भगवानुवाच\nपश्य मे पार्थ रूपाणि शतशोऽथ सहस्रशः।\nनानाविधानि दिव्यानि नानावर्णाकृतीनि च॥","t":"śrī bhagavānuvāca\npaśya me pārtha rūpāṇi śataśo'tha sahasraśaḥ|\nnānāvidhāni divyāni nānāvarṇākṛtīni ca||","e":"Krishna.\nGaze, then, thou Son of Pritha! I manifest for thee\nThose hundred thousand thousand shapes that clothe my Mystery:\nI show thee all my semblances, infinite, rich, divine,\nMy changeful hues, my countless forms."},
{"c":11,"v":6,"d":"पश्यादित्यान्वसून्रुद्रानश्िवनौ मरुतस्तथा।\nबहून्यदृष्टपूर्वाणि पश्याऽश्चर्याणि भारत॥","t":"paśyādityānvasūnrudrānaśvanau marutastathā|\nbahūnyadṛṣṭapūrvāṇi paśyā'ścaryāṇi bhārata||","e":"See! in this face of mine,\nAdityas, Vasus, Rudras, Aswins, and Maruts; see\nWonders unnumbered, Indian Prince! revealed to none save thee."},
{"c":11,"v":7,"d":"इहैकस्थं जगत्कृत्स्नं पश्याद्य सचराचरम्।\nमम देहे गुडाकेश यच्चान्यद्द्रष्टुमिच्छसि॥","t":"ihaikasthaṃ jagatkṛtsnaṃ paśyādya sacarācaram|\nmama dehe guḍākeśa yaccānyaddraṣṭumicchasi||","e":"Behold! this is the Universe!--Look! what is live and dead\nI gather all in one--in Me! Gaze, as thy lips have said,\nOn GOD ETERNAL, VERY GOD! See Me! see what thou prayest!"},
{"c":11,"v":8,"d":"न तु मां शक्यसे द्रष्टुमनेनैव स्वचक्षुषा।\nदिव्यं ददामि ते चक्षुः पश्य मे योगमैश्वरम्॥","t":"na tu māṃ śakyase draṣṭumanenaiva svacakṣuṣā|\ndivyaṃ dadāmi te cakṣuḥ paśya me yogamaiśvaram||","e":"Thou canst not!--nor, with human eyes, Arjuna! ever mayest!\nTherefore I give thee sense divine. Have other eyes, new light!\nAnd, look! This is My glory, unveiled to mortal sight!"},
{"c":11,"v":9,"d":"सञ्जय उवाच\nएवमुक्त्वा ततो राजन्महायोगेश्वरो हरिः।\nदर्शयामास पार्थाय परमं रूपमैश्वरम्॥","t":"sañjaya uvāca\nevamuktvā tato rājanmahāyogeśvaro hariḥ|\ndarśayāmāsa pārthāya paramaṃ rūpamaiśvaram||","e":"Sanjaya.\nThen, O King! the God, so saying,\nStood, to Pritha's Son displaying\nAll the splendour, wonder, dread\nOf His vast Almighty-head."},
{"c":11,"v":10,"d":"अनेकवक्त्रनयनमनेकाद्भुतदर्शनम्।\nअनेकदिव्याभरणं दिव्यानेकोद्यतायुधम्॥","t":"anekavaktranayanamanekādbhutadarśanam|\nanekadivyābharaṇaṃ divyānekodyatāyudham||","e":"Out of countless eyes beholding,\nOut of countless mouths commanding,\nCountless mystic forms enfolding\nIn one Form: supremely standing\nCountless radiant glories wearing,\nCountless heavenly weapons bearing,"},
{"c":11,"v":11,"d":"दिव्यमाल्याम्बरधरं दिव्यगन्धानुलेपनम्।\nसर्वाश्चर्यमयं देवमनन्तं विश्वतोमुखम्॥","t":"divyamālyāmbaradharaṃ divyagandhānulepanam|\nsarvāścaryamayaṃ devamanantaṃ viśvatomukham||","e":"Crowned with garlands of star-clusters,\nRobed in garb of woven lustres,\nBreathing from His perfect Presence\nBreaths of every subtle essence\nOf all heavenly odours; shedding\nBlinding brilliance; overspreading--\nBoundless, beautiful--all spaces\nWith His all-regarding faces;\nSo He showed!"},
{"c":11,"v":12,"d":"दिवि सूर्यसहस्रस्य भवेद्युगपदुत्थिता।\nयदि भाः सदृशी सा स्याद्भासस्तस्य महात्मनः॥","t":"divi sūryasahasrasya bhavedyugapadutthitā|\nyadi bhāḥ sadṛśī sā syādbhāsastasya mahātmanaḥ||","e":"If there should rise\nSuddenly within the skies\nSunburst of a thousand suns\nFlooding earth with beams undeemed-of,\nThen might be that Holy One's\nMajesty and radiance dreamed of!"},
{"c":11,"v":13,"d":"तत्रैकस्थं जगत्कृत्स्नं प्रविभक्तमनेकधा।\nअपश्यद्देवदेवस्य शरीरे पाण्डवस्तदा॥","t":"tatraikasthaṃ jagatkṛtsnaṃ pravibhaktamanekadhā|\napaśyaddevadevasya śarīre pāṇḍavastadā||","e":"So did Pandu's Son behold\nAll this universe enfold\nAll its huge diversity\nInto one vast shape, and be\nVisible, and viewed, and blended\nIn one Body--subtle, splendid,\nNameless--th' All-comprehending\nGod of Gods, the Never-Ending\nDeity!"},
{"c":11,"v":14,"d":"ततः स विस्मयाविष्टो हृष्टरोमा धनञ्जयः।\nप्रणम्य शिरसा देवं कृताञ्जलिरभाषत॥","t":"tataḥ sa vismayāviṣṭo hṛṣṭaromā dhanañjayaḥ|\npraṇamya śirasā devaṃ kṛtāñjalirabhāṣata||","e":"But, sore amazed,\nThrilled, o'erfilled, dazzled, and dazed,\nArjuna knelt; and bowed his head,\nAnd clasped his palms; and cried, and said:"},
{"c":11,"v":15,"d":"अर्जुन उवाच\nपश्यामि देवांस्तव देव देहे\nसर्वांस्तथा भूतविशेषसङ्घान्।\nब्रह्माणमीशं कमलासनस्थ\nमृषींश्च सर्वानुरगांश्च दिव्यान्॥","t":"arjuna uvāca\npaśyāmi devāṃstava deva dehe\nsarvāṃstathā bhūtaviśeṣasaṅghān|\nbrahmāṇamīśaṃ kamalāsanastha\nmṛṣīṃśca sarvānuragāṃśca divyān||","e":"Arjuna.\nYea! I have seen! I see!\nLord! all is wrapped in Thee!\nThe gods are in Thy glorious frame! the creatures\nOf earth, and heaven, and hell\nIn Thy Divine form dwell,\nAnd in Thy countenance shine all the features\nOf Brahma, sitting lone\nUpon His lotus-throne;\nOf saints and sages, and the serpent races\nAnanta, Vasuki;"},
{"c":11,"v":16,"d":"अनेकबाहूदरवक्त्रनेत्रं\nपश्यामि त्वां सर्वतोऽनन्तरूपम्।\nनान्तं न मध्यं न पुनस्तवादिं\nपश्यामि विश्वेश्वर विश्वरूप॥","t":"anekabāhūdaravaktranetraṃ\npaśyāmi tvāṃ sarvato'nantarūpam|\nnāntaṃ na madhyaṃ na punastavādiṃ\npaśyāmi viśveśvara viśvarūpa||","e":"Yea! mightiest Lord! I see\nThy thousand thousand arms, and breasts, and faces,\nAnd eyes,--on every side\nPerfect, diversified;\nAnd nowhere end of Thee, nowhere beginning,\nNowhere a centre! Shifts--\nWherever soul's gaze lifts--\nThy central Self, all-wielding, and all-winning!"},
{"c":11,"v":17,"d":"किरीटिनं गदिनं चक्रिणं च\nतेजोराशिं सर्वतोदीप्तिमन्तम्।\nपश्यामि त्वां दुर्निरीक्ष्यं समन्ता\nद्दीप्तानलार्कद्युतिमप्रमेयम्॥","t":"kirīṭinaṃ gadinaṃ cakriṇaṃ ca\ntejorāśiṃ sarvatodīptimantam|\npaśyāmi tvāṃ durnirīkṣyaṃ samantā\nddīptānalārkadyutimaprameyam||","e":"Infinite King! I see\nThe anadem on Thee,\nThe club, the shell, the discus; see Thee burning\nIn beams insufferable,\nLighting earth, heaven, and hell\nWith brilliance blazing, glowing, flashing; turning\nDarkness to dazzling day,\nLook I whichever way;"},
{"c":11,"v":18,"d":"त्वमक्षरं परमं वेदितव्यं\nत्वमस्य विश्वस्य परं निधानम्।\nत्वमव्ययः शाश्वतधर्मगोप्ता\nसनातनस्त्वं पुरुषो मतो मे॥","t":"tvamakṣaraṃ paramaṃ veditavyaṃ\ntvamasya viśvasya paraṃ nidhānam|\ntvamavyayaḥ śāśvatadharmagoptā\nsanātanastvaṃ puruṣo mato me||","e":"Ah, Lord! I worship Thee, the Undivided,\nThe Uttermost of thought,\nThe Treasure-Palace wrought\nTo hold the wealth of the worlds; the Shield provided\nTo shelter Virtue's laws;\nThe Fount whence Life's stream draws\nAll waters of all rivers of all being:"},
{"c":11,"v":19,"d":"अनादिमध्यान्तमनन्तवीर्य\nमनन्तबाहुं शशिसूर्यनेत्रम्।\nपश्यामि त्वां दीप्तहुताशवक्त्रम्\nस्वतेजसा विश्वमिदं तपन्तम्॥","t":"anādimadhyāntamanantavīrya\nmanantabāhuṃ śaśisūryanetram|\npaśyāmi tvāṃ dīptahutāśavaktram\nsvatejasā viśvamidaṃ tapantam||","e":"The One Unborn, Unending:\nUnchanging and Unblending!\nWith might and majesty, past thought, past seeing!\nSilver of moon and gold\nOf sun are glories rolled\nFrom Thy great eyes; Thy visage, beaming tender\nThroughout the stars and skies,\nDoth to warm life surprise\nThy Universe."},
{"c":11,"v":20,"d":"द्यावापृथिव्योरिदमन्तरं हि\nव्याप्तं त्वयैकेन दिशश्च सर्वाः।\nदृष्ट्वाऽद्भुतं रूपमुग्रं तवेदं\nलोकत्रयं प्रव्यथितं महात्मन्॥","t":"dyāvāpṛthivyoridamantaraṃ hi\nvyāptaṃ tvayaikena diśaśca sarvāḥ|\ndṛṣṭvā'dbhutaṃ rūpamugraṃ tavedaṃ\nlokatrayaṃ pravyathitaṃ mahātman||","e":"The worlds are filled with wonder\nOf Thy perfections! Space\nStar-sprinkled, and void place\nFrom pole to pole of the Blue, from bound to bound,\nHath Thee in every spot,\nThee, Thee!--Where Thou art not,\nO Holy, Marvellous Form! is nowhere found!\nO Mystic, Awful One!\nAt sight of Thee, made known,\nThe Three Worlds quake;"},
{"c":11,"v":21,"d":"अमी हि त्वां सुरसङ्घाः विशन्ति\nकेचिद्भीताः प्राञ्जलयो गृणन्ति।\nस्वस्तीत्युक्त्वा महर्षिसिद्धसङ्घाः\nस्तुवन्ति त्वां स्तुतिभिः पुष्कलाभिः॥","t":"amī hi tvāṃ surasaṅghāḥ viśanti\nkecidbhītāḥ prāñjalayo gṛṇanti|\nsvastītyuktvā maharṣisiddhasaṅghāḥ\nstuvanti tvāṃ stutibhiḥ puṣkalābhiḥ||","e":"the lower gods draw nigh Thee;\nThey fold their palms, and bow\nBody, and breast, and brow,\nAnd, whispering worship, laud and magnify Thee!\nRishis and Siddhas cry\n\"Hail! Highest Majesty!\"\nFrom sage and singer breaks the hymn of glory\nIn dulcet harmony,\nSounding the praise of Thee;\nWhile countless companies take up the story,"},
{"c":11,"v":22,"d":"रुद्रादित्या वसवो ये च साध्या\nविश्वेऽश्िवनौ मरुतश्चोष्मपाश्च।\nगन्धर्वयक्षासुरसिद्धसङ्घा\nवीक्षन्ते त्वां विस्मिताश्चैव सर्वे॥","t":"rudrādityā vasavo ye ca sādhyā\nviśve'śvanau marutaścoṣmapāśca|\ngandharvayakṣāsurasiddhasaṅghā\nvīkṣante tvāṃ vismitāścaiva sarve||","e":"Rudras, who ride the storms,\nTh' Adityas' shining forms,\nVasus and Sadhyas, Viswas, Ushmapas;\nMaruts, and those great Twins\nThe heavenly, fair, Aswins,\nGandharvas, Rakshasas, Siddhas, and Asuras,--\nThese see Thee, and revere\nIn sudden-stricken fear;"},
{"c":11,"v":23,"d":"रूपं महत्ते बहुवक्त्रनेत्रं\nमहाबाहो बहुबाहूरुपादम्।\nबहूदरं बहुदंष्ट्राकरालं\nदृष्ट्वा लोकाः प्रव्यथितास्तथाऽहम्॥","t":"rūpaṃ mahatte bahuvaktranetraṃ\nmahābāho bahubāhūrupādam|\nbahūdaraṃ bahudaṃṣṭrākarālaṃ\ndṛṣṭvā lokāḥ pravyathitāstathā'ham||","e":"Yea! the Worlds,--seeing Thee with form stupendous,\nWith faces manifold,\nWith eyes which all behold,\nUnnumbered eyes, vast arms, members tremendous,\nFlanks, lit with sun and star,\nFeet planted near and far,\nTushes of terror, mouths wrathful and tender;--\nThe Three wide Worlds before Thee\nAdore, as I adore Thee,\nQuake, as I quake, to witness so much splendour!"},
{"c":11,"v":24,"d":"नभःस्पृशं दीप्तमनेकवर्णं\nव्यात्ताननं दीप्तविशालनेत्रम्।\nदृष्ट्वा हि त्वां प्रव्यथितान्तरात्मा\nधृतिं न विन्दामि शमं च विष्णो॥","t":"nabhaḥspṛśaṃ dīptamanekavarṇaṃ\nvyāttānanaṃ dīptaviśālanetram|\ndṛṣṭvā hi tvāṃ pravyathitāntarātmā\ndhṛtiṃ na vindāmi śamaṃ ca viṣṇo||","e":"I mark Thee strike the skies\nWith front, in wondrous wise\nHuge, rainbow-painted, glittering; and thy mouth\nOpened, and orbs which see\nAll things, whatever be\nIn all Thy worlds, east, west, and north and south.\nO Eyes of God! O Head!\nMy strength of soul is fled,\nGone is heart's force, rebuked is mind's desire!"},
{"c":11,"v":25,"d":"दंष्ट्राकरालानि च ते मुखानि\nदृष्ट्वैव कालानलसन्निभानि।\nदिशो न जाने न लभे च शर्म\nप्रसीद देवेश जगन्निवास॥","t":"daṃṣṭrākarālāni ca te mukhāni\ndṛṣṭvaiva kālānalasannibhāni|\ndiśo na jāne na labhe ca śarma\nprasīda deveśa jagannivāsa||","e":"When I behold Thee so,\nWith awful brows a-glow,\nWith burning glance, and lips lighted by fire\nFierce as those flames which shall\nConsume, at close of all,\nEarth, Heaven! Ah me! I see no Earth and Heaven!\nThee, Lord of Lords! I see,\nThee only-only Thee!\nNow let Thy mercy unto me be given,\nThou Refuge of the World!"},
{"c":11,"v":26,"d":"अमी च त्वां धृतराष्ट्रस्य पुत्राः\nसर्वे सहैवावनिपालसङ्घैः।\nभीष्मो द्रोणः सूतपुत्रस्तथाऽसौ\nसहास्मदीयैरपि योधमुख्यैः॥","t":"amī ca tvāṃ dhṛtarāṣṭrasya putrāḥ\nsarve sahaivāvanipālasaṅghaiḥ|\nbhīṣmo droṇaḥ sūtaputrastathā'sau\nsahāsmadīyairapi yodhamukhyaiḥ||","e":"Lo! to the cavern hurled\nOf Thy wide-opened throat, and lips white-tushed,\nI see our noblest ones,\nGreat Dhritarashtra's sons,\nBhishma, Drona, and Karna, caught and crushed!\nThe Kings and Chiefs drawn in,\nThat gaping gorge within;\nThe best of both these armies torn and riven!\nBetween Thy jaws they lie\nMangled full bloodily,\nGround into dust and death!","g":[26,27]},
{"c":11,"v":27,"d":"वक्त्राणि ते त्वरमाणा विशन्ति\nदंष्ट्राकरालानि भयानकानि।\nकेचिद्विलग्ना दशनान्तरेषु\nसंदृश्यन्ते चूर्णितैरुत्तमाङ्गैः॥","t":"vaktrāṇi te tvaramāṇā viśanti\ndaṃṣṭrākarālāni bhayānakāni|\nkecidvilagnā daśanāntareṣu\nsaṃdṛśyante cūrṇitairuttamāṅgaiḥ||","e":"Lo! to the cavern hurled\nOf Thy wide-opened throat, and lips white-tushed,\nI see our noblest ones,\nGreat Dhritarashtra's sons,\nBhishma, Drona, and Karna, caught and crushed!\nThe Kings and Chiefs drawn in,\nThat gaping gorge within;\nThe best of both these armies torn and riven!\nBetween Thy jaws they lie\nMangled full bloodily,\nGround into dust and death!","g":[26,27]},
{"c":11,"v":28,"d":"यथा नदीनां बहवोऽम्बुवेगाः\nसमुद्रमेवाभिमुखाः द्रवन्ति।\nतथा तवामी नरलोकवीरा\nविशन्ति वक्त्राण्यभिविज्वलन्ति॥","t":"yathā nadīnāṃ bahavo'mbuvegāḥ\nsamudramevābhimukhāḥ dravanti|\ntathā tavāmī naralokavīrā\nviśanti vaktrāṇyabhivijvalanti||","e":"Like streams down-driven\nWith helpless haste, which go\nIn headlong furious flow\nStraight to the gulfing deeps of th' unfilled ocean,\nSo to that flaming cave\nThose heroes great and brave\nPour, in unending streams, with helpless motion!"},
{"c":11,"v":29,"d":"यथा प्रदीप्तं ज्वलनं पतङ्गा\nविशन्ति नाशाय समृद्धवेगाः।\nतथैव नाशाय विशन्ति लोका\nस्तवापि वक्त्राणि समृद्धवेगाः॥","t":"yathā pradīptaṃ jvalanaṃ pataṅgā\nviśanti nāśāya samṛddhavegāḥ|\ntathaiva nāśāya viśanti lokā\nstavāpi vaktrāṇi samṛddhavegāḥ||","e":"Like moths which in the night\nFlutter towards a light,\nDrawn to their fiery doom, flying and dying,\nSo to their death still throng,\nBlind, dazzled, borne along\nCeaselessly, all those multitudes, wild flying!"},
{"c":11,"v":30,"d":"लेलिह्यसे ग्रसमानः समन्ता\nल्लोकान्समग्रान्वदनैर्ज्वलद्भिः।\nतेजोभिरापूर्य जगत्समग्रं\nभासस्तवोग्राः प्रतपन्ति विष्णो॥","t":"lelihyase grasamānaḥ samantā\nllokānsamagrānvadanairjvaladbhiḥ|\ntejobhirāpūrya jagatsamagraṃ\nbhāsastavogrāḥ pratapanti viṣṇo||","e":"Thou, that hast fashioned men,\nDevourest them again,\nOne with another, great and small, alike!\nThe creatures whom Thou mak'st,\nWith flaming jaws Thou tak'st,\nLapping them up! Lord God! Thy terrors strike\nFrom end to end of earth,\nFilling life full, from birth\nTo death, with deadly, burning, lurid dread!"},
{"c":11,"v":31,"d":"आख्याहि मे को भवानुग्ररूपो\nनमोऽस्तु ते देववर प्रसीद।\nविज्ञातुमिच्छामि भवन्तमाद्यं\nन हि प्रजानामि तव प्रवृत्तिम्॥","t":"ākhyāhi me ko bhavānugrarūpo\nnamo'stu te devavara prasīda|\nvijñātumicchāmi bhavantamādyaṃ\nna hi prajānāmi tava pravṛttim||","e":"Ah, Vishnu! make me know\nWhy is Thy visage so?\nWho art Thou, feasting thus upon Thy dead?\nWho? awful Deity!\nI bow myself to Thee,\nNamostu Te, Devavara! Prasid!\nO Mightiest Lord! rehearse\nWhy hast Thou face so fierce?\nWhence doth this aspect horrible proceed?"},
{"c":11,"v":32,"d":"श्री भगवानुवाच\nकालोऽस्मि लोकक्षयकृत्प्रवृद्धो\nलोकान्समाहर्तुमिह प्रवृत्तः।\nऋतेऽपि त्वां न भविष्यन्ति सर्वे\nयेऽवस्थिताः प्रत्यनीकेषु योधाः॥","t":"śrī bhagavānuvāca\nkālo'smi lokakṣayakṛtpravṛddho\nlokānsamāhartumiha pravṛttaḥ|\nṛte'pi tvāṃ na bhaviṣyanti sarve\nye'vasthitāḥ pratyanīkeṣu yodhāḥ||","e":"Krishna.\nThou seest Me as Time who kills,\nTime who brings all to doom,\nThe Slayer Time, Ancient of Days, come hither to consume;\nExcepting thee, of all these hosts of hostile chiefs arrayed,\nThere stands not one shall leave alive the battlefield!"},
{"c":11,"v":33,"d":"तस्मात्त्वमुत्तिष्ठ यशो लभस्व\nजित्वा शत्रून् भुङ्क्ष्व राज्यं समृद्धम्।\nमयैवैते निहताः पूर्वमेव\nनिमित्तमात्रं भव सव्यसाचिन्॥","t":"tasmāttvamuttiṣṭha yaśo labhasva\njitvā śatrūn bhuṅkṣva rājyaṃ samṛddham|\nmayaivaite nihatāḥ pūrvameva\nnimittamātraṃ bhava savyasācin||","e":"Dismayed\nNo longer be! Arise! obtain renown! destroy thy foes!\nFight for the kingdom waiting thee when thou hast vanquished those.\nBy Me they fall--not thee! the stroke of death is dealt them now,\nEven as they show thus gallantly; My instrument art thou!"},
{"c":11,"v":34,"d":"द्रोणं च भीष्मं च जयद्रथं च\nकर्णं तथाऽन्यानपि योधवीरान्।\nमया हतांस्त्वं जहि मा व्यथिष्ठा\nयुध्यस्व जेतासि रणे सपत्नान्॥","t":"droṇaṃ ca bhīṣmaṃ ca jayadrathaṃ ca\nkarṇaṃ tathā'nyānapi yodhavīrān|\nmayā hatāṃstvaṃ jahi mā vyathiṣṭhā\nyudhyasva jetāsi raṇe sapatnān||","e":"Strike, strong-armed Prince, at Drona! at Bhishma strike! deal death\nOn Karna, Jyadratha; stay all their warlike breath!\n'Tis I who bid them perish! Thou wilt but slay the slain;\nFight! they must fall, and thou must live, victor upon this plain!"},
{"c":11,"v":35,"d":"सञ्जय उवाच\nएतच्छ्रुत्वा वचनं केशवस्य\nकृताञ्जलिर्वेपमानः किरीटी।\nनमस्कृत्वा भूय एवाह कृष्णं\nसगद्गदं भीतभीतः प्रणम्य॥","t":"sañjaya uvāca\netacchrutvā vacanaṃ keśavasya\nkṛtāñjalirvepamānaḥ kirīṭī|\nnamaskṛtvā bhūya evāha kṛṣṇaṃ\nsagadgadaṃ bhītabhītaḥ praṇamya||","e":"Sanjaya.\nHearing mighty Keshav's word,\nTremblingly that helmed Lord\nClasped his lifted palms, and--praying\nGrace of Krishna--stood there, saying,\nWith bowed brow and accents broken,\nThese words, timorously spoken:"},
{"c":11,"v":36,"d":"अर्जुन उवाच\nस्थाने हृषीकेश तव प्रकीर्त्या\nजगत् प्रहृष्यत्यनुरज्यते च।\nरक्षांसि भीतानि दिशो द्रवन्ति\nसर्वे नमस्यन्ति च सिद्धसङ्घाः॥","t":"arjuna uvāca\nsthāne hṛṣīkeśa tava prakīrtyā\njagat prahṛṣyatyanurajyate ca|\nrakṣāṃsi bhītāni diśo dravanti\nsarve namasyanti ca siddhasaṅghāḥ||","e":"Arjuna.\nWorthily, Lord of Might!\nThe whole world hath delight\nIn Thy surpassing power, obeying Thee;\nThe Rakshasas, in dread\nAt sight of Thee, are sped\nTo all four quarters; and the company\nOf Siddhas sound Thy name."},
{"c":11,"v":37,"d":"कस्माच्च ते न नमेरन्महात्मन्\nगरीयसे ब्रह्मणोऽप्यादिकर्त्रे।\nअनन्त देवेश जगन्निवास\nत्वमक्षरं सदसत्तत्परं यत्॥","t":"kasmācca te na nameranmahātman\ngarīyase brahmaṇo'pyādikartre|\nananta deveśa jagannivāsa\ntvamakṣaraṃ sadasattatparaṃ yat||","e":"How should they not proclaim\nThy Majesties, Divinest, Mightiest?\nThou Brahm, than Brahma greater!\nThou Infinite Creator!\nThou God of gods, Life's Dwelling-place and Rest!\nThou, of all souls the Soul!\nThe Comprehending Whole!\nOf being formed, and formless being the Framer;"},
{"c":11,"v":38,"d":"त्वमादिदेवः पुरुषः पुराण\nस्त्वमस्य विश्वस्य परं निधानम्।\nवेत्तासि वेद्यं च परं च धाम\nत्वया ततं विश्वमनन्तरूप॥","t":"tvamādidevaḥ puruṣaḥ purāṇa\nstvamasya viśvasya paraṃ nidhānam|\nvettāsi vedyaṃ ca paraṃ ca dhāma\ntvayā tataṃ viśvamanantarūpa||","e":"O Utmost One! O Lord!\nOlder than eld, Who stored\nThe worlds with wealth of life! O Treasure-Claimer,\nWho wottest all, and art\nWisdom Thyself! O Part\nIn all, and All; for all from Thee have risen\nNumberless now I see\nThe aspects are of Thee!"},
{"c":11,"v":39,"d":"वायुर्यमोऽग्निर्वरुणः शशाङ्कः\nप्रजापतिस्त्वं प्रपितामहश्च।\nनमो नमस्तेऽस्तु सहस्रकृत्वः\nपुनश्च भूयोऽपि नमो नमस्ते॥","t":"vāyuryamo'gnirvaruṇaḥ śaśāṅkaḥ\nprajāpatistvaṃ prapitāmahaśca|\nnamo namaste'stu sahasrakṛtvaḥ\npunaśca bhūyo'pi namo namaste||","e":"Vayu Thou art, and He who keeps the prison\nOf Narak, Yama dark;\nAnd Agni's shining spark;\nVaruna's waves are Thy waves. Moon and starlight\nAre Thine! Prajapati\nArt Thou, and 'tis to Thee\nThey knelt in worshipping the old world's far light,\nThe first of mortal men.\nAgain, Thou God! again\nA thousand thousand times be magnified!"},
{"c":11,"v":40,"d":"नमः पुरस्तादथ पृष्ठतस्ते\nनमोऽस्तु ते सर्वत एव सर्व।\nअनन्तवीर्यामितविक्रमस्त्वं\nसर्वं समाप्नोषि ततोऽसि सर्वः॥","t":"namaḥ purastādatha pṛṣṭhataste\nnamo'stu te sarvata eva sarva|\nanantavīryāmitavikramastvaṃ\nsarvaṃ samāpnoṣi tato'si sarvaḥ||","e":"Honour and worship be--\nGlory and praise,--to Thee\nNamo, Namaste, cried on every side;\nCried here, above, below,\nUttered when Thou dost go,\nUttered where Thou dost come! Namo! we call;\nNamostu! God adored!\nNamostu! Nameless Lord!\nHail to Thee! Praise to Thee! Thou One in all;\nFor Thou art All! Yea, Thou!"},
{"c":11,"v":41,"d":"सखेति मत्वा प्रसभं यदुक्तं\nहे कृष्ण हे यादव हे सखेति।\nअजानता महिमानं तवेदं\nमया प्रमादात्प्रणयेन वापि॥","t":"sakheti matvā prasabhaṃ yaduktaṃ\nhe kṛṣṇa he yādava he sakheti|\najānatā mahimānaṃ tavedaṃ\nmayā pramādātpraṇayena vāpi||","e":"Ah! if in anger now\nThou shouldst remember I did think Thee Friend,\nSpeaking with easy speech,\nAs men use each to each;\nDid call Thee \"Krishna,\" \"Prince,\" nor comprehend\nThy hidden majesty,\nThe might, the awe of Thee;\nDid, in my heedlessness, or in my love,"},
{"c":11,"v":42,"d":"यच्चावहासार्थमसत्कृतोऽसि\nविहारशय्यासनभोजनेषु।\nएकोऽथवाप्यच्युत तत्समक्षं\nतत्क्षामये त्वामहमप्रमेयम्॥","t":"yaccāvahāsārthamasatkṛto'si\nvihāraśayyāsanabhojaneṣu|\neko'thavāpyacyuta tatsamakṣaṃ\ntatkṣāmaye tvāmahamaprameyam||","e":"On journey, or in jest,\nOr when we lay at rest,\nSitting at council, straying in the grove,\nAlone, or in the throng,\nDo Thee, most Holy! wrong,\nBe Thy grace granted for that witless sin!"},
{"c":11,"v":43,"d":"पितासि लोकस्य चराचरस्य\nत्वमस्य पूज्यश्च गुरुर्गरीयान्।\nन त्वत्समोऽस्त्यभ्यधिकः कुतोऽन्यो\nलोकत्रयेऽप्यप्रतिमप्रभाव॥","t":"pitāsi lokasya carācarasya\ntvamasya pūjyaśca gururgarīyān|\nna tvatsamo'styabhyadhikaḥ kuto'nyo\nlokatraye'pyapratimaprabhāva||","e":"For Thou art, now I know,\nFather of all below,\nOf all above, of all the worlds within\nGuru of Gurus; more\nTo reverence and adore\nThan all which is adorable and high!\nHow, in the wide worlds three\nShould any equal be?\nShould any other share Thy Majesty?"},
{"c":11,"v":44,"d":"तस्मात्प्रणम्य प्रणिधाय कायं\nप्रसादये त्वामहमीशमीड्यम्।\nपितेव पुत्रस्य सखेव सख्युः\nप्रियः प्रियायार्हसि देव सोढुम्॥","t":"tasmātpraṇamya praṇidhāya kāyaṃ\nprasādaye tvāmahamīśamīḍyam|\npiteva putrasya sakheva sakhyuḥ\npriyaḥ priyāyārhasi deva soḍhum||","e":"Therefore, with body bent\nAnd reverent intent,\nI praise, and serve, and seek Thee, asking grace.\nAs father to a son,\nAs friend to friend, as one\nWho loveth to his lover, turn Thy face\nIn gentleness on me!"},
{"c":11,"v":45,"d":"अदृष्टपूर्वं हृषितोऽस्मि दृष्ट्वा\nभयेन च प्रव्यथितं मनो मे।\nतदेव मे दर्शय देव रूपं\nप्रसीद देवेश जगन्निवास॥","t":"adṛṣṭapūrvaṃ hṛṣito'smi dṛṣṭvā\nbhayena ca pravyathitaṃ mano me|\ntadeva me darśaya deva rūpaṃ\nprasīda deveśa jagannivāsa||","e":"Good is it I did see\nThis unknown marvel of Thy Form! But fear\nMingles with joy! Retake,\nDear Lord! for pity's sake\nThine earthly shape, which earthly eyes may bear!"},
{"c":11,"v":46,"d":"किरीटिनं गदिनं चक्रहस्त\nमिच्छामि त्वां द्रष्टुमहं तथैव।\nतेनैव रूपेण चतुर्भुजेन\nसहस्रबाहो भव विश्वमूर्ते॥","t":"kirīṭinaṃ gadinaṃ cakrahasta\nmicchāmi tvāṃ draṣṭumahaṃ tathaiva|\ntenaiva rūpeṇa caturbhujena\nsahasrabāho bhava viśvamūrte||","e":"Be merciful, and show\nThe visage that I know;\nLet me regard Thee, as of yore, arrayed\nWith disc and forehead-gem,\nWith mace and anadem,\nThou that sustainest all things! Undismayed\nLet me once more behold\nThe form I loved of old,\nThou of the thousand arms and countless eyes!\nThis frightened heart is fain\nTo see restored again\nMy Charioteer, in Krishna's kind disguise."},
{"c":11,"v":47,"d":"श्री भगवानुवाच\nमया प्रसन्नेन तवार्जुनेदं\nरूपं परं दर्शितमात्मयोगात्।\nतेजोमयं विश्वमनन्तमाद्यं\nयन्मे त्वदन्येन न दृष्टपूर्वम्॥","t":"śrī bhagavānuvāca\nmayā prasannena tavārjunedaṃ\nrūpaṃ paraṃ darśitamātmayogāt|\ntejomayaṃ viśvamanantamādyaṃ\nyanme tvadanyena na dṛṣṭapūrvam||","e":"Krishna.\nYea! thou hast seen, Arjuna! because I loved thee well,\nThe secret countenance of Me, revealed by mystic spell,\nShining, and wonderful, and vast, majestic, manifold,\nWhich none save thou in all the years had favour to behold;"},
{"c":11,"v":48,"d":"न वेदयज्ञाध्ययनैर्न दानै\nर्न च क्रियाभिर्न तपोभिरुग्रैः।\nएवंरूपः शक्य अहं नृलोके\nद्रष्टुं त्वदन्येन कुरुप्रवीर॥","t":"na vedayajñādhyayanairna dānai\nrna ca kriyābhirna tapobhirugraiḥ|\nevaṃrūpaḥ śakya ahaṃ nṛloke\ndraṣṭuṃ tvadanyena kurupravīra||","e":"For not by Vedas cometh this, nor sacrifice, nor alms,\nNor works well-done, nor penance long, nor prayers, nor chaunted\npsalms,\nThat mortal eyes should bear to view the Immortal Soul unclad,\nPrince of the Kurus! This was kept for thee alone! Be glad!"},
{"c":11,"v":49,"d":"मा ते व्यथा मा च विमूढभावो\nदृष्ट्वा रूपं घोरमीदृङ्ममेदम्।\nव्यपेतभीः प्रीतमनाः पुनस्त्वं\nतदेव मे रूपमिदं प्रपश्य॥","t":"mā te vyathā mā ca vimūḍhabhāvo\ndṛṣṭvā rūpaṃ ghoramīdṛṅmamedam|\nvyapetabhīḥ prītamanāḥ punastvaṃ\ntadeva me rūpamidaṃ prapaśya||","e":"Let no more trouble shake thy heart, because thine eyes have seen\nMy terror with My glory. As I before have been\nSo will I be again for thee; with lightened heart behold!\nOnce more I am thy Krishna, the form thou knew'st of old!"},
{"c":11,"v":50,"d":"सञ्जय उवाच\nइत्यर्जुनं वासुदेवस्तथोक्त्वा\nस्वकं रूपं दर्शयामास भूयः।\nआश्वासयामास च भीतमेनं\nभूत्वा पुनः सौम्यवपुर्महात्मा॥","t":"sañjaya uvāca\nityarjunaṃ vāsudevastathoktvā\nsvakaṃ rūpaṃ darśayāmāsa bhūyaḥ|\nāśvāsayāmāsa ca bhītamenaṃ\nbhūtvā punaḥ saumyavapurmahātmā||","e":"Sanjaya.\nThese words to Arjuna spake\nVasudev, and straight did take\nBack again the semblance dear\nOf the well-loved charioteer;\nPeace and joy it did restore\nWhen the Prince beheld once more\nMighty BRAHMA's form and face\nClothed in Krishna's gentle grace."},
{"c":11,"v":51,"d":"अर्जुन उवाच\nदृष्ट्वेदं मानुषं रूपं तवसौम्यं जनार्दन।\nइदानीमस्मि संवृत्तः सचेताः प्रकृतिं गतः॥","t":"arjuna uvāca\ndṛṣṭvedaṃ mānuṣaṃ rūpaṃ tavasaumyaṃ janārdana|\nidānīmasmi saṃvṛttaḥ sacetāḥ prakṛtiṃ gataḥ||","e":"Arjuna.\nNow that I see come back, Janardana!\nThis friendly human frame, my mind can think\nCalm thoughts once more; my heart beats still again!"},
{"c":11,"v":52,"d":"श्री भगवानुवाच\nसुदुर्दर्शमिदं रूपं दृष्टवानसि यन्मम।\nदेवा अप्यस्य रूपस्य नित्यं दर्शनकाङ्क्षिणः॥","t":"śrī bhagavānuvāca\nsudurdarśamidaṃ rūpaṃ dṛṣṭavānasi yanmama|\ndevā apyasya rūpasya nityaṃ darśanakāṅkṣiṇaḥ||","e":"Krishna.\nYea! it was wonderful and terrible\nTo view me as thou didst, dear Prince! The gods\nDread and desire continually to view!"},
{"c":11,"v":53,"d":"नाहं वेदैर्न तपसा न दानेन न चेज्यया।\nशक्य एवंविधो द्रष्टुं दृष्टवानसि मां यथा॥","t":"nāhaṃ vedairna tapasā na dānena na cejyayā|\nśakya evaṃvidho draṣṭuṃ dṛṣṭavānasi māṃ yathā||","e":"Yet not by Vedas, nor from sacrifice,\nNor penance, nor gift-giving, nor with prayer\nShall any so behold, as thou hast seen!"},
{"c":11,"v":54,"d":"भक्त्या त्वनन्यया शक्यमहमेवंविधोऽर्जुन।\nज्ञातुं दृष्टुं च तत्त्वेन प्रवेष्टुं च परंतप॥","t":"bhaktyā tvananyayā śakyamahamevaṃvidho'rjuna|\njñātuṃ dṛṣṭuṃ ca tattvena praveṣṭuṃ ca paraṃtapa||","e":"Only by fullest service, perfect faith,\nAnd uttermost surrender am I known\nAnd seen, and entered into, Indian Prince!"},
{"c":11,"v":55,"d":"मत्कर्मकृन्मत्परमो मद्भक्तः सङ्गवर्जितः।\nनिर्वैरः सर्वभूतेषु यः स मामेति पाण्डव॥","t":"matkarmakṛnmatparamo madbhaktaḥ saṅgavarjitaḥ|\nnirvairaḥ sarvabhūteṣu yaḥ sa māmeti pāṇḍava||","e":"Who doeth all for Me; who findeth Me\nIn all; adoreth always; loveth all\nWhich I have made, and Me, for Love's sole end\nThat man, Arjuna! unto Me doth wend."},
{"c":12,"v":1,"d":"अर्जुन उवाच\nएवं सततयुक्ता ये भक्तास्त्वां पर्युपासते।\nयेचाप्यक्षरमव्यक्तं तेषां के योगवित्तमाः॥","t":"arjuna uvāca\nevaṃ satatayuktā ye bhaktāstvāṃ paryupāsate|\nyecāpyakṣaramavyaktaṃ teṣāṃ ke yogavittamāḥ||","e":"Arjuna.\nLord! of the men who serve Thee--true in heart--\nAs God revealed; and of the men who serve,\nWorshipping Thee Unrevealed, Unbodied, Far,\nWhich take the better way of faith and life?"},
{"c":12,"v":2,"d":"श्री भगवानुवाच\nमय्यावेश्य मनो ये मां नित्ययुक्ता उपासते।\nश्रद्धया परयोपेतास्ते मे युक्ततमा मताः॥","t":"śrī bhagavānuvāca\nmayyāveśya mano ye māṃ nityayuktā upāsate|\nśraddhayā parayopetāste me yuktatamā matāḥ||","e":"Krishna.\nWhoever serve Me--as I show Myself--\nConstantly true, in full devotion fixed,\nThose hold I very holy."},
{"c":12,"v":3,"d":"ये त्वक्षरमनिर्देश्यमव्यक्तं पर्युपासते।\nसर्वत्रगमचिन्त्यं च कूटस्थमचलं ध्रुवम्॥","t":"ye tvakṣaramanirdeśyamavyaktaṃ paryupāsate|\nsarvatragamacintyaṃ ca kūṭasthamacalaṃ dhruvam||","e":"But who serve--\nWorshipping Me The One, The Invisible,\nThe Unrevealed, Unnamed, Unthinkable,\nUttermost, All-pervading, Highest, Sure--"},
{"c":12,"v":4,"d":"संनियम्येन्द्रियग्रामं सर्वत्र समबुद्धयः।\nते प्राप्नुवन्ति मामेव सर्वभूतहिते रताः॥","t":"saṃniyamyendriyagrāmaṃ sarvatra samabuddhayaḥ|\nte prāpnuvanti māmeva sarvabhūtahite ratāḥ||","e":"Who thus adore Me, mastering their sense,\nOf one set mind to all, glad in all good,\nThese blessed souls come unto Me."},
{"c":12,"v":5,"d":"क्लेशोऽधिकतरस्तेषामव्यक्तासक्तचेतसाम्।\nअव्यक्ता हि गतिर्दुःखं देहवद्भिरवाप्यते॥","t":"kleśo'dhikatarasteṣāmavyaktāsaktacetasām|\navyaktā hi gatirduḥkhaṃ dehavadbhiravāpyate||","e":"Yet, hard\nThe travail is for such as bend their minds\nTo reach th' Unmanifest That viewless path\nShall scarce be trod by man bearing the flesh!"},
{"c":12,"v":6,"d":"ये तु सर्वाणि कर्माणि मयि संन्यस्य मत्पराः।\nअनन्येनैव योगेन मां ध्यायन्त उपासते॥","t":"ye tu sarvāṇi karmāṇi mayi saṃnyasya matparāḥ|\nananyenaiva yogena māṃ dhyāyanta upāsate||","e":"But whereso any doeth all his deeds\nRenouncing self for Me, full of Me, fixed\nTo serve only the Highest, night and day\nMusing on Me--"},
{"c":12,"v":7,"d":"तेषामहं समुद्धर्ता मृत्युसंसारसागरात्।\nभवामि नचिरात्पार्थ मय्यावेशितचेतसाम्॥","t":"teṣāmahaṃ samuddhartā mṛtyusaṃsārasāgarāt|\nbhavāmi nacirātpārtha mayyāveśitacetasām||","e":"him will I swiftly lift\nForth from life's ocean of distress and death,\nWhose soul clings fast to Me."},
{"c":12,"v":8,"d":"मय्येव मन आधत्स्व मयि बुद्धिं निवेशय।\nनिवसिष्यसि मय्येव अत ऊर्ध्वं न संशयः॥","t":"mayyeva mana ādhatsva mayi buddhiṃ niveśaya|\nnivasiṣyasi mayyeva ata ūrdhvaṃ na saṃśayaḥ||","e":"Cling thou to Me!\nClasp Me with heart and mind! so shalt thou dwell\nSurely with Me on high."},
{"c":12,"v":9,"d":"अथ चित्तं समाधातुं न शक्नोषि मयि स्थिरम्।\nअभ्यासयोगेन ततो मामिच्छाप्तुं धनञ्जय॥","t":"atha cittaṃ samādhātuṃ na śaknoṣi mayi sthiram|\nabhyāsayogena tato māmicchāptuṃ dhanañjaya||","e":"But if thy thought\nDroops from such height; if thou be'st weak to set\nBody and soul upon Me constantly,\nDespair not! give Me lower service! seek\nTo reach Me, worshipping with steadfast will;"},
{"c":12,"v":10,"d":"अभ्यासेऽप्यसमर्थोऽसि मत्कर्मपरमो भव।\nमदर्थमपि कर्माणि कुर्वन् सिद्धिमवाप्स्यसि॥","t":"abhyāse'pyasamartho'si matkarmaparamo bhava|\nmadarthamapi karmāṇi kurvan siddhimavāpsyasi||","e":"And, if thou canst not worship steadfastly,\nWork for Me, toil in works pleasing to Me!\nFor he that laboureth right for love of Me\nShall finally attain!"},
{"c":12,"v":11,"d":"अथैतदप्यशक्तोऽसि कर्तुं मद्योगमाश्रितः।\nसर्वकर्मफलत्यागं ततः कुरु यतात्मवान्॥","t":"athaitadapyaśakto'si kartuṃ madyogamāśritaḥ|\nsarvakarmaphalatyāgaṃ tataḥ kuru yatātmavān||","e":"But, if in this\nThy faint heart fails, bring Me thy failure! find\nRefuge in Me! let fruits of labour go,\nRenouncing hope for Me, with lowliest heart,\nSo shalt thou come;"},
{"c":12,"v":12,"d":"श्रेयो हि ज्ञानमभ्यासाज्ज्ञानाद्ध्यानं विशिष्यते।\nध्यानात्कर्मफलत्यागस्त्यागाच्छान्तिरनन्तरम्॥","t":"śreyo hi jñānamabhyāsājjñānāddhyānaṃ viśiṣyate|\ndhyānātkarmaphalatyāgastyāgācchāntiranantaram||","e":"for, though to know is more\nThan diligence, yet worship better is\nThan knowing, and renouncing better still.\nNear to renunciation--very near--\nDwelleth Eternal Peace!"},
{"c":12,"v":13,"d":"अद्वेष्टा सर्वभूतानां मैत्रः करुण एव च।\nनिर्ममो निरहङ्कारः समदुःखसुखः क्षमी॥","t":"adveṣṭā sarvabhūtānāṃ maitraḥ karuṇa eva ca|\nnirmamo nirahaṅkāraḥ samaduḥkhasukhaḥ kṣamī||","e":"Who hateth nought\nOf all which lives, living himself benign,\nCompassionate, from arrogance exempt,\nExempt from love of self, unchangeable\nBy good or ill; patient,"},
{"c":12,"v":14,"d":"सन्तुष्टः सततं योगी यतात्मा दृढनिश्चयः।\nमय्यर्पितमनोबुद्धिर्यो मद्भक्तः स मे प्रियः॥","t":"santuṣṭaḥ satataṃ yogī yatātmā dṛḍhaniścayaḥ|\nmayyarpitamanobuddhiryo madbhaktaḥ sa me priyaḥ||","e":"contented, firm\nIn faith, mastering himself, true to his word,\nSeeking Me, heart and soul; vowed unto Me,--\nThat man I love!"},
{"c":12,"v":15,"d":"यस्मान्नोद्विजते लोको लोकान्नोद्विजते च यः।\nहर्षामर्षभयोद्वेगैर्मुक्तो यः स च मे प्रियः॥","t":"yasmānnodvijate loko lokānnodvijate ca yaḥ|\nharṣāmarṣabhayodvegairmukto yaḥ sa ca me priyaḥ||","e":"Who troubleth not his kind,\nAnd is not troubled by them; clear of wrath,\nLiving too high for gladness, grief, or fear,\nThat man I love!"},
{"c":12,"v":16,"d":"अनपेक्षः शुचिर्दक्ष उदासीनो गतव्यथः।\nसर्वारम्भपरित्यागी यो मद्भक्तः स मे प्रियः॥","t":"anapekṣaḥ śucirdakṣa udāsīno gatavyathaḥ|\nsarvārambhaparityāgī yo madbhaktaḥ sa me priyaḥ||","e":"Who, dwelling quiet-eyed,\nStainless, serene, well-balanced, unperplexed,\nWorking with Me, yet from all works detached,\nThat man I love!"},
{"c":12,"v":17,"d":"यो न हृष्यति न द्वेष्टि न शोचति न काङ्क्षति।\nशुभाशुभपरित्यागी भक्ितमान्यः स मे प्रियः॥","t":"yo na hṛṣyati na dveṣṭi na śocati na kāṅkṣati|\nśubhāśubhaparityāgī bhaktamānyaḥ sa me priyaḥ||","e":"Who, fixed in faith on Me,\nDotes upon none, scorns none; rejoices not,\nAnd grieves not, letting good or evil hap\nLight when it will, and when it will depart,\nThat man I love!"},
{"c":12,"v":18,"d":"समः शत्रौ च मित्रे च तथा मानापमानयोः।\nशीतोष्णसुखदुःखेषु समः सङ्गविवर्जितः॥","t":"samaḥ śatrau ca mitre ca tathā mānāpamānayoḥ|\nśītoṣṇasukhaduḥkheṣu samaḥ saṅgavivarjitaḥ||","e":"Who, unto friend and foe\nKeeping an equal heart, with equal mind\nBears shame and glory; with an equal peace\nTakes heat and cold, pleasure and pain; abides\nQuit of desires,"},
{"c":12,"v":19,"d":"तुल्यनिन्दास्तुतिर्मौनी सन्तुष्टो येनकेनचित्।\nअनिकेतः स्थिरमतिर्भक्ितमान्मे प्रियो नरः॥","t":"tulyanindāstutirmaunī santuṣṭo yenakenacit|\naniketaḥ sthiramatirbhaktamānme priyo naraḥ||","e":"hears praise or calumny\nIn passionless restraint, unmoved by each;\nLinked by no ties to earth, steadfast in Me,\nThat man I love!"},
{"c":12,"v":20,"d":"ये तु धर्म्यामृतमिदं यथोक्तं पर्युपासते।\nश्रद्दधाना मत्परमा भक्तास्तेऽतीव मे प्रियाः॥","t":"ye tu dharmyāmṛtamidaṃ yathoktaṃ paryupāsate|\nśraddadhānā matparamā bhaktāste'tīva me priyāḥ||","e":"But most of all I love\nThose happy ones to whom 'tis life to live\nIn single fervid faith and love unseeing,\nDrinking the blessed Amrit of my Being!"},
{"c":13,"v":1,"d":"श्री भगवानुवाच\nइदं शरीरं कौन्तेय क्षेत्रमित्यभिधीयते।\nएतद्यो वेत्ति तं प्राहुः क्षेत्रज्ञ इति तद्विदः॥","t":"śrī bhagavānuvāca\nidaṃ śarīraṃ kaunteya kṣetramityabhidhīyate|\netadyo vetti taṃ prāhuḥ kṣetrajña iti tadvidaḥ||","e":"Krishna.\nYea! Son of Kunti! for this flesh ye see\nIs Kshetra, is the field where Life disports;\nAnd that which views and knows it is the Soul,\nKshetrajna."},
{"c":13,"v":2,"d":"क्षेत्रज्ञं चापि मां विद्धि सर्वक्षेत्रेषु भारत।\nक्षेत्रक्षेत्रज्ञयोर्ज्ञानं यत्तज्ज्ञानं मतं मम॥","t":"kṣetrajñaṃ cāpi māṃ viddhi sarvakṣetreṣu bhārata|\nkṣetrakṣetrajñayorjñānaṃ yattajjñānaṃ mataṃ mama||","e":"In all \"fields,\" thou Indian prince!\nI am Kshetrajna. I am what surveys!\nOnly that knowledge knows which knows the known\nBy the knower!"},
{"c":13,"v":3,"d":"तत्क्षेत्रं यच्च यादृक् च यद्विकारि यतश्च यत्।\nस च यो यत्प्रभावश्च तत्समासेन मे श्रृणु॥","t":"tatkṣetraṃ yacca yādṛk ca yadvikāri yataśca yat|\nsa ca yo yatprabhāvaśca tatsamāsena me śrṛṇu||","e":"What it is, that \"field\" of life,\nWhat qualities it hath, and whence it is,\nAnd why it changeth, and the faculty\nThat wotteth it, the mightiness of this,\nAnd how it wotteth-hear these things from Me!"},
{"c":13,"v":4,"d":"ऋषिभिर्बहुधा गीतं छन्दोभिर्विविधैः पृथक्।\nब्रह्मसूत्रपदैश्चैव हेतुमद्भिर्विनिश्िचतैः॥","t":"ṛṣibhirbahudhā gītaṃ chandobhirvividhaiḥ pṛthak|\nbrahmasūtrapadaiścaiva hetumadbhirviniścataiḥ||","e":""},
{"c":13,"v":5,"d":"महाभूतान्यहङ्कारो बुद्धिरव्यक्तमेव च।\nइन्द्रियाणि दशैकं च पञ्च चेन्द्रियगोचराः॥","t":"mahābhūtānyahaṅkāro buddhiravyaktameva ca|\nindriyāṇi daśaikaṃ ca pañca cendriyagocarāḥ||","e":"The elements, the conscious life, the mind,\nThe unseen vital force, the nine strange gates\nOf the body, and the five domains of sense;"},
{"c":13,"v":6,"d":"इच्छा द्वेषः सुखं दुःखं सङ्घातश्चेतनाधृतिः।\nएतत्क्षेत्रं समासेन सविकारमुदाहृतम्॥","t":"icchā dveṣaḥ sukhaṃ duḥkhaṃ saṅghātaścetanādhṛtiḥ|\netatkṣetraṃ samāsena savikāramudāhṛtam||","e":"Desire, dislike, pleasure and pain, and thought\nDeep-woven, and persistency of being;\nThese all are wrought on Matter by the Soul!"},
{"c":13,"v":7,"d":"अमानित्वमदम्भित्वमहिंसा क्षान्तिरार्जवम्।\nआचार्योपासनं शौचं स्थैर्यमात्मविनिग्रहः॥","t":"amānitvamadambhitvamahiṃsā kṣāntirārjavam|\nācāryopāsanaṃ śaucaṃ sthairyamātmavinigrahaḥ||","e":"Humbleness, truthfulness, and harmlessness,\nPatience and honour, reverence for the wise.\nPurity, constancy, control of self,"},
{"c":13,"v":8,"d":"इन्द्रियार्थेषु वैराग्यमनहङ्कार एव च।\nजन्ममृत्युजराव्याधिदुःखदोषानुदर्शनम्॥","t":"indriyārtheṣu vairāgyamanahaṅkāra eva ca|\njanmamṛtyujarāvyādhiduḥkhadoṣānudarśanam||","e":"Contempt of sense-delights, self-sacrifice,\nPerception of the certitude of ill\nIn birth, death, age, disease, suffering, and sin;"},
{"c":13,"v":9,"d":"असक्ितरनभिष्वङ्गः पुत्रदारगृहादिषु।\nनित्यं च समचित्तत्वमिष्टानिष्टोपपत्तिषु॥","t":"asaktaranabhiṣvaṅgaḥ putradāragṛhādiṣu|\nnityaṃ ca samacittatvamiṣṭāniṣṭopapattiṣu||","e":"Detachment, lightly holding unto home,\nChildren, and wife, and all that bindeth men;\nAn ever-tranquil heart in fortunes good\nAnd fortunes evil,"},
{"c":13,"v":10,"d":"मयि चानन्ययोगेन भक्ितरव्यभिचारिणी।\nविविक्तदेशसेवित्वमरतिर्जनसंसदि॥","t":"mayi cānanyayogena bhaktaravyabhicāriṇī|\nviviktadeśasevitvamaratirjanasaṃsadi||","e":"with a will set firm\nTo worship Me--Me only! ceasing not;\nLoving all solitudes, and shunning noise\nOf foolish crowds;"},
{"c":13,"v":11,"d":"अध्यात्मज्ञाननित्यत्वं तत्त्वज्ञानार्थदर्शनम्।\nएतज्ज्ञानमिति प्रोक्तमज्ञानं यदतोन्यथा॥","t":"adhyātmajñānanityatvaṃ tattvajñānārthadarśanam|\netajjñānamiti proktamajñānaṃ yadatonyathā||","e":"endeavours resolute\nTo reach perception of the Utmost Soul,\nAnd grace to understand what gain it were\nSo to attain,--this is true Wisdom, Prince!\nAnd what is otherwise is ignorance!"},
{"c":13,"v":12,"d":"ज्ञेयं यत्तत्प्रवक्ष्यामि यज्ज्ञात्वाऽमृतमश्नुते।\nअनादिमत्परं ब्रह्म न सत्तन्नासदुच्यते॥","t":"jñeyaṃ yattatpravakṣyāmi yajjñātvā'mṛtamaśnute|\nanādimatparaṃ brahma na sattannāsaducyate||","e":"Now will I speak of knowledge best to know-\nThat Truth which giveth man Amrit to drink,\nThe Truth of HIM, the Para-Brahm, the All,\nThe Uncreated;; not Asat, not Sat,\nNot Form, nor the Unformed; yet both, and more;--"},
{"c":13,"v":13,"d":"सर्वतः पाणिपादं तत्सर्वतोऽक्षिशिरोमुखम्।\nसर्वतः श्रुतिमल्लोके सर्वमावृत्य तिष्ठति॥","t":"sarvataḥ pāṇipādaṃ tatsarvato'kṣiśiromukham|\nsarvataḥ śrutimalloke sarvamāvṛtya tiṣṭhati||","e":"Whose hands are everywhere, and everywhere\nPlanted His feet, and everywhere His eyes\nBeholding, and His ears in every place\nHearing, and all His faces everywhere\nEnlightening and encompassing His worlds."},
{"c":13,"v":14,"d":"सर्वेन्द्रियगुणाभासं सर्वेन्द्रियविवर्जितम्।\nअसक्तं सर्वभृच्चैव निर्गुणं गुणभोक्तृ च॥","t":"sarvendriyaguṇābhāsaṃ sarvendriyavivarjitam|\nasaktaṃ sarvabhṛccaiva nirguṇaṃ guṇabhoktṛ ca||","e":"Glorified in the senses He hath given,\nYet beyond sense He is; sustaining all,\nYet dwells He unattached: of forms and modes\nMaster, yet neither form nor mode hath He;"},
{"c":13,"v":15,"d":"बहिरन्तश्च भूतानामचरं चरमेव च।\nसूक्ष्मत्वात्तदविज्ञेयं दूरस्थं चान्तिके च तत्॥","t":"bahirantaśca bhūtānāmacaraṃ carameva ca|\nsūkṣmatvāttadavijñeyaṃ dūrasthaṃ cāntike ca tat||","e":"He is within all beings--and without--\nMotionless, yet still moving; not discerned\nFor subtlety of instant presence; close\nTo all, to each; yet measurelessly far!"},
{"c":13,"v":16,"d":"अविभक्तं च भूतेषु विभक्तमिव च स्थितम्।\nभूतभर्तृ च तज्ज्ञेयं ग्रसिष्णु प्रभविष्णु च॥","t":"avibhaktaṃ ca bhūteṣu vibhaktamiva ca sthitam|\nbhūtabhartṛ ca tajjñeyaṃ grasiṣṇu prabhaviṣṇu ca||","e":"Not manifold, and yet subsisting still\nIn all which lives; for ever to be known\nAs the Sustainer, yet, at the End of Times,\nHe maketh all to end--and re-creates."},
{"c":13,"v":17,"d":"ज्योतिषामपि तज्ज्योतिस्तमसः परमुच्यते।\nज्ञानं ज्ञेयं ज्ञानगम्यं हृदि सर्वस्य विष्ठितम्॥","t":"jyotiṣāmapi tajjyotistamasaḥ paramucyate|\njñānaṃ jñeyaṃ jñānagamyaṃ hṛdi sarvasya viṣṭhitam||","e":"The Light of Lights He is, in the heart of the Dark\nShining eternally. Wisdom He is\nAnd Wisdom's way, and Guide of all the wise,\nPlanted in every heart."},
{"c":13,"v":18,"d":"इति क्षेत्रं तथा ज्ञानं ज्ञेयं चोक्तं समासतः।\nमद्भक्त एतद्विज्ञाय मद्भावायोपपद्यते॥","t":"iti kṣetraṃ tathā jñānaṃ jñeyaṃ coktaṃ samāsataḥ|\nmadbhakta etadvijñāya madbhāvāyopapadyate||","e":"So have I told\nOf Life's stuff, and the moulding, and the lore\nTo comprehend. Whoso, adoring Me,\nPerceiveth this, shall surely come to Me!"},
{"c":13,"v":19,"d":"प्रकृतिं पुरुषं चैव विद्ध्यनादी उभावपि।\nविकारांश्च गुणांश्चैव विद्धि प्रकृतिसंभवान्॥","t":"prakṛtiṃ puruṣaṃ caiva viddhyanādī ubhāvapi|\nvikārāṃśca guṇāṃścaiva viddhi prakṛtisaṃbhavān||","e":"Know thou that Nature and the Spirit both\nHave no beginning! Know that qualities\nAnd changes of them are by Nature wrought;"},
{"c":13,"v":20,"d":"कार्यकारणकर्तृत्वे हेतुः प्रकृतिरुच्यते।\nपुरुषः सुखदुःखानां भोक्तृत्वे हेतुरुच्यते॥","t":"kāryakāraṇakartṛtve hetuḥ prakṛtirucyate|\npuruṣaḥ sukhaduḥkhānāṃ bhoktṛtve heturucyate||","e":"That Nature puts to work the acting frame,\nBut Spirit doth inform it, and so cause\nFeeling of pain and pleasure."},
{"c":13,"v":21,"d":"पुरुषः प्रकृतिस्थो हि भुङ्क्ते प्रकृतिजान्गुणान्।\nकारणं गुणसङ्गोऽस्य सदसद्योनिजन्मसु॥","t":"puruṣaḥ prakṛtistho hi bhuṅkte prakṛtijānguṇān|\nkāraṇaṃ guṇasaṅgo'sya sadasadyonijanmasu||","e":"Spirit, linked\nTo moulded matter, entereth into bond\nWith qualities by Nature framed, and, thus\nMarried to matter, breeds the birth again\nIn good or evil yonis."},
{"c":13,"v":22,"d":"उपद्रष्टाऽनुमन्ता च भर्ता भोक्ता महेश्वरः।\nपरमात्मेति चाप्युक्तो देहेऽस्मिन्पुरुषः परः॥","t":"upadraṣṭā'numantā ca bhartā bhoktā maheśvaraḥ|\nparamātmeti cāpyukto dehe'sminpuruṣaḥ paraḥ||","e":"Yet is this\nYea! in its bodily prison!--Spirit pure,\nSpirit supreme; surveying, governing,\nGuarding, possessing; Lord and Master still\nPURUSHA, Ultimate, One Soul with Me."},
{"c":13,"v":23,"d":"य एवं वेत्ति पुरुषं प्रकृतिं च गुणैःसह।\nसर्वथा वर्तमानोऽपि न स भूयोऽभिजायते॥","t":"ya evaṃ vetti puruṣaṃ prakṛtiṃ ca guṇaiḥsaha|\nsarvathā vartamāno'pi na sa bhūyo'bhijāyate||","e":"Whoso thus knows himself, and knows his soul\nPURUSHA, working through the qualities\nWith Nature's modes, the light hath come for him!\nWhatever flesh he bears, never again\nShall he take on its load."},
{"c":13,"v":24,"d":"ध्यानेनात्मनि पश्यन्ति केचिदात्मानमात्मना।\nअन्ये सांख्येन योगेन कर्मयोगेन चापरे॥","t":"dhyānenātmani paśyanti kecidātmānamātmanā|\nanye sāṃkhyena yogena karmayogena cāpare||","e":"Some few there be\nBy meditation find the Soul in Self\nSelf-schooled; and some by long philosophy\nAnd holy life reach thither; some by works:"},
{"c":13,"v":25,"d":"अन्ये त्वेवमजानन्तः श्रुत्वाऽन्येभ्य उपासते।\nतेऽपि चातितरन्त्येव मृत्युं श्रुतिपरायणाः॥","t":"anye tvevamajānantaḥ śrutvā'nyebhya upāsate|\nte'pi cātitarantyeva mṛtyuṃ śrutiparāyaṇāḥ||","e":"Some, never so attaining, hear of light\nFrom other lips, and seize, and cleave to it\nWorshipping; yea! and those--to teaching true--\nOverpass Death!"},
{"c":13,"v":26,"d":"यावत्सञ्जायते किञ्चित्सत्त्वं स्थावरजङ्गमम्।\nक्षेत्रक्षेत्रज्ञसंयोगात्तद्विद्धि भरतर्षभ॥","t":"yāvatsañjāyate kiñcitsattvaṃ sthāvarajaṅgamam|\nkṣetrakṣetrajñasaṃyogāttadviddhi bharatarṣabha||","e":"Wherever, Indian Prince!\nLife is--of moving things, or things unmoved,\nPlant or still seed--know, what is there hath grown\nBy bond of Matter and of Spirit:"},
{"c":13,"v":27,"d":"समं सर्वेषु भूतेषु तिष्ठन्तं परमेश्वरम्।\nविनश्यत्स्वविनश्यन्तं यः पश्यति स पश्यति॥","t":"samaṃ sarveṣu bhūteṣu tiṣṭhantaṃ parameśvaram|\nvinaśyatsvavinaśyantaṃ yaḥ paśyati sa paśyati||","e":"Know\nHe sees indeed who sees in all alike\nThe living, lordly Soul; the Soul Supreme,\nImperishable amid the Perishing:"},
{"c":13,"v":28,"d":"समं पश्यन्हि सर्वत्र समवस्थितमीश्वरम्।\nन हिनस्त्यात्मनाऽऽत्मानं ततो याति परां गतिम्॥","t":"samaṃ paśyanhi sarvatra samavasthitamīśvaram|\nna hinastyātmanā''tmānaṃ tato yāti parāṃ gatim||","e":"For, whoso thus beholds, in every place,\nIn every form, the same, one, Living Life,\nDoth no more wrongfulness unto himself,\nBut goes the highest road which brings to bliss."},
{"c":13,"v":29,"d":"प्रकृत्यैव च कर्माणि क्रियमाणानि सर्वशः।\nयः पश्यति तथाऽऽत्मानमकर्तारं स पश्यति॥","t":"prakṛtyaiva ca karmāṇi kriyamāṇāni sarvaśaḥ|\nyaḥ paśyati tathā''tmānamakartāraṃ sa paśyati||","e":"Seeing, he sees, indeed, who sees that works\nAre Nature's wont, for Soul to practise by\nActing, yet not the agent;"},
{"c":13,"v":30,"d":"यदा भूतपृथग्भावमेकस्थमनुपश्यति।\nतत एव च विस्तारं ब्रह्म सम्पद्यते तदा॥","t":"yadā bhūtapṛthagbhāvamekasthamanupaśyati|\ntata eva ca vistāraṃ brahma sampadyate tadā||","e":"sees the mass\nOf separate living things--each of its kind--\nIssue from One, and blend again to One:\nThen hath he BRAHMA, he attains!"},
{"c":13,"v":31,"d":"अनादित्वान्निर्गुणत्वात्परमात्मायमव्ययः।\nशरीरस्थोऽपि कौन्तेय न करोति न लिप्यते॥","t":"anāditvānnirguṇatvātparamātmāyamavyayaḥ|\nśarīrastho'pi kaunteya na karoti na lipyate||","e":"O Prince!\nThat Ultimate, High Spirit, Uncreate,\nUnqualified, even when it entereth flesh\nTaketh no stain of acts, worketh in nought!"},
{"c":13,"v":32,"d":"यथा सर्वगतं सौक्ष्म्यादाकाशं नोपलिप्यते।\nसर्वत्रावस्थितो देहे तथाऽऽत्मा नोपलिप्यते॥","t":"yathā sarvagataṃ saukṣmyādākāśaṃ nopalipyate|\nsarvatrāvasthito dehe tathā''tmā nopalipyate||","e":"Like to the ethereal air, pervading all,\nWhich, for sheer subtlety, avoideth taint,\nThe subtle Soul sits everywhere, unstained:"},
{"c":13,"v":33,"d":"यथा प्रकाशयत्येकः कृत्स्नं लोकमिमं रविः।\nक्षेत्रं क्षेत्री तथा कृत्स्नं प्रकाशयति भारत॥","t":"yathā prakāśayatyekaḥ kṛtsnaṃ lokamimaṃ raviḥ|\nkṣetraṃ kṣetrī tathā kṛtsnaṃ prakāśayati bhārata||","e":"Like to the light of the all-piercing sun\n[Which is not changed by aught it shines upon,]\nThe Soul's light shineth pure in every place;"},
{"c":13,"v":34,"d":"क्षेत्रक्षेत्रज्ञयोरेवमन्तरं ज्ञानचक्षुषा।\nभूतप्रकृतिमोक्षं च ये विदुर्यान्ति ते परम्॥","t":"kṣetrakṣetrajñayorevamantaraṃ jñānacakṣuṣā|\nbhūtaprakṛtimokṣaṃ ca ye viduryānti te param||","e":"And they who, by such eye of wisdom, see\nHow Matter, and what deals with it, divide;\nAnd how the Spirit and the flesh have strife,\nThose wise ones go the way which leads to Life!"},
{"c":14,"v":1,"d":"श्री भगवानुवाच\nपरं भूयः प्रवक्ष्यामि ज्ञानानां ज्ञानमुत्तमम्।\nयज्ज्ञात्वा मुनयः सर्वे परां सिद्धिमितो गताः॥","t":"śrī bhagavānuvāca\nparaṃ bhūyaḥ pravakṣyāmi jñānānāṃ jñānamuttamam|\nyajjñātvā munayaḥ sarve parāṃ siddhimito gatāḥ||","e":"Krishna.\nYet farther will I open unto thee\nThis wisdom of all wisdoms, uttermost,\nThe which possessing, all My saints have passed\nTo perfectness."},
{"c":14,"v":2,"d":"इदं ज्ञानमुपाश्रित्य मम साधर्म्यमागताः।\nसर्गेऽपि नोपजायन्ते प्रलये न व्यथन्ति च॥","t":"idaṃ jñānamupāśritya mama sādharmyamāgatāḥ|\nsarge'pi nopajāyante pralaye na vyathanti ca||","e":"On such high verities\nReliant, rising into fellowship\nWith Me, they are not born again at birth\nOf Kalpas, nor at Pralyas suffer change!"},
{"c":14,"v":3,"d":"मम योनिर्महद्ब्रह्म तस्मिन् गर्भं दधाम्यहम्।\nसंभवः सर्वभूतानां ततो भवति भारत॥","t":"mama yonirmahadbrahma tasmin garbhaṃ dadhāmyaham|\nsaṃbhavaḥ sarvabhūtānāṃ tato bhavati bhārata||","e":"This Universe the womb is where I plant\nSeed of all lives! Thence, Prince of India, comes\nBirth to all beings!"},
{"c":14,"v":4,"d":"सर्वयोनिषु कौन्तेय मूर्तयः सम्भवन्ति याः।\nतासां ब्रह्म महद्योनिरहं बीजप्रदः पिता॥","t":"sarvayoniṣu kaunteya mūrtayaḥ sambhavanti yāḥ|\ntāsāṃ brahma mahadyonirahaṃ bījapradaḥ pitā||","e":"Whoso, Kunti's Son!\nMothers each mortal form, Brahma conceives,\nAnd I am He that fathers, sending seed!"},
{"c":14,"v":5,"d":"सत्त्वं रजस्तम इति गुणाः प्रकृतिसंभवाः।\nनिबध्नन्ति महाबाहो देहे देहिनमव्ययम्॥","t":"sattvaṃ rajastama iti guṇāḥ prakṛtisaṃbhavāḥ|\nnibadhnanti mahābāho dehe dehinamavyayam||","e":"Sattwan, Rajas, and Tamas, so are named\nThe qualities of Nature, \"Soothfastness,\"\n\"Passion,\" and \"Ignorance.\" These three bind down\nThe changeless Spirit in the changeful flesh."},
{"c":14,"v":6,"d":"तत्र सत्त्वं निर्मलत्वात्प्रकाशकमनामयम्।\nसुखसङ्गेन बध्नाति ज्ञानसङ्गेन चानघ॥","t":"tatra sattvaṃ nirmalatvātprakāśakamanāmayam|\nsukhasaṅgena badhnāti jñānasaṅgena cānagha||","e":"Whereof sweet \"Soothfastness,\" by purity\nLiving unsullied and enlightened, binds\nThe sinless Soul to happiness and truth;"},
{"c":14,"v":7,"d":"रजो रागात्मकं विद्धि तृष्णासङ्गसमुद्भवम्।\nतन्निबध्नाति कौन्तेय कर्मसङ्गेन देहिनम्॥","t":"rajo rāgātmakaṃ viddhi tṛṣṇāsaṅgasamudbhavam|\ntannibadhnāti kaunteya karmasaṅgena dehinam||","e":"And Passion, being kin to appetite,\nAnd breeding impulse and propensity,\nBinds the embodied Soul, O Kunti's Son!\nBy tie of works."},
{"c":14,"v":8,"d":"तमस्त्वज्ञानजं विद्धि मोहनं सर्वदेहिनाम्।\nप्रमादालस्यनिद्राभिस्तन्निबध्नाति भारत॥","t":"tamastvajñānajaṃ viddhi mohanaṃ sarvadehinām|\npramādālasyanidrābhistannibadhnāti bhārata||","e":"But Ignorance, begot\nOf Darkness, blinding mortal men, binds down\nTheir souls to stupor, sloth, and drowsiness."},
{"c":14,"v":9,"d":"सत्त्वं सुखे सञ्जयति रजः कर्मणि भारत।\nज्ञानमावृत्य तु तमः प्रमादे सञ्जयत्युत॥","t":"sattvaṃ sukhe sañjayati rajaḥ karmaṇi bhārata|\njñānamāvṛtya tu tamaḥ pramāde sañjayatyuta||","e":"Yea, Prince of India! Soothfastness binds souls\nIn pleasant wise to flesh; and Passion binds\nBy toilsome strain; but Ignorance, which blots\nThe beams of wisdom, binds the soul to sloth."},
{"c":14,"v":10,"d":"रजस्तमश्चाभिभूय सत्त्वं भवति भारत।\nरजः सत्त्वं तमश्चैव तमः सत्त्वं रजस्तथा॥","t":"rajastamaścābhibhūya sattvaṃ bhavati bhārata|\nrajaḥ sattvaṃ tamaścaiva tamaḥ sattvaṃ rajastathā||","e":"Passion and Ignorance, once overcome,\nLeave Soothfastness, O Bharata! Where this\nWith Ignorance are absent, Passion rules;\nAnd Ignorance in hearts not good nor quick."},
{"c":14,"v":11,"d":"सर्वद्वारेषु देहेऽस्मिन्प्रकाश उपजायते।\nज्ञानं यदा तदा विद्याद्विवृद्धं सत्त्वमित्युत॥","t":"sarvadvāreṣu dehe'sminprakāśa upajāyate|\njñānaṃ yadā tadā vidyādvivṛddhaṃ sattvamityuta||","e":"When at all gateways of the Body shines\nThe Lamp of Knowledge, then may one see well\nSoothfastness settled in that city reigns;"},
{"c":14,"v":12,"d":"लोभः प्रवृत्तिरारम्भः कर्मणामशमः स्पृहा।\nरजस्येतानि जायन्ते विवृद्धे भरतर्षभ॥","t":"lobhaḥ pravṛttirārambhaḥ karmaṇāmaśamaḥ spṛhā|\nrajasyetāni jāyante vivṛddhe bharatarṣabha||","e":"Where longing is, and ardour, and unrest,\nImpulse to strive and gain, and avarice,\nThose spring from Passion--Prince!--engrained;"},
{"c":14,"v":13,"d":"अप्रकाशोऽप्रवृत्तिश्च प्रमादो मोह एव च।\nतमस्येतानि जायन्ते विवृद्धे कुरुनन्दन॥","t":"aprakāśo'pravṛttiśca pramādo moha eva ca|\ntamasyetāni jāyante vivṛddhe kurunandana||","e":"and where\nDarkness and dulness, sloth and stupor are,\n'Tis Ignorance hath caused them, Kuru Chief!"},
{"c":14,"v":14,"d":"यदा सत्त्वे प्रवृद्धे तु प्रलयं याति देहभृत्।\nतदोत्तमविदां लोकानमलान्प्रतिपद्यते॥","t":"yadā sattve pravṛddhe tu pralayaṃ yāti dehabhṛt|\ntadottamavidāṃ lokānamalānpratipadyate||","e":"Moreover, when a soul departeth, fixed\nIn Soothfastness, it goeth to the place--\nPerfect and pure--of those that know all Truth."},
{"c":14,"v":15,"d":"रजसि प्रलयं गत्वा कर्मसङ्गिषु जायते।\nतथा प्रलीनस्तमसि मूढयोनिषु जायते॥","t":"rajasi pralayaṃ gatvā karmasaṅgiṣu jāyate|\ntathā pralīnastamasi mūḍhayoniṣu jāyate||","e":"If it departeth in set habitude\nOf Impulse, it shall pass into the world\nOf spirits tied to works; and, if it dies\nIn hardened Ignorance, that blinded soul\nIs born anew in some unlighted womb."},
{"c":14,"v":16,"d":"कर्मणः सुकृतस्याहुः सात्त्विकं निर्मलं फलम्।\nरजसस्तु फलं दुःखमज्ञानं तमसः फलम्॥","t":"karmaṇaḥ sukṛtasyāhuḥ sāttvikaṃ nirmalaṃ phalam|\nrajasastu phalaṃ duḥkhamajñānaṃ tamasaḥ phalam||","e":"The fruit of Soothfastness is true and sweet;\nThe fruit of lusts is pain and toil; the fruit\nOf Ignorance is deeper darkness. Yea!"},
{"c":14,"v":17,"d":"सत्त्वात्सञ्जायते ज्ञानं रजसो लोभ एव च।\nप्रमादमोहौ तमसो भवतोऽज्ञानमेव च॥","t":"sattvātsañjāyate jñānaṃ rajaso lobha eva ca|\npramādamohau tamaso bhavato'jñānameva ca||","e":"For Light brings light, and Passion ache to have;\nAnd gloom, bewilderments, and ignorance\nGrow forth from Ignorance."},
{"c":14,"v":18,"d":"ऊर्ध्वं गच्छन्ति सत्त्वस्था मध्ये तिष्ठन्ति राजसाः।\nजघन्यगुणवृत्तिस्था अधो गच्छन्ति तामसाः॥","t":"ūrdhvaṃ gacchanti sattvasthā madhye tiṣṭhanti rājasāḥ|\njaghanyaguṇavṛttisthā adho gacchanti tāmasāḥ||","e":"Those of the first\nRise ever higher; those of the second mode\nTake a mid place; the darkened souls sink back\nTo lower deeps, loaded with witlessness!"},
{"c":14,"v":19,"d":"नान्यं गुणेभ्यः कर्तारं यदा द्रष्टानुपश्यति।\nगुणेभ्यश्च परं वेत्ति मद्भावं सोऽधिगच्छति॥","t":"nānyaṃ guṇebhyaḥ kartāraṃ yadā draṣṭānupaśyati|\nguṇebhyaśca paraṃ vetti madbhāvaṃ so'dhigacchati||","e":"When, watching life, the living man perceives\nThe only actors are the Qualities,\nAnd knows what rules beyond the Qualities,\nThen is he come nigh unto Me!"},
{"c":14,"v":20,"d":"गुणानेतानतीत्य त्रीन्देही देहसमुद्भवान्।\nजन्ममृत्युजरादुःखैर्विमुक्तोऽमृतमश्नुते॥","t":"guṇānetānatītya trīndehī dehasamudbhavān|\njanmamṛtyujarāduḥkhairvimukto'mṛtamaśnute||","e":"The Soul,\nThus passing forth from the Three Qualities--\nWhereby arise all bodies--overcomes\nBirth, Death, Sorrow, and Age; and drinketh deep\nThe undying wine of Amrit."},
{"c":14,"v":21,"d":"अर्जुन उवाच\nकैर्लिंगैस्त्रीन्गुणानेतानतीतो भवति प्रभो।\nकिमाचारः कथं चैतांस्त्रीन्गुणानतिवर्तते॥","t":"arjuna uvāca\nkairliṃgaistrīnguṇānetānatīto bhavati prabho|\nkimācāraḥ kathaṃ caitāṃstrīnguṇānativartate||","e":"Arjuna.\nOh, my Lord!\nWhich be the signs to know him that hath gone\nPast the Three Modes? How liveth he? What way\nLeadeth him safe beyond the threefold Modes?"},
{"c":14,"v":22,"d":"श्री भगवानुवाच\nप्रकाशं च प्रवृत्तिं च मोहमेव च पाण्डव।\nन द्वेष्टि सम्प्रवृत्तानि न निवृत्तानि काङ्क्षति॥","t":"śrī bhagavānuvāca\nprakāśaṃ ca pravṛttiṃ ca mohameva ca pāṇḍava|\nna dveṣṭi sampravṛttāni na nivṛttāni kāṅkṣati||","e":"Krishna.\nHe who with equanimity surveys\nLustre of goodness, strife of passion, sloth\nOf ignorance, not angry if they are,\nNot wishful when they are not:"},
{"c":14,"v":23,"d":"उदासीनवदासीनो गुणैर्यो न विचाल्यते।\nगुणा वर्तन्त इत्येव योऽवतिष्ठति नेङ्गते॥","t":"udāsīnavadāsīno guṇairyo na vicālyate|\nguṇā vartanta ityeva yo'vatiṣṭhati neṅgate||","e":"he who sits\nA sojourner and stranger in their midst\nUnruffled, standing off, saying--serene--\nWhen troubles break, \"These be the Qualities!\""},
{"c":14,"v":24,"d":"समदुःखसुखः स्वस्थः समलोष्टाश्मकाञ्चनः।\nतुल्यप्रियाप्रियो धीरस्तुल्यनिन्दात्मसंस्तुतिः॥","t":"samaduḥkhasukhaḥ svasthaḥ samaloṣṭāśmakāñcanaḥ|\ntulyapriyāpriyo dhīrastulyanindātmasaṃstutiḥ||","e":"He unto whom--self-centred--grief and joy\nSound as one word; to whose deep-seeing eyes\nThe clod, the marble, and the gold are one;\nWhose equal heart holds the same gentleness\nFor lovely and unlovely things, firm-set,\nWell-pleased in praise and dispraise;"},
{"c":14,"v":25,"d":"मानापमानयोस्तुल्यस्तुल्यो मित्रारिपक्षयोः।\nसर्वारम्भपरित्यागी गुणातीतः स उच्यते॥","t":"mānāpamānayostulyastulyo mitrāripakṣayoḥ|\nsarvārambhaparityāgī guṇātītaḥ sa ucyate||","e":"satisfied\nWith honour or dishonour; unto friends\nAnd unto foes alike in tolerance;\nDetached from undertakings,--he is named\nSurmounter of the Qualities!"},
{"c":14,"v":26,"d":"मां च योऽव्यभिचारेण भक्ितयोगेन सेवते।\nस गुणान्समतीत्यैतान् ब्रह्मभूयाय कल्पते॥","t":"māṃ ca yo'vyabhicāreṇa bhaktayogena sevate|\nsa guṇānsamatītyaitān brahmabhūyāya kalpate||","e":"And such--\nWith single, fervent faith adoring Me,\nPassing beyond the Qualities, conforms\nTo Brahma, and attains Me!"},
{"c":14,"v":27,"d":"ब्रह्मणो हि प्रतिष्ठाऽहममृतस्याव्ययस्य च।\nशाश्वतस्य च धर्मस्य सुखस्यैकान्तिकस्य च॥","t":"brahmaṇo hi pratiṣṭhā'hamamṛtasyāvyayasya ca|\nśāśvatasya ca dharmasya sukhasyaikāntikasya ca||","e":"For I am\nThat whereof Brahma is the likeness! Mine\nThe Amrit is; and Immortality\nIs mine; and mine perfect Felicity!"},
{"c":15,"v":1,"d":"श्री भगवानुवाच\nऊर्ध्वमूलमधःशाखमश्वत्थं प्राहुरव्ययम्।\nछन्दांसि यस्य पर्णानि यस्तं वेद स वेदवित्॥","t":"śrī bhagavānuvāca\nūrdhvamūlamadhaḥśākhamaśvatthaṃ prāhuravyayam|\nchandāṃsi yasya parṇāni yastaṃ veda sa vedavit||","e":"Krishna.\nMen call the Aswattha,--the Banyan-tree,--\nWhich hath its boughs beneath, its roots above,--\nThe ever-holy tree. Yea! for its leaves\nAre green and waving hymns which whisper Truth!\nWho knows the Aswattha, knows Veds, and all."},
{"c":15,"v":2,"d":"अधश्चोर्ध्वं प्रसृतास्तस्य शाखा     गुणप्रवृद्धा विषयप्रवालाः।\nअधश्च मूलान्यनुसन्ततानि     कर्मानुबन्धीनि मनुष्यलोके॥","t":"adhaścordhvaṃ prasṛtāstasya śākhā     guṇapravṛddhā viṣayapravālāḥ|\nadhaśca mūlānyanusantatāni     karmānubandhīni manuṣyaloke||","e":"Its branches shoot to heaven and sink to earth,\nEven as the deeds of men, which take their birth\nFrom qualities: its silver sprays and blooms,\nAnd all the eager verdure of its girth,\nLeap to quick life at kiss of sun and air,\nAs men's lives quicken to the temptings fair\nOf wooing sense: its hanging rootlets seek\nThe soil beneath, helping to hold it there,\nAs actions wrought amid this world of men\nBind them by ever-tightening bonds again."},
{"c":15,"v":3,"d":"न रूपमस्येह तथोपलभ्यते    नान्तो न चादिर्न च संप्रतिष्ठा।\nअश्वत्थमेनं सुविरूढमूल    मसङ्गशस्त्रेण दृढेन छित्त्वा॥","t":"na rūpamasyeha tathopalabhyate    nānto na cādirna ca saṃpratiṣṭhā|\naśvatthamenaṃ suvirūḍhamūla    masaṅgaśastreṇa dṛḍhena chittvā||","e":"If ye knew well the teaching of the Tree,\nWhat its shape saith; and whence it springs; and, then\nHow it must end, and all the ills of it,\nThe axe of sharp Detachment ye would whet,\nAnd cleave the clinging snaky roots, and lay\nThis Aswattha of sense-life low,--to set"},
{"c":15,"v":4,"d":"ततः पदं तत्परिमार्गितव्य    यस्मिन्गता न निवर्तन्ति भूयः।\nतमेव चाद्यं पुरुषं प्रपद्ये    यतः प्रवृत्तिः प्रसृता पुराणी॥","t":"tataḥ padaṃ tatparimārgitavya    yasmingatā na nivartanti bhūyaḥ|\ntameva cādyaṃ puruṣaṃ prapadye    yataḥ pravṛttiḥ prasṛtā purāṇī||","e":"New growths upspringing to that happier sky,--\nWhich they who reach shall have no day to die,\nNor fade away, nor fall--to Him, I mean,\nFATHER and FIRST, Who made the mystery\nOf old Creation;"},
{"c":15,"v":5,"d":"निर्मानमोहा जितसङ्गदोषा    अध्यात्मनित्या विनिवृत्तकामाः।\nद्वन्द्वैर्विमुक्ताः सुखदुःखसंज्ञै    र्गच्छन्त्यमूढाः पदमव्ययं तत्॥","t":"nirmānamohā jitasaṅgadoṣā    adhyātmanityā vinivṛttakāmāḥ|\ndvandvairvimuktāḥ sukhaduḥkhasaṃjñai    rgacchantyamūḍhāḥ padamavyayaṃ tat||","e":"for to Him come they\nFrom passion and from dreams who break away;\nWho part the bonds constraining them to flesh,\nAnd,--Him, the Highest, worshipping alway--\nNo longer grow at mercy of what breeze\nOf summer pleasure stirs the sleeping trees,\nWhat blast of tempest tears them, bough and stem\nTo the eternal world pass such as these!"},
{"c":15,"v":6,"d":"न तद्भासयते सूर्यो न शशाङ्को न पावकः।\nयद्गत्वा न निवर्तन्ते तद्धाम परमं मम॥","t":"na tadbhāsayate sūryo na śaśāṅko na pāvakaḥ|\nyadgatvā na nivartante taddhāma paramaṃ mama||","e":"Another Sun gleams there! another Moon!\nAnother Light,--not Dusk, nor Dawn, nor Noon--\nWhich they who once behold return no more;\nThey have attained My rest, life's Utmost boon!"},
{"c":15,"v":7,"d":"ममैवांशो जीवलोके जीवभूतः सनातनः।\nमनःषष्ठानीन्द्रियाणि प्रकृतिस्थानि कर्षति॥","t":"mamaivāṃśo jīvaloke jīvabhūtaḥ sanātanaḥ|\nmanaḥṣaṣṭhānīndriyāṇi prakṛtisthāni karṣati||","e":"When, in this world of manifested life,\nThe undying Spirit, setting forth from Me,\nTaketh on form, it draweth to itself\nFrom Being's storehouse,--which containeth all,--\nSenses and intellect."},
{"c":15,"v":8,"d":"शरीरं यदवाप्नोति यच्चाप्युत्क्रामतीश्वरः।\nगृहीत्वैतानि संयाति वायुर्गन्धानिवाशयात्॥","t":"śarīraṃ yadavāpnoti yaccāpyutkrāmatīśvaraḥ|\ngṛhītvaitāni saṃyāti vāyurgandhānivāśayāt||","e":"The Sovereign Soul\nThus entering the flesh, or quitting it,\nGathers these up, as the wind gathers scents,\nBlowing above the flower-beds."},
{"c":15,"v":9,"d":"श्रोत्रं चक्षुः स्पर्शनं च रसनं घ्राणमेव च।\nअधिष्ठाय मनश्चायं विषयानुपसेवते॥","t":"śrotraṃ cakṣuḥ sparśanaṃ ca rasanaṃ ghrāṇameva ca|\nadhiṣṭhāya manaścāyaṃ viṣayānupasevate||","e":"Ear and Eye,\nAnd Touch and Taste, and Smelling, these it takes,--\nYea, and a sentient mind;--linking itself\nTo sense-things so."},
{"c":15,"v":10,"d":"उत्क्रामन्तं स्थितं वापि भुञ्जानं वा गुणान्वितम्।\nविमूढा नानुपश्यन्ति पश्यन्ति ज्ञानचक्षुषः॥","t":"utkrāmantaṃ sthitaṃ vāpi bhuñjānaṃ vā guṇānvitam|\nvimūḍhā nānupaśyanti paśyanti jñānacakṣuṣaḥ||","e":"The unenlightened ones\nMark not that Spirit when he goes or comes,\nNor when he takes his pleasure in the form,\nConjoined with qualities; but those see plain\nWho have the eyes to see."},
{"c":15,"v":11,"d":"यतन्तो योगिनश्चैनं पश्यन्त्यात्मन्यवस्थितम्।\nयतन्तोऽप्यकृतात्मानो नैनं पश्यन्त्यचेतसः॥","t":"yatanto yoginaścainaṃ paśyantyātmanyavasthitam|\nyatanto'pyakṛtātmāno nainaṃ paśyantyacetasaḥ||","e":"Holy souls see\nWhich strive thereto. Enlightened, they perceive\nThat Spirit in themselves; but foolish ones,\nEven though they strive, discern not, having hearts\nUnkindled, ill-informed!"},
{"c":15,"v":12,"d":"यदादित्यगतं तेजो जगद्भासयतेऽखिलम्।\nयच्चन्द्रमसि यच्चाग्नौ तत्तेजो विद्धि मामकम्॥","t":"yadādityagataṃ tejo jagadbhāsayate'khilam|\nyaccandramasi yaccāgnau tattejo viddhi māmakam||","e":"Know, too, from Me\nShineth the gathered glory of the suns\nWhich lighten all the world: from Me the moons\nDraw silvery beams, and fire fierce loveliness."},
{"c":15,"v":13,"d":"गामाविश्य च भूतानि धारयाम्यहमोजसा।\nपुष्णामि चौषधीः सर्वाः सोमो भूत्वा रसात्मकः॥","t":"gāmāviśya ca bhūtāni dhārayāmyahamojasā|\npuṣṇāmi cauṣadhīḥ sarvāḥ somo bhūtvā rasātmakaḥ||","e":"I penetrate the clay, and lend all shapes\nTheir living force; I glide into the plant--\nRoot, leaf, and bloom--to make the woodlands green\nWith springing sap."},
{"c":15,"v":14,"d":"अहं वैश्वानरो भूत्वा प्राणिनां देहमाश्रितः।\nप्राणापानसमायुक्तः पचाम्यन्नं चतुर्विधम्॥","t":"ahaṃ vaiśvānaro bhūtvā prāṇināṃ dehamāśritaḥ|\nprāṇāpānasamāyuktaḥ pacāmyannaṃ caturvidham||","e":"Becoming vital warmth,\nI glow in glad, respiring frames, and pass,\nWith outward and with inward breath, to feed\nThe body by all meats."},
{"c":15,"v":15,"d":"सर्वस्य चाहं हृदि सन्निविष्टो    मत्तः स्मृतिर्ज्ञानमपोहनं च।\nवेदैश्च सर्वैरहमेव वेद्यो    वेदान्तकृद्वेदविदेव चाहम्॥","t":"sarvasya cāhaṃ hṛdi sanniviṣṭo    mattaḥ smṛtirjñānamapohanaṃ ca|\nvedaiśca sarvairahameva vedyo    vedāntakṛdvedavideva cāham||","e":""},
{"c":15,"v":16,"d":"द्वाविमौ पुरुषौ लोके क्षरश्चाक्षर एव च।\nक्षरः सर्वाणि भूतानि कूटस्थोऽक्षर उच्यते॥","t":"dvāvimau puruṣau loke kṣaraścākṣara eva ca|\nkṣaraḥ sarvāṇi bhūtāni kūṭastho'kṣara ucyate||","e":"For in this world\nBeing is twofold: the Divided, one;\nThe Undivided, one. All things that live\nAre \"the Divided.\" That which sits apart,\n\"The Undivided.\""},
{"c":15,"v":17,"d":"उत्तमः पुरुषस्त्वन्यः परमात्मेत्युदाहृतः।\nयो लोकत्रयमाविश्य बिभर्त्यव्यय ईश्वरः॥","t":"uttamaḥ puruṣastvanyaḥ paramātmetyudāhṛtaḥ|\nyo lokatrayamāviśya bibhartyavyaya īśvaraḥ||","e":"Higher still is He,\nThe Highest, holding all, whose Name is LORD,\nThe Eternal, Sovereign, First! Who fills all worlds,\nSustaining them."},
{"c":15,"v":18,"d":"यस्मात्क्षरमतीतोऽहमक्षरादपि चोत्तमः।\nअतोऽस्मि लोके वेदे च प्रथितः पुरुषोत्तमः॥","t":"yasmātkṣaramatīto'hamakṣarādapi cottamaḥ|\nato'smi loke vede ca prathitaḥ puruṣottamaḥ||","e":"And--dwelling thus beyond\nDivided Being and Undivided--I\nAm called of men and Vedas, Life Supreme,\nThe PURUSHOTTAMA."},
{"c":15,"v":19,"d":"यो मामेवमसम्मूढो जानाति पुरुषोत्तमम्।\nस सर्वविद्भजति मां सर्वभावेन भारत॥","t":"yo māmevamasammūḍho jānāti puruṣottamam|\nsa sarvavidbhajati māṃ sarvabhāvena bhārata||","e":"Who knows Me thus,\nWith mind unclouded, knoweth all, dear Prince!\nAnd with his whole soul ever worshippeth Me."},
{"c":15,"v":20,"d":"इति गुह्यतमं शास्त्रमिदमुक्तं मयाऽनघ।\nएतद्बुद्ध्वा बुद्धिमान्स्यात्कृतकृत्यश्च भारत॥","t":"iti guhyatamaṃ śāstramidamuktaṃ mayā'nagha|\netadbuddhvā buddhimānsyātkṛtakṛtyaśca bhārata||","e":"Now is the sacred, secret Mystery\nDeclared to thee! Who comprehendeth this\nHath wisdom! He is quit of works in bliss!"},
{"c":16,"v":1,"d":"श्री भगवानुवाच\nअभयं सत्त्वसंशुद्धिः ज्ञानयोगव्यवस्थितिः।\nदानं दमश्च यज्ञश्च स्वाध्यायस्तप आर्जवम्॥","t":"śrī bhagavānuvāca\nabhayaṃ sattvasaṃśuddhiḥ jñānayogavyavasthitiḥ|\ndānaṃ damaśca yajñaśca svādhyāyastapa ārjavam||","e":"Krishna.\nFearlessness, singleness of soul, the will\nAlways to strive for wisdom; opened hand\nAnd governed appetites; and piety,\nAnd love of lonely study; humbleness,\nUprightness,"},
{"c":16,"v":2,"d":"अहिंसा सत्यमक्रोधस्त्यागः शान्तिरपैशुनम्।\nदया भूतेष्वलोलुप्त्वं मार्दवं ह्रीरचापलम्॥","t":"ahiṃsā satyamakrodhastyāgaḥ śāntirapaiśunam|\ndayā bhūteṣvaloluptvaṃ mārdavaṃ hrīracāpalam||","e":"heed to injure nought which lives,\nTruthfulness, slowness unto wrath, a mind\nThat lightly letteth go what others prize;\nAnd equanimity, and charity\nWhich spieth no man's faults; and tenderness\nTowards all that suffer; a contented heart,\nFluttered by no desires; a bearing mild,\nModest, and grave,"},
{"c":16,"v":3,"d":"तेजः क्षमा धृतिः शौचमद्रोहो नातिमानिता।\nभवन्ति सम्पदं दैवीमभिजातस्य भारत॥","t":"tejaḥ kṣamā dhṛtiḥ śaucamadroho nātimānitā|\nbhavanti sampadaṃ daivīmabhijātasya bhārata||","e":"with manhood nobly mixed,\nWith patience, fortitude, and purity;\nAn unrevengeful spirit, never given\nTo rate itself too high;--such be the signs,\nO Indian Prince! of him whose feet are set\nOn that fair path which leads to heavenly birth!"},
{"c":16,"v":4,"d":"दम्भो दर्पोऽभिमानश्च क्रोधः पारुष्यमेव च।\nअज्ञानं चाभिजातस्य पार्थ सम्पदमासुरीम्॥","t":"dambho darpo'bhimānaśca krodhaḥ pāruṣyameva ca|\najñānaṃ cābhijātasya pārtha sampadamāsurīm||","e":"Deceitfulness, and arrogance, and pride,\nQuickness to anger, harsh and evil speech,\nAnd ignorance, to its own darkness blind,--\nThese be the signs, My Prince! of him whose birth\nIs fated for the regions of the vile."},
{"c":16,"v":5,"d":"दैवी सम्पद्विमोक्षाय निबन्धायासुरी मता।\nमा शुचः सम्पदं दैवीमभिजातोऽसि पाण्डव॥","t":"daivī sampadvimokṣāya nibandhāyāsurī matā|\nmā śucaḥ sampadaṃ daivīmabhijāto'si pāṇḍava||","e":"The Heavenly Birth brings to deliverance,\nSo should'st thou know! The birth with Asuras\nBrings into bondage. Be thou joyous, Prince!\nWhose lot is set apart for heavenly Birth."},
{"c":16,"v":6,"d":"द्वौ भूतसर्गौ लोकेऽस्मिन् दैव आसुर एव च।\nदैवो विस्तरशः प्रोक्त आसुरं पार्थ मे श्रृणु॥","t":"dvau bhūtasargau loke'smin daiva āsura eva ca|\ndaivo vistaraśaḥ prokta āsuraṃ pārtha me śrṛṇu||","e":"Two stamps there are marked on all living men,\nDivine and Undivine; I spake to thee\nBy what marks thou shouldst know the Heavenly Man,\nHear from me now of the Unheavenly!"},
{"c":16,"v":7,"d":"प्रवृत्तिं च निवृत्तिं च जना न विदुरासुराः।\nन शौचं नापि चाचारो न सत्यं तेषु विद्यते॥","t":"pravṛttiṃ ca nivṛttiṃ ca janā na vidurāsurāḥ|\nna śaucaṃ nāpi cācāro na satyaṃ teṣu vidyate||","e":"They comprehend not, the Unheavenly,\nHow Souls go forth from Me; nor how they come\nBack unto Me: nor is there Truth in these,\nNor purity, nor rule of Life."},
{"c":16,"v":8,"d":"असत्यमप्रतिष्ठं ते जगदाहुरनीश्वरम्।\nअपरस्परसम्भूतं किमन्यत्कामहैतुकम्॥","t":"asatyamapratiṣṭhaṃ te jagadāhuranīśvaram|\naparasparasambhūtaṃ kimanyatkāmahaitukam||","e":"\"This world\nHath not a Law, nor Order, nor a Lord,\"\nSo say they: \"nor hath risen up by Cause\nFollowing on Cause, in perfect purposing,\nBut is none other than a House of Lust.\""},
{"c":16,"v":9,"d":"एतां दृष्टिमवष्टभ्य नष्टात्मानोऽल्पबुद्धयः।\nप्रभवन्त्युग्रकर्माणः क्षयाय जगतोऽहिताः॥","t":"etāṃ dṛṣṭimavaṣṭabhya naṣṭātmāno'lpabuddhayaḥ|\nprabhavantyugrakarmāṇaḥ kṣayāya jagato'hitāḥ||","e":"And, this thing thinking, all those ruined ones--\nOf little wit, dark-minded--give themselves\nTo evil deeds, the curses of their kind."},
{"c":16,"v":10,"d":"काममाश्रित्य दुष्पूरं दम्भमानमदान्विताः।\nमोहाद्गृहीत्वासद्ग्राहान्प्रवर्तन्तेऽशुचिव्रताः॥","t":"kāmamāśritya duṣpūraṃ dambhamānamadānvitāḥ|\nmohādgṛhītvāsadgrāhānpravartante'śucivratāḥ||","e":"Surrendered to desires insatiable,\nFull of deceitfulness, folly, and pride,\nIn blindness cleaving to their errors, caught\nInto the sinful course,"},
{"c":16,"v":11,"d":"चिन्तामपरिमेयां च प्रलयान्तामुपाश्रिताः।\nकामोपभोगपरमा एतावदिति निश्िचताः॥","t":"cintāmaparimeyāṃ ca pralayāntāmupāśritāḥ|\nkāmopabhogaparamā etāvaditi niścatāḥ||","e":"they trust this lie\nAs it were true--this lie which leads to death--\nFinding in Pleasure all the good which is,\nAnd crying \"Here it finisheth!\""},
{"c":16,"v":12,"d":"आशापाशशतैर्बद्धाः कामक्रोधपरायणाः।\nईहन्ते कामभोगार्थमन्यायेनार्थसञ्चयान्॥","t":"āśāpāśaśatairbaddhāḥ kāmakrodhaparāyaṇāḥ|\nīhante kāmabhogārthamanyāyenārthasañcayān||","e":"Ensnared\nIn nooses of a hundred idle hopes,\nSlaves to their passion and their wrath, they buy\nWealth with base deeds, to glut hot appetites;"},
{"c":16,"v":13,"d":"इदमद्य मया लब्धमिमं प्राप्स्ये मनोरथम्।\nइदमस्तीदमपि मे भविष्यति पुनर्धनम्॥","t":"idamadya mayā labdhamimaṃ prāpsye manoratham|\nidamastīdamapi me bhaviṣyati punardhanam||","e":"\"Thus much, to-day,\" they say, \"we gained! thereby\nSuch and such wish of heart shall have its fill;\nAnd this is ours! and th' other shall be ours!"},
{"c":16,"v":14,"d":"असौ मया हतः शत्रुर्हनिष्ये चापरानपि।\nईश्वरोऽहमहं भोगी सिद्धोऽहं बलवान्सुखी॥","t":"asau mayā hataḥ śatrurhaniṣye cāparānapi|\nīśvaro'hamahaṃ bhogī siddho'haṃ balavānsukhī||","e":"To-day we slew a foe, and we will slay\nOur other enemy to-morrow! Look!\nAre we not lords? Make we not goodly cheer?\nIs not our fortune famous, brave, and great?"},
{"c":16,"v":15,"d":"आढ्योऽभिजनवानस्मि कोऽन्योऽस्ति सदृशो मया।\nयक्ष्ये दास्यामि मोदिष्य इत्यज्ञानविमोहिताः॥","t":"āḍhyo'bhijanavānasmi ko'nyo'sti sadṛśo mayā|\nyakṣye dāsyāmi modiṣya ityajñānavimohitāḥ||","e":"Rich are we, proudly born! What other men\nLive like to us? Kill, then, for sacrifice!\nCast largesse, and be merry!\" So they speak\nDarkened by ignorance;"},
{"c":16,"v":16,"d":"अनेकचित्तविभ्रान्ता मोहजालसमावृताः।\nप्रसक्ताः कामभोगेषु पतन्ति नरकेऽशुचौ॥","t":"anekacittavibhrāntā mohajālasamāvṛtāḥ|\nprasaktāḥ kāmabhogeṣu patanti narake'śucau||","e":"and so they fall--\nTossed to and fro with projects, tricked, and bound\nIn net of black delusion, lost in lusts--\nDown to foul Naraka."},
{"c":16,"v":17,"d":"आत्मसम्भाविताः स्तब्धा धनमानमदान्विताः।\nयजन्ते नामयज्ञैस्ते दम्भेनाविधिपूर्वकम्॥","t":"ātmasambhāvitāḥ stabdhā dhanamānamadānvitāḥ|\nyajante nāmayajñaiste dambhenāvidhipūrvakam||","e":"Conceited, fond,\nStubborn and proud, dead-drunken with the wine\nOf wealth, and reckless, all their offerings\nHave but a show of reverence, being not made\nIn piety of ancient faith."},
{"c":16,"v":18,"d":"अहङ्कारं बलं दर्पं कामं क्रोधं च संश्रिताः।\nमामात्मपरदेहेषु प्रद्विषन्तोऽभ्यसूयकाः॥","t":"ahaṅkāraṃ balaṃ darpaṃ kāmaṃ krodhaṃ ca saṃśritāḥ|\nmāmātmaparadeheṣu pradviṣanto'bhyasūyakāḥ||","e":"Thus vowed\nTo self-hood, force, insolence, feasting, wrath,\nThese My blasphemers, in the forms they wear\nAnd in the forms they breed, my foemen are,"},
{"c":16,"v":19,"d":"तानहं द्विषतः क्रूरान्संसारेषु नराधमान्।\nक्षिपाम्यजस्रमशुभानासुरीष्वेव योनिषु॥","t":"tānahaṃ dviṣataḥ krūrānsaṃsāreṣu narādhamān|\nkṣipāmyajasramaśubhānāsurīṣveva yoniṣu||","e":"Hateful and hating; cruel, evil, vile,\nLowest and least of men, whom I cast down\nAgain, and yet again, at end of lives,\nInto some devilish womb,"},
{"c":16,"v":20,"d":"असुरीं योनिमापन्ना मूढा जन्मनि जन्मनि।\nमामप्राप्यैव कौन्तेय ततो यान्त्यधमां गतिम्॥","t":"asurīṃ yonimāpannā mūḍhā janmani janmani|\nmāmaprāpyaiva kaunteya tato yāntyadhamāṃ gatim||","e":"whence--birth by birth--\nThe devilish wombs re-spawn them, all beguiled;\nAnd, till they find and worship Me, sweet Prince!\nTread they that Nether Road."},
{"c":16,"v":21,"d":"त्रिविधं नरकस्येदं द्वारं नाशनमात्मनः।\nकामः क्रोधस्तथा लोभस्तस्मादेतत्त्रयं त्यजेत्॥","t":"trividhaṃ narakasyedaṃ dvāraṃ nāśanamātmanaḥ|\nkāmaḥ krodhastathā lobhastasmādetattrayaṃ tyajet||","e":"The Doors of Hell\nAre threefold, whereby men to ruin pass,--\nThe door of Lust, the door of Wrath, the door\nOf Avarice. Let a man shun those three!"},
{"c":16,"v":22,"d":"एतैर्विमुक्तः कौन्तेय तमोद्वारैस्त्रिभिर्नरः।\nआचरत्यात्मनः श्रेयस्ततो याति परां गतिम्॥","t":"etairvimuktaḥ kaunteya tamodvāraistribhirnaraḥ|\nācaratyātmanaḥ śreyastato yāti parāṃ gatim||","e":"He who shall turn aside from entering\nAll those three gates of Narak, wendeth straight\nTo find his peace, and comes to Swarga's gate."},
{"c":16,"v":23,"d":"यः शास्त्रविधिमुत्सृज्य वर्तते कामकारतः।\nन स सिद्धिमवाप्नोति न सुखं न परां गतिम्॥","t":"yaḥ śāstravidhimutsṛjya vartate kāmakārataḥ|\nna sa siddhimavāpnoti na sukhaṃ na parāṃ gatim||","e":"","g":[23,24]},
{"c":16,"v":24,"d":"तस्माच्छास्त्रं प्रमाणं ते कार्याकार्यव्यवस्थितौ।\nज्ञात्वा शास्त्रविधानोक्तं कर्म कर्तुमिहार्हसि॥","t":"tasmācchāstraṃ pramāṇaṃ te kāryākāryavyavasthitau|\njñātvā śāstravidhānoktaṃ karma kartumihārhasi||","e":"","g":[23,24]},
{"c":17,"v":1,"d":"अर्जुन उवाच\nये शास्त्रविधिमुत्सृज्य यजन्ते श्रद्धयाऽन्विताः।\nतेषां निष्ठा तु का कृष्ण सत्त्वमाहो रजस्तमः॥","t":"arjuna uvāca\nye śāstravidhimutsṛjya yajante śraddhayā'nvitāḥ|\nteṣāṃ niṣṭhā tu kā kṛṣṇa sattvamāho rajastamaḥ||","e":"Arjuna.\nIf men forsake the holy ordinance,\nHeedless of Shastras, yet keep faith at heart\nAnd worship, what shall be the state of those,\nGreat Krishna! Sattwan, Rajas, Tamas? Say!"},
{"c":17,"v":2,"d":"श्री भगवानुवाच\nत्रिविधा भवति श्रद्धा देहिनां सा स्वभावजा।\nसात्त्विकी राजसी चैव तामसी चेति तां श्रृणु॥","t":"śrī bhagavānuvāca\ntrividhā bhavati śraddhā dehināṃ sā svabhāvajā|\nsāttvikī rājasī caiva tāmasī ceti tāṃ śrṛṇu||","e":"Krishna.\nThreefold the faith is of mankind and springs\nFrom those three qualities,--becoming \"true,\"\nOr \"passion-stained,\" or \"dark,\" as thou shalt hear!"},
{"c":17,"v":3,"d":"सत्त्वानुरूपा सर्वस्य श्रद्धा भवति भारत।\nश्रद्धामयोऽयं पुरुषो यो यच्छ्रद्धः स एव सः॥","t":"sattvānurūpā sarvasya śraddhā bhavati bhārata|\nśraddhāmayo'yaṃ puruṣo yo yacchraddhaḥ sa eva saḥ||","e":"The faith of each believer, Indian Prince!\nConforms itself to what he truly is.\nWhere thou shalt see a worshipper, that one\nTo what he worships lives assimilate,\n[Such as the shrine, so is the votary,]"},
{"c":17,"v":4,"d":"यजन्ते सात्त्विका देवान्यक्षरक्षांसि राजसाः।\nप्रेतान्भूतगणांश्चान्ये यजन्ते तामसा जनाः॥","t":"yajante sāttvikā devānyakṣarakṣāṃsi rājasāḥ|\npretānbhūtagaṇāṃścānye yajante tāmasā janāḥ||","e":"The \"soothfast\" souls adore true gods; the souls\nObeying Rajas worship Rakshasas\nOr Yakshas; and the men of Darkness pray\nTo Pretas and to Bhutas."},
{"c":17,"v":5,"d":"अशास्त्रविहितं घोरं तप्यन्ते ये तपो जनाः।\nदम्भाहङ्कारसंयुक्ताः कामरागबलान्विताः॥","t":"aśāstravihitaṃ ghoraṃ tapyante ye tapo janāḥ|\ndambhāhaṅkārasaṃyuktāḥ kāmarāgabalānvitāḥ||","e":"Yea, and those\nWho practise bitter penance, not enjoined\nBy rightful rule--penance which hath its root\nIn self-sufficient, proud hypocrisies--\nThose men, passion-beset, violent, wild,"},
{"c":17,"v":6,"d":"कर्षयन्तः शरीरस्थं भूतग्राममचेतसः।\nमां चैवान्तःशरीरस्थं तान्विद्ध्यासुरनिश्चयान्॥","t":"karṣayantaḥ śarīrasthaṃ bhūtagrāmamacetasaḥ|\nmāṃ caivāntaḥśarīrasthaṃ tānviddhyāsuraniścayān||","e":"Torturing--the witless ones--My elements\nShut in fair company within their flesh,\n(Nay, Me myself, present within the flesh!)\nKnow them to devils devoted, not to Heaven!"},
{"c":17,"v":7,"d":"आहारस्त्वपि सर्वस्य त्रिविधो भवति प्रियः।\nयज्ञस्तपस्तथा दानं तेषां भेदमिमं श्रृणु॥","t":"āhārastvapi sarvasya trividho bhavati priyaḥ|\nyajñastapastathā dānaṃ teṣāṃ bhedamimaṃ śrṛṇu||","e":"For like as foods are threefold for mankind\nIn nourishing, so is there threefold way\nOf worship, abstinence, and almsgiving!\nHear this of Me!"},
{"c":17,"v":8,"d":"आयुःसत्त्वबलारोग्यसुखप्रीतिविवर्धनाः।\nरस्याः स्निग्धाः स्थिरा हृद्या आहाराः सात्त्विकप्रियाः॥","t":"āyuḥsattvabalārogyasukhaprītivivardhanāḥ|\nrasyāḥ snigdhāḥ sthirā hṛdyā āhārāḥ sāttvikapriyāḥ||","e":"there is a food which brings\nForce, substance, strength, and health, and joy to live,\nBeing well-seasoned, cordial, comforting,\nThe \"Soothfast\" meat."},
{"c":17,"v":9,"d":"कट्वम्ललवणात्युष्णतीक्ष्णरूक्षविदाहिनः।\nआहारा राजसस्येष्टा दुःखशोकामयप्रदाः॥","t":"kaṭvamlalavaṇātyuṣṇatīkṣṇarūkṣavidāhinaḥ|\nāhārā rājasasyeṣṭā duḥkhaśokāmayapradāḥ||","e":"And there be foods which bring\nAches and unrests, and burning blood, and grief,\nBeing too biting, heating, salt, and sharp,\nAnd therefore craved by too strong appetite."},
{"c":17,"v":10,"d":"यातयामं गतरसं पूति पर्युषितं च यत्।\nउच्छिष्टमपि चामेध्यं भोजनं तामसप्रियम्॥","t":"yātayāmaṃ gatarasaṃ pūti paryuṣitaṃ ca yat|\nucchiṣṭamapi cāmedhyaṃ bhojanaṃ tāmasapriyam||","e":"And there is foul food--kept from over-night,\nSavourless, filthy, which the foul will eat,\nA feast of rottenness, meet for the lips\nOf such as love the \"Darkness.\""},
{"c":17,"v":11,"d":"अफलाकाङ्क्षिभिर्यज्ञो विधिदृष्टो य इज्यते।\nयष्टव्यमेवेति मनः समाधाय स सात्त्विकः॥","t":"aphalākāṅkṣibhiryajño vidhidṛṣṭo ya ijyate|\nyaṣṭavyameveti manaḥ samādhāya sa sāttvikaḥ||","e":"Thus with rites;--\nA sacrifice not for rewardment made,\nOffered in rightful wise, when he who vows\nSayeth, with heart devout, \"This I should do!\"\nIs \"Soothfast\" rite."},
{"c":17,"v":12,"d":"अभिसंधाय तु फलं दम्भार्थमपि चैव यत्।\nइज्यते भरतश्रेष्ठ तं यज्ञं विद्धि राजसम्॥","t":"abhisaṃdhāya tu phalaṃ dambhārthamapi caiva yat|\nijyate bharataśreṣṭha taṃ yajñaṃ viddhi rājasam||","e":"But sacrifice for gain,\nOffered for good repute, be sure that this,\nO Best of Bharatas! is Rajas-rite,\nWith stamp of \"passion.\""},
{"c":17,"v":13,"d":"विधिहीनमसृष्टान्नं मन्त्रहीनमदक्षिणम्।\nश्रद्धाविरहितं यज्ञं तामसं परिचक्षते॥","t":"vidhihīnamasṛṣṭānnaṃ mantrahīnamadakṣiṇam|\nśraddhāvirahitaṃ yajñaṃ tāmasaṃ paricakṣate||","e":"And a sacrifice\nOffered against the laws, with no due dole\nOf food-giving, with no accompaniment\nOf hallowed hymn, nor largesse to the priests,\nIn faithless celebration, call it vile,\nThe deed of \"Darkness!\"--lost!"},
{"c":17,"v":14,"d":"देवद्विजगुरुप्राज्ञपूजनं शौचमार्जवम्।\nब्रह्मचर्यमहिंसा च शारीरं तप उच्यते॥","t":"devadvijaguruprājñapūjanaṃ śaucamārjavam|\nbrahmacaryamahiṃsā ca śārīraṃ tapa ucyate||","e":"Worship of gods\nMeriting worship; lowly reverence\nOf Twice-borns, Teachers, Elders; Purity,\nRectitude, and the Brahmacharya's vow,\nAnd not to injure any helpless thing,--\nThese make a true religiousness of Act."},
{"c":17,"v":15,"d":"अनुद्वेगकरं वाक्यं सत्यं प्रियहितं च यत्।\nस्वाध्यायाभ्यसनं चैव वाङ्मयं तप उच्यते॥","t":"anudvegakaraṃ vākyaṃ satyaṃ priyahitaṃ ca yat|\nsvādhyāyābhyasanaṃ caiva vāṅmayaṃ tapa ucyate||","e":"Words causing no man woe, words ever true,\nGentle and pleasing words, and those ye say\nIn murmured reading of a Sacred Writ,--\nThese make the true religiousness of Speech."},
{"c":17,"v":16,"d":"मनःप्रसादः सौम्यत्वं मौनमात्मविनिग्रहः।\nभावसंशुद्धिरित्येतत्तपो मानसमुच्यते॥","t":"manaḥprasādaḥ saumyatvaṃ maunamātmavinigrahaḥ|\nbhāvasaṃśuddhirityetattapo mānasamucyate||","e":"Serenity of soul, benignity,\nSway of the silent Spirit, constant stress\nTo sanctify the Nature,--these things make\nGood rite, and true religiousness of Mind."},
{"c":17,"v":17,"d":"श्रद्धया परया तप्तं तपस्तत्ित्रविधं नरैः।\nअफलाकाङ्क्षिभिर्युक्तैः सात्त्विकं परिचक्षते॥","t":"śraddhayā parayā taptaṃ tapastattravidhaṃ naraiḥ|\naphalākāṅkṣibhiryuktaiḥ sāttvikaṃ paricakṣate||","e":"Such threefold faith, in highest piety\nKept, with no hope of gain, by hearts devote,\nIs perfect work of Sattwan, true belief."},
{"c":17,"v":18,"d":"सत्कारमानपूजार्थं तपो दम्भेन चैव यत्।\nक्रियते तदिह प्रोक्तं राजसं चलमध्रुवम्॥","t":"satkāramānapūjārthaṃ tapo dambhena caiva yat|\nkriyate tadiha proktaṃ rājasaṃ calamadhruvam||","e":"Religion shown in act of proud display\nTo win good entertainment, worship, fame,\nSuch--say I--is of Rajas, rash and vain."},
{"c":17,"v":19,"d":"मूढग्राहेणात्मनो यत्पीडया क्रियते तपः।\nपरस्योत्सादनार्थं वा तत्तामसमुदाहृतम्॥","t":"mūḍhagrāheṇātmano yatpīḍayā kriyate tapaḥ|\nparasyotsādanārthaṃ vā tattāmasamudāhṛtam||","e":"Religion followed by a witless will\nTo torture self, or come at power to hurt\nAnother,--'tis of Tamas, dark and ill."},
{"c":17,"v":20,"d":"दातव्यमिति यद्दानं दीयतेऽनुपकारिणे।\nदेशे काले च पात्रे च तद्दानं सात्त्विकं स्मृतम्॥","t":"dātavyamiti yaddānaṃ dīyate'nupakāriṇe|\ndeśe kāle ca pātre ca taddānaṃ sāttvikaṃ smṛtam||","e":"The gift lovingly given, when one shall say\n\"Now must I gladly give!\" when he who takes\nCan render nothing back; made in due place,\nDue time, and to a meet recipient,\nIs gift of Sattwan, fair and profitable."},
{"c":17,"v":21,"d":"यत्तु प्रत्युपकारार्थं फलमुद्दिश्य वा पुनः।\nदीयते च परिक्लिष्टं तद्दानं राजसं स्मृतम्॥","t":"yattu pratyupakārārthaṃ phalamuddiśya vā punaḥ|\ndīyate ca parikliṣṭaṃ taddānaṃ rājasaṃ smṛtam||","e":"The gift selfishly given, where to receive\nIs hoped again, or when some end is sought,\nOr where the gift is proffered with a grudge,\nThis is of Rajas, stained with impulse, ill."},
{"c":17,"v":22,"d":"अदेशकाले यद्दानमपात्रेभ्यश्च दीयते।\nअसत्कृतमवज्ञातं तत्तामसमुदाहृतम्॥","t":"adeśakāle yaddānamapātrebhyaśca dīyate|\nasatkṛtamavajñātaṃ tattāmasamudāhṛtam||","e":"The gift churlishly flung, at evil time,\nIn wrongful place, to base recipient,\nMade in disdain or harsh unkindliness,\nIs gift of Tamas, dark; it doth not bless!"},
{"c":17,"v":23,"d":"तत्सदिति निर्देशो ब्रह्मणस्त्रिविधः स्मृतः।\nब्राह्मणास्तेन वेदाश्च यज्ञाश्च विहिताः पुरा॥","t":"tatsaditi nirdeśo brahmaṇastrividhaḥ smṛtaḥ|\nbrāhmaṇāstena vedāśca yajñāśca vihitāḥ purā||","e":"","g":[23,24,25,26,27,28]},
{"c":17,"v":24,"d":"तस्मादोमित्युदाहृत्य यज्ञदानतपःक्रियाः।\nप्रवर्तन्ते विधानोक्ताः सततं ब्रह्मवादिनाम्॥","t":"tasmādomityudāhṛtya yajñadānatapaḥkriyāḥ|\npravartante vidhānoktāḥ satataṃ brahmavādinām||","e":"","g":[23,24,25,26,27,28]},
{"c":17,"v":25,"d":"तदित्यनभिसन्धाय फलं यज्ञतपःक्रियाः।\nदानक्रियाश्च विविधाः क्रियन्ते मोक्षकाङ्क्षि॥","t":"tadityanabhisandhāya phalaṃ yajñatapaḥkriyāḥ|\ndānakriyāśca vividhāḥ kriyante mokṣakāṅkṣi||","e":"","g":[23,24,25,26,27,28]},
{"c":17,"v":26,"d":"सद्भावे साधुभावे च सदित्येतत्प्रयुज्यते।\nप्रशस्ते कर्मणि तथा सच्छब्दः पार्थ युज्यते॥","t":"sadbhāve sādhubhāve ca sadityetatprayujyate|\npraśaste karmaṇi tathā sacchabdaḥ pārtha yujyate||","e":"","g":[23,24,25,26,27,28]},
{"c":17,"v":27,"d":"यज्ञे तपसि दाने च स्थितिः सदिति चोच्यते।\nकर्म चैव तदर्थीयं सदित्येवाभिधीयते॥","t":"yajñe tapasi dāne ca sthitiḥ saditi cocyate|\nkarma caiva tadarthīyaṃ sadityevābhidhīyate||","e":"","g":[23,24,25,26,27,28]},
{"c":17,"v":28,"d":"अश्रद्धया हुतं दत्तं तपस्तप्तं कृतं च यत्।\nअसदित्युच्यते पार्थ न च तत्प्रेत्य नो इह॥","t":"aśraddhayā hutaṃ dattaṃ tapastaptaṃ kṛtaṃ ca yat|\nasadityucyate pārtha na ca tatpretya no iha||","e":"","g":[23,24,25,26,27,28]},
{"c":18,"v":1,"d":"अर्जुन उवाच\nसंन्यासस्य महाबाहो तत्त्वमिच्छामि वेदितुम्।\nत्यागस्य च हृषीकेश पृथक्केशिनिषूदन॥","t":"arjuna uvāca\nsaṃnyāsasya mahābāho tattvamicchāmi veditum|\ntyāgasya ca hṛṣīkeśa pṛthakkeśiniṣūdana||","e":"Arjuna.\nFain would I better know, Thou Glorious One!\nThe very truth--Heart's Lord!--of Sannyas,\nAbstention; and enunciation, Lord!\nTyaga; and what separates these twain!"},
{"c":18,"v":2,"d":"श्री भगवानुवाच\nकाम्यानां कर्मणां न्यासं संन्यासं कवयो विदुः।\nसर्वकर्मफलत्यागं प्राहुस्त्यागं विचक्षणाः॥","t":"śrī bhagavānuvāca\nkāmyānāṃ karmaṇāṃ nyāsaṃ saṃnyāsaṃ kavayo viduḥ|\nsarvakarmaphalatyāgaṃ prāhustyāgaṃ vicakṣaṇāḥ||","e":"Krishna.\nThe poets rightly teach that Sannyas\nIs the foregoing of all acts which spring\nOut of desire; and their wisest say\nTyaga is renouncing fruit of acts."},
{"c":18,"v":3,"d":"त्याज्यं दोषवदित्येके कर्म प्राहुर्मनीषिणः।\nयज्ञदानतपःकर्म न त्याज्यमिति चापरे॥","t":"tyājyaṃ doṣavadityeke karma prāhurmanīṣiṇaḥ|\nyajñadānatapaḥkarma na tyājyamiti cāpare||","e":"There be among the saints some who have held\nAll action sinful, and to be renounced;\nAnd some who answer, \"Nay! the goodly acts--\nAs worship, penance, alms--must be performed!\""},
{"c":18,"v":4,"d":"निश्चयं श्रृणु मे तत्र त्यागे भरतसत्तम।\nत्यागो हि पुरुषव्याघ्र त्रिविधः संप्रकीर्तितः॥","t":"niścayaṃ śrṛṇu me tatra tyāge bharatasattama|\ntyāgo hi puruṣavyāghra trividhaḥ saṃprakīrtitaḥ||","e":"Hear now My sentence, Best of Bharatas!\n'Tis well set forth, O Chaser of thy Foes!\nRenunciation is of threefold form,"},
{"c":18,"v":5,"d":"यज्ञदानतपःकर्म न त्याज्यं कार्यमेव तत्।\nयज्ञो दानं तपश्चैव पावनानि मनीषिणाम्॥","t":"yajñadānatapaḥkarma na tyājyaṃ kāryameva tat|\nyajño dānaṃ tapaścaiva pāvanāni manīṣiṇām||","e":"And Worship, Penance, Alms, not to be stayed;\nNay, to be gladly done; for all those three\nAre purifying waters for true souls!"},
{"c":18,"v":6,"d":"एतान्यपि तु कर्माणि सङ्गं त्यक्त्वा फलानि च।\nकर्तव्यानीति मे पार्थ निश्िचतं मतमुत्तमम्॥","t":"etānyapi tu karmāṇi saṅgaṃ tyaktvā phalāni ca|\nkartavyānīti me pārtha niścataṃ matamuttamam||","e":"Yet must be practised even those high works\nIn yielding up attachment, and all fruit\nProduced by works. This is My judgment, Prince!\nThis My insuperable and fixed decree!"},
{"c":18,"v":7,"d":"नियतस्य तु संन्यासः कर्मणो नोपपद्यते।\nमोहात्तस्य परित्यागस्तामसः परिकीर्तितः॥","t":"niyatasya tu saṃnyāsaḥ karmaṇo nopapadyate|\nmohāttasya parityāgastāmasaḥ parikīrtitaḥ||","e":"Abstaining from a work by right prescribed\nNever is meet! So to abstain doth spring\nFrom \"Darkness,\" and Delusion teacheth it."},
{"c":18,"v":8,"d":"दुःखमित्येव यत्कर्म कायक्लेशभयात्त्यजेत्।\nस कृत्वा राजसं त्यागं नैव त्यागफलं लभेत्॥","t":"duḥkhamityeva yatkarma kāyakleśabhayāttyajet|\nsa kṛtvā rājasaṃ tyāgaṃ naiva tyāgaphalaṃ labhet||","e":"Abstaining from a work grievous to flesh,\nWhen one saith \"'Tis unpleasing!\" this is null!\nSuch an one acts from \"passion;\" nought of gain\nWins his Renunciation!"},
{"c":18,"v":9,"d":"कार्यमित्येव यत्कर्म नियतं क्रियतेऽर्जुन।\nसङ्गं त्यक्त्वा फलं चैव स त्यागः सात्त्विको मतः॥","t":"kāryamityeva yatkarma niyataṃ kriyate'rjuna|\nsaṅgaṃ tyaktvā phalaṃ caiva sa tyāgaḥ sāttviko mataḥ||","e":"But, Arjun!\nAbstaining from attachment to the work,\nAbstaining from rewardment in the work,\nWhile yet one doeth it full faithfully,\nSaying, \"Tis right to do!\" that is \"true \" act\nAnd abstinence!"},
{"c":18,"v":10,"d":"न द्वेष्ट्यकुशलं कर्म कुशले नानुषज्जते।\nत्यागी सत्त्वसमाविष्टो मेधावी छिन्नसंशयः॥","t":"na dveṣṭyakuśalaṃ karma kuśale nānuṣajjate|\ntyāgī sattvasamāviṣṭo medhāvī chinnasaṃśayaḥ||","e":"Who doeth duties so,\nUnvexed if his work fail, if it succeed\nUnflattered, in his own heart justified,\nQuit of debates and doubts, his is \"true\" act:"},
{"c":18,"v":11,"d":"न हि देहभृता शक्यं त्यक्तुं कर्माण्यशेषतः।\nयस्तु कर्मफलत्यागी स त्यागीत्यभिधीयते॥","t":"na hi dehabhṛtā śakyaṃ tyaktuṃ karmāṇyaśeṣataḥ|\nyastu karmaphalatyāgī sa tyāgītyabhidhīyate||","e":"For, being in the body, none may stand\nWholly aloof from act; yet, who abstains\nFrom profit of his acts is abstinent."},
{"c":18,"v":12,"d":"अनिष्टमिष्टं मिश्रं च त्रिविधं कर्मणः फलम्।\nभवत्यत्यागिनां प्रेत्य न तु संन्यासिनां क्वचित्॥","t":"aniṣṭamiṣṭaṃ miśraṃ ca trividhaṃ karmaṇaḥ phalam|\nbhavatyatyāgināṃ pretya na tu saṃnyāsināṃ kvacit||","e":"The fruit of labours, in the lives to come,\nIs threefold for all men,--Desirable,\nAnd Undesirable, and mixed of both;\nBut no fruit is at all where no work was."},
{"c":18,"v":13,"d":"पञ्चैतानि महाबाहो कारणानि निबोध मे।\nसांख्ये कृतान्ते प्रोक्तानि सिद्धये सर्वकर्मणाम्॥","t":"pañcaitāni mahābāho kāraṇāni nibodha me|\nsāṃkhye kṛtānte proktāni siddhaye sarvakarmaṇām||","e":"Hear from me, Long-armed Lord! the makings five\nWhich go to every act, in Sankhya taught\nAs necessary."},
{"c":18,"v":14,"d":"अधिष्ठानं तथा कर्ता करणं च पृथग्विधम्।\nविविधाश्च पृथक्चेष्टा दैवं चैवात्र पञ्चमम्॥","t":"adhiṣṭhānaṃ tathā kartā karaṇaṃ ca pṛthagvidham|\nvividhāśca pṛthakceṣṭā daivaṃ caivātra pañcamam||","e":"First the force; and then\nThe agent; next, the various instruments;\nFourth, the especial effort; fifth, the God."},
{"c":18,"v":15,"d":"शरीरवाङ्मनोभिर्यत्कर्म प्रारभते नरः।\nन्याय्यं वा विपरीतं वा पञ्चैते तस्य हेतवः॥","t":"śarīravāṅmanobhiryatkarma prārabhate naraḥ|\nnyāyyaṃ vā viparītaṃ vā pañcaite tasya hetavaḥ||","e":"What work soever any mortal doth\nOf body, mind, or speech, evil or good,\nBy these five doth he that."},
{"c":18,"v":16,"d":"तत्रैवं सति कर्तारमात्मानं केवलं तु यः।\nपश्यत्यकृतबुद्धित्वान्न स पश्यति दुर्मतिः॥","t":"tatraivaṃ sati kartāramātmānaṃ kevalaṃ tu yaḥ|\npaśyatyakṛtabuddhitvānna sa paśyati durmatiḥ||","e":"Which being thus,\nWhoso, for lack of knowledge, seeth himself\nAs the sole actor, knoweth nought at all\nAnd seeth nought."},
{"c":18,"v":17,"d":"यस्य नाहंकृतो भावो बुद्धिर्यस्य न लिप्यते।\nहत्वापि स इमाँल्लोकान्न हन्ति न निबध्यते॥","t":"yasya nāhaṃkṛto bhāvo buddhiryasya na lipyate|\nhatvāpi sa imām̐llokānna hanti na nibadhyate||","e":"Therefore, I say, if one--\nHolding aloof from self--with unstained mind\nShould slay all yonder host, being bid to slay,\nHe doth not slay; he is not bound thereby!"},
{"c":18,"v":18,"d":"ज्ञानं ज्ञेयं परिज्ञाता त्रिविधा कर्मचोदना।\nकरणं कर्म कर्तेति त्रिविधः कर्मसंग्रहः॥","t":"jñānaṃ jñeyaṃ parijñātā trividhā karmacodanā|\nkaraṇaṃ karma karteti trividhaḥ karmasaṃgrahaḥ||","e":"Knowledge, the thing known, and the mind which knows,\nThese make the threefold starting-ground of act.\nThe act, the actor, and the instrument,\nThese make the threefold total of the deed."},
{"c":18,"v":19,"d":"ज्ञानं कर्म च कर्ता च त्रिधैव गुणभेदतः।\nप्रोच्यते गुणसंख्याने यथावच्छृणु तान्यपि॥","t":"jñānaṃ karma ca kartā ca tridhaiva guṇabhedataḥ|\nprocyate guṇasaṃkhyāne yathāvacchṛṇu tānyapi||","e":"But knowledge, agent, act, are differenced\nBy three dividing qualities. Hear now\nWhich be the qualities dividing them."},
{"c":18,"v":20,"d":"सर्वभूतेषु येनैकं भावमव्ययमीक्षते।\nअविभक्तं विभक्तेषु तज्ज्ञानं विद्धि सात्त्विकम्॥","t":"sarvabhūteṣu yenaikaṃ bhāvamavyayamīkṣate|\navibhaktaṃ vibhakteṣu tajjñānaṃ viddhi sāttvikam||","e":"There is \"true\" Knowledge. Learn thou it is this:\nTo see one changeless Life in all the Lives,\nAnd in the Separate, One Inseparable."},
{"c":18,"v":21,"d":"पृथक्त्वेन तु यज्ज्ञानं नानाभावान्पृथग्विधान्।\nवेत्ति सर्वेषु भूतेषु तज्ज्ञानं विद्धि राजसम्॥","t":"pṛthaktvena tu yajjñānaṃ nānābhāvānpṛthagvidhān|\nvetti sarveṣu bhūteṣu tajjñānaṃ viddhi rājasam||","e":"There is imperfect Knowledge: that which sees\nThe separate existences apart,\nAnd, being separated, holds them real."},
{"c":18,"v":22,"d":"यत्तु कृत्स्नवदेकस्मिन्कार्ये सक्तमहैतुकम्।\nअतत्त्वार्थवदल्पं च तत्तामसमुदाहृतम्॥","t":"yattu kṛtsnavadekasminkārye saktamahaitukam|\natattvārthavadalpaṃ ca tattāmasamudāhṛtam||","e":"There is false Knowledge: that which blindly clings\nTo one as if 'twere all, seeking no Cause,\nDeprived of light, narrow, and dull, and \"dark.\""},
{"c":18,"v":23,"d":"नियतं सङ्गरहितमरागद्वेषतः कृतम्।\nअफलप्रेप्सुना कर्म यत्तत्सात्त्विकमुच्यते॥","t":"niyataṃ saṅgarahitamarāgadveṣataḥ kṛtam|\naphalaprepsunā karma yattatsāttvikamucyate||","e":"There is \"right\" Action: that which being enjoined--\nIs wrought without attachment, passionlessly,\nFor duty, not for love, nor hate, nor gain."},
{"c":18,"v":24,"d":"यत्तु कामेप्सुना कर्म साहङ्कारेण वा पुनः।\nक्रियते बहुलायासं तद्राजसमुदाहृतम्॥","t":"yattu kāmepsunā karma sāhaṅkāreṇa vā punaḥ|\nkriyate bahulāyāsaṃ tadrājasamudāhṛtam||","e":"There is \"vain\" Action: that which men pursue\nAching to satisfy desires, impelled\nBy sense of self, with all-absorbing stress:\nThis is of Rajas--passionate and vain."},
{"c":18,"v":25,"d":"अनुबन्धं क्षयं हिंसामनपेक्ष्य च पौरुषम्।\nमोहादारभ्यते कर्म यत्तत्तामसमुच्यते॥","t":"anubandhaṃ kṣayaṃ hiṃsāmanapekṣya ca pauruṣam|\nmohādārabhyate karma yattattāmasamucyate||","e":"There is \"dark\" Action: when one doth a thing\nHeedless of issues, heedless of the hurt\nOr wrong for others, heedless if he harm\nHis own soul--'tis of Tamas, black and bad!"},
{"c":18,"v":26,"d":"मुक्तसङ्गोऽनहंवादी धृत्युत्साहसमन्वितः।\nसिद्ध्यसिद्ध्योर्निर्विकारः कर्ता सात्त्विक उच्यते॥","t":"muktasaṅgo'nahaṃvādī dhṛtyutsāhasamanvitaḥ|\nsiddhyasiddhyornirvikāraḥ kartā sāttvika ucyate||","e":"There is the \"rightful\"doer. He who acts\nFree from self-seeking, humble, resolute,\nSteadfast, in good or evil hap the same,\nContent to do aright-he \"truly\" acts."},
{"c":18,"v":27,"d":"रागी कर्मफलप्रेप्सुर्लुब्धो हिंसात्मकोऽशुचिः।\nहर्षशोकान्वितः कर्ता राजसः परिकीर्तितः॥","t":"rāgī karmaphalaprepsurlubdho hiṃsātmako'śuciḥ|\nharṣaśokānvitaḥ kartā rājasaḥ parikīrtitaḥ||","e":"There is th' \"impassioned\" doer. He that works\nFrom impulse, seeking profit, rude and bold\nTo overcome, unchastened; slave by turns\nOf sorrow and of joy: of Rajas he!"},
{"c":18,"v":28,"d":"अयुक्तः प्राकृतः स्तब्धः शठो नैष्कृतिकोऽलसः।\nविषादी दीर्घसूत्री च कर्ता तामस उच्यते॥","t":"ayuktaḥ prākṛtaḥ stabdhaḥ śaṭho naiṣkṛtiko'lasaḥ|\nviṣādī dīrghasūtrī ca kartā tāmasa ucyate||","e":"And there be evil doers; loose of heart,\nLow-minded, stubborn, fraudulent, remiss,\nDull, slow, despondent--children of the \"dark.\""},
{"c":18,"v":29,"d":"बुद्धेर्भेदं धृतेश्चैव गुणतस्त्रिविधं श्रृणु।\nप्रोच्यमानमशेषेण पृथक्त्वेन धनञ्जय॥","t":"buddherbhedaṃ dhṛteścaiva guṇatastrividhaṃ śrṛṇu|\nprocyamānamaśeṣeṇa pṛthaktvena dhanañjaya||","e":"Hear, too, of Intellect and Steadfastness\nThe threefold separation, Conqueror-Prince!\nHow these are set apart by Qualities."},
{"c":18,"v":30,"d":"प्रवृत्तिं च निवृत्तिं च कार्याकार्ये भयाभये।\nबन्धं मोक्षं च या वेत्ति बुद्धिः सा पार्थ सात्त्विकी॥","t":"pravṛttiṃ ca nivṛttiṃ ca kāryākārye bhayābhaye|\nbandhaṃ mokṣaṃ ca yā vetti buddhiḥ sā pārtha sāttvikī||","e":"Good is the Intellect which comprehends\nThe coming forth and going back of life,\nWhat must be done, and what must not be done,\nWhat should be feared, and what should not be feared,\nWhat binds and what emancipates the soul:\nThat is of Sattwan, Prince! of \"soothfastness.\""},
{"c":18,"v":31,"d":"यया धर्ममधर्मं च कार्यं चाकार्यमेव च।\nअयथावत्प्रजानाति बुद्धिः सा पार्थ राजसी॥","t":"yayā dharmamadharmaṃ ca kāryaṃ cākāryameva ca|\nayathāvatprajānāti buddhiḥ sā pārtha rājasī||","e":"Marred is the Intellect which, knowing right\nAnd knowing wrong, and what is well to do\nAnd what must not be done, yet understands\nNought with firm mind, nor as the calm truth is:\nThis is of Rajas, Prince! and \"passionate!\""},
{"c":18,"v":32,"d":"अधर्मं धर्ममिति या मन्यते तमसाऽऽवृता।\nसर्वार्थान्विपरीतांश्च बुद्धिः सा पार्थ तामसी॥","t":"adharmaṃ dharmamiti yā manyate tamasā''vṛtā|\nsarvārthānviparītāṃśca buddhiḥ sā pārtha tāmasī||","e":"Evil is Intellect which, wrapped in gloom,\nLooks upon wrong as right, and sees all things\nContrariwise of Truth. O Pritha's Son!\nThat is of Tamas, \"dark\" and desperate!"},
{"c":18,"v":33,"d":"धृत्या यया धारयते मनःप्राणेन्द्रियक्रियाः।\nयोगेनाव्यभिचारिण्या धृतिः सा पार्थ सात्त्विकी॥","t":"dhṛtyā yayā dhārayate manaḥprāṇendriyakriyāḥ|\nyogenāvyabhicāriṇyā dhṛtiḥ sā pārtha sāttvikī||","e":"Good is the steadfastness whereby a man\nMasters his beats of heart, his very breath\nOf life, the action of his senses; fixed\nIn never-shaken faith and piety:\nThat is of Sattwan, Prince! \"soothfast\" and fair!"},
{"c":18,"v":34,"d":"यया तु धर्मकामार्थान् धृत्या धारयतेऽर्जुन।\nप्रसङ्गेन फलाकाङ्क्षी धृतिः सा पार्थ राजसी॥","t":"yayā tu dharmakāmārthān dhṛtyā dhārayate'rjuna|\nprasaṅgena phalākāṅkṣī dhṛtiḥ sā pārtha rājasī||","e":"Stained is the steadfastness whereby a man\nHolds to his duty, purpose, effort, end,\nFor life's sake, and the love of goods to gain,\nArjuna! 'tis of Rajas, passion-stamped!"},
{"c":18,"v":35,"d":"यया स्वप्नं भयं शोकं विषादं मदमेव च।\nन विमुञ्चति दुर्मेधा धृतिः सा पार्थ तामसी॥","t":"yayā svapnaṃ bhayaṃ śokaṃ viṣādaṃ madameva ca|\nna vimuñcati durmedhā dhṛtiḥ sā pārtha tāmasī||","e":"Sad is the steadfastness wherewith the fool\nCleaves to his sloth, his sorrow, and his fears,\nHis folly and despair. This--Pritha's Son!--\nIs born of Tamas, \"dark\" and miserable!"},
{"c":18,"v":36,"d":"सुखं त्विदानीं त्रिविधं श्रृणु मे भरतर्षभ।\nअभ्यासाद्रमते यत्र दुःखान्तं च निगच्छति॥","t":"sukhaṃ tvidānīṃ trividhaṃ śrṛṇu me bharatarṣabha|\nabhyāsādramate yatra duḥkhāntaṃ ca nigacchati||","e":"Hear further, Chief of Bharatas! from Me\nThe threefold kinds of Pleasure which there be.\nGood Pleasure is the pleasure that endures,\nBanishing pain for aye;"},
{"c":18,"v":37,"d":"यत्तदग्रे विषमिव परिणामेऽमृतोपमम्।\nतत्सुखं सात्त्विकं प्रोक्तमात्मबुद्धिप्रसादजम्॥","t":"yattadagre viṣamiva pariṇāme'mṛtopamam|\ntatsukhaṃ sāttvikaṃ proktamātmabuddhiprasādajam||","e":"bitter at first\nAs poison to the soul, but afterward\nSweet as the taste of Amrit. Drink of that!\nIt springeth in the Spirit's deep content."},
{"c":18,"v":38,"d":"विषयेन्द्रियसंयोगाद्यत्तदग्रेऽमृतोपमम्।\nपरिणामे विषमिव तत्सुखं राजसं स्मृतम्॥","t":"viṣayendriyasaṃyogādyattadagre'mṛtopamam|\npariṇāme viṣamiva tatsukhaṃ rājasaṃ smṛtam||","e":"And painful Pleasure springeth from the bond\nBetween the senses and the sense-world. Sweet\nAs Amrit is its first taste, but its last\nBitter as poison. 'Tis of Rajas, Prince!"},
{"c":18,"v":39,"d":"यदग्रे चानुबन्धे च सुखं मोहनमात्मनः।\nनिद्रालस्यप्रमादोत्थं तत्तामसमुदाहृतम्॥","t":"yadagre cānubandhe ca sukhaṃ mohanamātmanaḥ|\nnidrālasyapramādotthaṃ tattāmasamudāhṛtam||","e":"And foul and \"dark\" the Pleasure is which springs\nFrom sloth and sin and foolishness; at first\nAnd at the last, and all the way of life\nThe soul bewildering. 'Tis of Tamas, Prince!"},
{"c":18,"v":40,"d":"न तदस्ति पृथिव्यां वा दिवि देवेषु वा पुनः।\nसत्त्वं प्रकृतिजैर्मुक्तं यदेभिः स्यात्ित्रभिर्गुणैः॥","t":"na tadasti pṛthivyāṃ vā divi deveṣu vā punaḥ|\nsattvaṃ prakṛtijairmuktaṃ yadebhiḥ syāttrabhirguṇaiḥ||","e":"For nothing lives on earth, nor 'midst the gods\nIn utmost heaven, but hath its being bound\nWith these three Qualities, by Nature framed."},
{"c":18,"v":41,"d":"ब्राह्मणक्षत्रियविशां शूद्राणां च परंतप।\nकर्माणि प्रविभक्तानि स्वभावप्रभवैर्गुणैः॥","t":"brāhmaṇakṣatriyaviśāṃ śūdrāṇāṃ ca paraṃtapa|\nkarmāṇi pravibhaktāni svabhāvaprabhavairguṇaiḥ||","e":"The work of Brahmans, Kshatriyas, Vaisyas,\nAnd Sudras, O thou Slayer of thy Foes!\nIs fixed by reason of the Qualities\nPlanted in each:"},
{"c":18,"v":42,"d":"शमो दमस्तपः शौचं क्षान्तिरार्जवमेव च।\nज्ञानं विज्ञानमास्तिक्यं ब्रह्मकर्म स्वभावजम्॥","t":"śamo damastapaḥ śaucaṃ kṣāntirārjavameva ca|\njñānaṃ vijñānamāstikyaṃ brahmakarma svabhāvajam||","e":"A Brahman's virtues, Prince!\nBorn of his nature, are serenity,\nSelf-mastery, religion, purity,\nPatience, uprightness, learning, and to know\nThe truth of things which be."},
{"c":18,"v":43,"d":"शौर्यं तेजो धृतिर्दाक्ष्यं युद्धे चाप्यपलायनम्।\nदानमीश्वरभावश्च क्षात्रं कर्म स्वभावजम्॥","t":"śauryaṃ tejo dhṛtirdākṣyaṃ yuddhe cāpyapalāyanam|\ndānamīśvarabhāvaśca kṣātraṃ karma svabhāvajam||","e":"A Kshatriya's pride,\nBorn of his nature, lives in valour, fire,\nConstancy, skilfulness, spirit in fight,\nAnd open-handedness and noble mien,\nAs of a lord of men."},
{"c":18,"v":44,"d":"कृषिगौरक्ष्यवाणिज्यं वैश्यकर्म स्वभावजम्।\nपरिचर्यात्मकं कर्म शूद्रस्यापि स्वभावजम्॥","t":"kṛṣigaurakṣyavāṇijyaṃ vaiśyakarma svabhāvajam|\nparicaryātmakaṃ karma śūdrasyāpi svabhāvajam||","e":"A Vaisya's task,\nBorn with his nature, is to till the ground,\nTend cattle, venture trade. A Sudra's state,\nSuiting his nature, is to minister."},
{"c":18,"v":45,"d":"स्वे स्वे कर्मण्यभिरतः संसिद्धिं लभते नरः।\nस्वकर्मनिरतः सिद्धिं यथा विन्दति तच्छृणु॥","t":"sve sve karmaṇyabhirataḥ saṃsiddhiṃ labhate naraḥ|\nsvakarmanirataḥ siddhiṃ yathā vindati tacchṛṇu||","e":"Whoso performeth--diligent, content--\nThe work allotted him, whate'er it be,\nLays hold of perfectness! Hear how a man\nFindeth perfection, being so content:"},
{"c":18,"v":46,"d":"यतः प्रवृत्तिर्भूतानां येन सर्वमिदं ततम्।\nस्वकर्मणा तमभ्यर्च्य सिद्धिं विन्दति मानवः॥","t":"yataḥ pravṛttirbhūtānāṃ yena sarvamidaṃ tatam|\nsvakarmaṇā tamabhyarcya siddhiṃ vindati mānavaḥ||","e":"He findeth it through worship--wrought by work--\nOf Him that is the Source of all which lives,\nOf HIM by Whom the universe was stretched."},
{"c":18,"v":47,"d":"श्रेयान्स्वधर्मो विगुणः परधर्मात्स्वनुष्ठितात्।\nस्वभावनियतं कर्म कुर्वन्नाप्नोति किल्बिषम्॥","t":"śreyānsvadharmo viguṇaḥ paradharmātsvanuṣṭhitāt|\nsvabhāvaniyataṃ karma kurvannāpnoti kilbiṣam||","e":"Better thine own work is, though done with fault,\nThan doing others' work, ev'n excellently.\nHe shall not fall in sin who fronts the task\nSet him by Nature's hand!"},
{"c":18,"v":48,"d":"सहजं कर्म कौन्तेय सदोषमपि न त्यजेत्।\nसर्वारम्भा हि दोषेण धूमेनाग्निरिवावृताः॥","t":"sahajaṃ karma kaunteya sadoṣamapi na tyajet|\nsarvārambhā hi doṣeṇa dhūmenāgnirivāvṛtāḥ||","e":"Let no man leave\nHis natural duty, Prince! though it bear blame!\nFor every work hath blame, as every flame\nIs wrapped in smoke!"},
{"c":18,"v":49,"d":"असक्तबुद्धिः सर्वत्र जितात्मा विगतस्पृहः।\nनैष्कर्म्यसिद्धिं परमां संन्यासेनाधिगच्छति॥","t":"asaktabuddhiḥ sarvatra jitātmā vigataspṛhaḥ|\nnaiṣkarmyasiddhiṃ paramāṃ saṃnyāsenādhigacchati||","e":"Only that man attains\nPerfect surcease of work whose work was wrought\nWith mind unfettered, soul wholly subdued,\nDesires for ever dead, results renounced."},
{"c":18,"v":50,"d":"सिद्धिं प्राप्तो यथा ब्रह्म तथाप्नोति निबोध मे।\nसमासेनैव कौन्तेय निष्ठा ज्ञानस्य या परा॥","t":"siddhiṃ prāpto yathā brahma tathāpnoti nibodha me|\nsamāsenaiva kaunteya niṣṭhā jñānasya yā parā||","e":"Learn from me, Son of Kunti! also this,\nHow one, attaining perfect peace, attains\nBRAHM, the supreme, the highest height of all!"},
{"c":18,"v":51,"d":"बुद्ध्या विशुद्धया युक्तो धृत्याऽऽत्मानं नियम्य च।\nशब्दादीन् विषयांस्त्यक्त्वा रागद्वेषौ व्युदस्य च॥","t":"buddhyā viśuddhayā yukto dhṛtyā''tmānaṃ niyamya ca|\nśabdādīn viṣayāṃstyaktvā rāgadveṣau vyudasya ca||","e":"Devoted--with a heart grown pure, restrained\nIn lordly self-control, forgoing wiles\nOf song and senses, freed from love and hate,"},
{"c":18,"v":52,"d":"विविक्तसेवी लघ्वाशी यतवाक्कायमानसः।\nध्यानयोगपरो नित्यं वैराग्यं समुपाश्रितः॥","t":"viviktasevī laghvāśī yatavākkāyamānasaḥ|\ndhyānayogaparo nityaṃ vairāgyaṃ samupāśritaḥ||","e":"Dwelling 'mid solitudes, in diet spare,\nWith body, speech, and will tamed to obey,\nEver to holy meditation vowed,\nFrom passions liberate,"},
{"c":18,"v":53,"d":"अहङ्कारं बलं दर्पं कामं क्रोधं परिग्रहम्।\nविमुच्य निर्ममः शान्तो ब्रह्मभूयाय कल्पते॥","t":"ahaṅkāraṃ balaṃ darpaṃ kāmaṃ krodhaṃ parigraham|\nvimucya nirmamaḥ śānto brahmabhūyāya kalpate||","e":"quit of the Self,\nOf arrogance, impatience, anger, pride;\nFreed from surroundings, quiet, lacking nought--\nSuch an one grows to oneness with the BRAHM;"},
{"c":18,"v":54,"d":"ब्रह्मभूतः प्रसन्नात्मा न शोचति न काङ्क्षति।\nसमः सर्वेषु भूतेषु मद्भक्तिं लभते पराम्॥","t":"brahmabhūtaḥ prasannātmā na śocati na kāṅkṣati|\nsamaḥ sarveṣu bhūteṣu madbhaktiṃ labhate parām||","e":"Such an one, growing one with BRAHM, serene,\nSorrows no more, desires no more; his soul,\nEqually loving all that lives, loves well\nMe, Who have made them, and attains to Me."},
{"c":18,"v":55,"d":"भक्त्या मामभिजानाति यावान्यश्चास्मि तत्त्वतः।\nततो मां तत्त्वतो ज्ञात्वा विशते तदनन्तरम्॥","t":"bhaktyā māmabhijānāti yāvānyaścāsmi tattvataḥ|\ntato māṃ tattvato jñātvā viśate tadanantaram||","e":"By this same love and worship doth he know\nMe as I am, how high and wonderful,\nAnd knowing, straightway enters into Me."},
{"c":18,"v":56,"d":"सर्वकर्माण्यपि सदा कुर्वाणो मद्व्यपाश्रयः।\nमत्प्रसादादवाप्नोति शाश्वतं पदमव्ययम्॥","t":"sarvakarmāṇyapi sadā kurvāṇo madvyapāśrayaḥ|\nmatprasādādavāpnoti śāśvataṃ padamavyayam||","e":"And whatsoever deeds he doeth--fixed\nIn Me, as in his refuge--he hath won\nFor ever and for ever by My grace\nTh' Eternal Rest!"},
{"c":18,"v":57,"d":"चेतसा सर्वकर्माणि मयि संन्यस्य मत्परः।\nबुद्धियोगमुपाश्रित्य मच्चित्तः सततं भव॥","t":"cetasā sarvakarmāṇi mayi saṃnyasya matparaḥ|\nbuddhiyogamupāśritya maccittaḥ satataṃ bhava||","e":"So win thou! In thy thoughts\nDo all thou dost for Me! Renounce for Me!\nSacrifice heart and mind and will to Me!\nLive in the faith of Me!"},
{"c":18,"v":58,"d":"मच्चित्तः सर्वदुर्गाणि मत्प्रसादात्तरिष्यसि।\nअथ चेत्त्वमहङ्कारान्न श्रोष्यसि विनङ्क्ष्यसि॥","t":"maccittaḥ sarvadurgāṇi matprasādāttariṣyasi|\natha cettvamahaṅkārānna śroṣyasi vinaṅkṣyasi||","e":"In faith of Me\nAll dangers thou shalt vanquish, by My grace;\nBut, trusting to thyself and heeding not,\nThou can'st but perish!"},
{"c":18,"v":59,"d":"यदहङ्कारमाश्रित्य न योत्स्य इति मन्यसे।\nमिथ्यैष व्यवसायस्ते प्रकृतिस्त्वां नियोक्ष्यति॥","t":"yadahaṅkāramāśritya na yotsya iti manyase|\nmithyaiṣa vyavasāyaste prakṛtistvāṃ niyokṣyati||","e":"If this day thou say'st,\nRelying on thyself, \"I will not fight!\"\nVain will the purpose prove! thy qualities\nWould spur thee to the war."},
{"c":18,"v":60,"d":"स्वभावजेन कौन्तेय निबद्धः स्वेन कर्मणा।\nकर्तुं नेच्छसि यन्मोहात्करिष्यस्यवशोऽपि तत्॥","t":"svabhāvajena kaunteya nibaddhaḥ svena karmaṇā|\nkartuṃ necchasi yanmohātkariṣyasyavaśo'pi tat||","e":"What thou dost shun,\nMisled by fair illusions, thou wouldst seek\nAgainst thy will, when the task comes to thee\nWaking the promptings in thy nature set."},
{"c":18,"v":61,"d":"ईश्वरः सर्वभूतानां हृद्देशेऽर्जुन तिष्ठति।\nभ्रामयन्सर्वभूतानि यन्त्रारूढानि मायया॥","t":"īśvaraḥ sarvabhūtānāṃ hṛddeśe'rjuna tiṣṭhati|\nbhrāmayansarvabhūtāni yantrārūḍhāni māyayā||","e":"There lives a Master in the hearts of men\nMaketh their deeds, by subtle pulling--strings,\nDance to what tune HE will."},
{"c":18,"v":62,"d":"तमेव शरणं गच्छ सर्वभावेन भारत।\nतत्प्रसादात्परां शान्तिं स्थानं प्राप्स्यसि शाश्वतम्॥","t":"tameva śaraṇaṃ gaccha sarvabhāvena bhārata|\ntatprasādātparāṃ śāntiṃ sthānaṃ prāpsyasi śāśvatam||","e":"With all thy soul\nTrust Him, and take Him for thy succour, Prince!\nSo--only so, Arjuna!--shalt thou gain--\nBy grace of Him--the uttermost repose,\nThe Eternal Place!"},
{"c":18,"v":63,"d":"इति ते ज्ञानमाख्यातं गुह्याद्गुह्यतरं मया।\nविमृश्यैतदशेषेण यथेच्छसि तथा कुरु॥","t":"iti te jñānamākhyātaṃ guhyādguhyataraṃ mayā|\nvimṛśyaitadaśeṣeṇa yathecchasi tathā kuru||","e":"Thus hath been opened thee\nThis Truth of Truths, the Mystery more hid\nThan any secret mystery. Meditate!\nAnd--as thou wilt--then act!"},
{"c":18,"v":64,"d":"सर्वगुह्यतमं भूयः श्रृणु मे परमं वचः।\nइष्टोऽसि मे दृढमिति ततो वक्ष्यामि ते हितम्॥","t":"sarvaguhyatamaṃ bhūyaḥ śrṛṇu me paramaṃ vacaḥ|\niṣṭo'si me dṛḍhamiti tato vakṣyāmi te hitam||","e":"Nay! but once more\nTake My last word, My utmost meaning have!\nPrecious thou art to Me; right well-beloved!\nListen! I tell thee for thy comfort this."},
{"c":18,"v":65,"d":"मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु।\nमामेवैष्यसि सत्यं ते प्रतिजाने प्रियोऽसि मे॥","t":"manmanā bhava madbhakto madyājī māṃ namaskuru|\nmāmevaiṣyasi satyaṃ te pratijāne priyo'si me||","e":"Give Me thy heart! adore Me! serve Me! cling\nIn faith and love and reverence to Me!\nSo shalt thou come to Me! I promise true,\nFor thou art sweet to Me!"},
{"c":18,"v":66,"d":"सर्वधर्मान्परित्यज्य मामेकं शरणं व्रज।\nअहं त्वा सर्वपापेभ्यो मोक्षयिष्यामि मा शुचः॥","t":"sarvadharmānparityajya māmekaṃ śaraṇaṃ vraja|\nahaṃ tvā sarvapāpebhyo mokṣayiṣyāmi mā śucaḥ||","e":"And let go those--\nRites and writ duties! Fly to Me alone!\nMake Me thy single refuge! I will free\nThy soul from all its sins! Be of good cheer!"},
{"c":18,"v":67,"d":"इदं ते नातपस्काय नाभक्ताय कदाचन।\nन चाशुश्रूषवे वाच्यं न च मां योऽभ्यसूयति॥","t":"idaṃ te nātapaskāya nābhaktāya kadācana|\nna cāśuśrūṣave vācyaṃ na ca māṃ yo'bhyasūyati||","e":"[Hide, the holy Krishna saith,\nThis from him that hath no faith,\nHim that worships not, nor seeks\nWisdom's teaching when she speaks:\nHide it from all men who mock;"},
{"c":18,"v":68,"d":"य इमं परमं गुह्यं मद्भक्तेष्वभिधास्यति।\nभक्ितं मयि परां कृत्वा मामेवैष्यत्यसंशयः॥","t":"ya imaṃ paramaṃ guhyaṃ madbhakteṣvabhidhāsyati|\nbhaktaṃ mayi parāṃ kṛtvā māmevaiṣyatyasaṃśayaḥ||","e":"But, wherever, 'mid the flock\nOf My lovers, one shall teach\nThis divinest, wisest, speech--\nTeaching in the faith to bring\nTruth to them, and offering\nOf all honour unto Me--\nUnto Brahma cometh he!"},
{"c":18,"v":69,"d":"न च तस्मान्मनुष्येषु कश्िचन्मे प्रियकृत्तमः।\nभविता न च मे तस्मादन्यः प्रियतरो भुवि॥","t":"na ca tasmānmanuṣyeṣu kaścanme priyakṛttamaḥ|\nbhavitā na ca me tasmādanyaḥ priyataro bhuvi||","e":"Nay, and nowhere shall ye find\nAny man of all mankind\nDoing dearer deed for Me;\nNor shall any dearer be\nIn My earth."},
{"c":18,"v":70,"d":"अध्येष्यते च य इमं धर्म्यं संवादमावयोः।\nज्ञानयज्ञेन तेनाहमिष्टः स्यामिति मे मतिः॥","t":"adhyeṣyate ca ya imaṃ dharmyaṃ saṃvādamāvayoḥ|\njñānayajñena tenāhamiṣṭaḥ syāmiti me matiḥ||","e":"Yea, furthermore,\nWhoso reads this converse o'er,\nHeld by Us upon the plain,\nPondering piously and fain,\nHe hath paid Me sacrifice!\n(Krishna speaketh in this wise!)"},
{"c":18,"v":71,"d":"श्रद्धावाननसूयश्च श्रृणुयादपि यो नरः।\nसोऽपि मुक्तः शुभाँल्लोकान्प्राप्नुयात्पुण्यकर्मणाम्॥","t":"śraddhāvānanasūyaśca śrṛṇuyādapi yo naraḥ|\nso'pi muktaḥ śubhām̐llokānprāpnuyātpuṇyakarmaṇām||","e":"Yea, and whoso, full of faith,\nHeareth wisely what it saith,\nHeareth meekly,--when he dies,\nSurely shall his spirit rise\nTo those regions where the Blest,\nFree of flesh, in joyance rest.]"},
{"c":18,"v":72,"d":"कच्चिदेतच्छ्रुतं पार्थ त्वयैकाग्रेण चेतसा।\nकच्चिदज्ञानसंमोहः प्रनष्टस्ते धनञ्जय॥","t":"kaccidetacchrutaṃ pārtha tvayaikāgreṇa cetasā|\nkaccidajñānasaṃmohaḥ pranaṣṭaste dhanañjaya||","e":"Hath this been heard by thee, O Indian Prince!\nWith mind intent? hath all the ignorance--\nWhich bred thy trouble--vanished, My Arjun?"},
{"c":18,"v":73,"d":"अर्जुन उवाच\nनष्टो मोहः स्मृतिर्लब्धा त्वत्प्रसादान्मयाच्युत।\nस्थितोऽस्मि गतसन्देहः करिष्ये वचनं तव॥","t":"arjuna uvāca\nnaṣṭo mohaḥ smṛtirlabdhā tvatprasādānmayācyuta|\nsthito'smi gatasandehaḥ kariṣye vacanaṃ tava||","e":"Arjuna.\nTrouble and ignorance are gone! the Light\nHath come unto me, by Thy favour, Lord!\nNow am I fixed! my doubt is fled away!\nAccording to Thy word, so will I do!"},
{"c":18,"v":74,"d":"सञ्जय उवाच\nइत्यहं वासुदेवस्य पार्थस्य च महात्मनः।\nसंवादमिममश्रौषमद्भुतं रोमहर्षणम्॥","t":"sañjaya uvāca\nityahaṃ vāsudevasya pārthasya ca mahātmanaḥ|\nsaṃvādamimamaśrauṣamadbhutaṃ romaharṣaṇam||","e":"Sanjaya.\nThus gathered I the gracious speech of Krishna, O my King!\nThus have I told, with heart a-thrill, this wise and wondrous thing"},
{"c":18,"v":75,"d":"व्यासप्रसादाच्छ्रुतवानेतद्गुह्यमहं परम्।\nयोगं योगेश्वरात्कृष्णात्साक्षात्कथयतः स्वयम्॥","t":"vyāsaprasādācchrutavānetadguhyamahaṃ param|\nyogaṃ yogeśvarātkṛṣṇātsākṣātkathayataḥ svayam||","e":"By great Vyasa's learning writ, how Krishna's self made known\nThe Yoga, being Yoga's Lord. So is the high truth shown!"},
{"c":18,"v":76,"d":"राजन्संस्मृत्य संस्मृत्य संवादमिममद्भुतम्।\nकेशवार्जुनयोः पुण्यं हृष्यामि च मुहुर्मुहुः॥","t":"rājansaṃsmṛtya saṃsmṛtya saṃvādamimamadbhutam|\nkeśavārjunayoḥ puṇyaṃ hṛṣyāmi ca muhurmuhuḥ||","e":"And aye, when I remember, O Lord my King, again\nArjuna and the God in talk, and all this holy strain,\nGreat is my gladness:"},
{"c":18,"v":77,"d":"तच्च संस्मृत्य संस्मृत्य रूपमत्यद्भुतं हरेः।\nविस्मयो मे महान् राजन् हृष्यामि च पुनः पुनः॥","t":"tacca saṃsmṛtya saṃsmṛtya rūpamatyadbhutaṃ hareḥ|\nvismayo me mahān rājan hṛṣyāmi ca punaḥ punaḥ||","e":"when I muse that splendour, passing speech,\nOf Hari, visible and plain, there is no tongue to reach\nMy marvel and my love and bliss."},
{"c":18,"v":78,"d":"यत्र योगेश्वरः कृष्णो यत्र पार्थो धनुर्धरः।\nतत्र श्रीर्विजयो भूतिर्ध्रुवा नीतिर्मतिर्मम॥18.78।","t":"yatra yogeśvaraḥ kṛṣṇo yatra pārtho dhanurdharaḥ|\ntatra śrīrvijayo bhūtirdhruvā nītirmatirmama||18.78|","e":"O Archer-Prince! all hail!\nO Krishna, Lord of Yoga! surely there shall not fail\nBlessing, and victory, and power, for Thy most mighty sake,\nWhere this song comes of Arjun, and how with God he spake."}
];
